    /// **复验 Important 2**：会话的 `PlayObject.MNMval`（`SessionGround.mnm_val`）必须映射进
    /// 脚本侧 `NpcPlayer.mnmval`，脚本跑完再写回——oracle 里说词 `$STR(M*)`（`NormNpc.cs:1548`）
    /// 与 `<QUERYVAL>`（`PlayObject.Base.cs:3436`）读写的是**同一个** `PlayObject.MNMval`
    /// （`PlayObject.cs:543`）。
    ///
    /// 红检：删掉 `npc_player_from_session` 的 `mnm_val` seeding ⇒ 读断言红；
    /// 删掉 `write_back_player_mnmval` 调用/函数体 ⇒ 写回断言红。
    #[test]
    fn npc_player_maps_session_mnmval_both_ways() {
        use mir2_script::engine::ScriptPlayer as _;
        let mut sg = test_session_ground(7);
        sg.mnm_val[9] = 77;
        let vars = npc_vars_from(None, "SKY引擎", 10_000);
        let catalog = game_svr::ability::StdItemCatalog::new();
        let mut rng = |_v: i32| 0;
        {
            let mut p = npc_player_from_session(&mut rng, "hero", &sg, "0", &catalog, &vars);
            assert_eq!(
                p.line_variable_text("<$STR(M9)>"),
                "77",
                "会话 MNMval[9] 必须映射进 NpcPlayer（$STR 300..399）"
            );
            // 脚本 `INC M9 1` 的落点。
            p.set_mnmval(9, 78);
            assert_eq!(p.line_variable_text("<$STR(M9)>"), "78");
            write_back_player_mnmval(&p, &mut sg);
        }
        assert_eq!(sg.mnm_val[9], 78, "脚本写回的 MNMval 必须回到会话");
    }

    /// **T-142 宿主会话接线**：`SaleDeal` / `PlayDiceLabel` / `GameGold` 在 oracle 里是
    /// 同一个 `PlayObject` 的字段（`PlayObject.cs:856/588`），跨 `GotoLable` 天然存活；
    /// 本仓每次 `GotoLable` 重建 `NpcPlayer` ⇒ 必须 seed + write-back，否则
    /// `OPENYBDEAL`（`ExecutionProcessingSys.cs:2345/2346`）/`PLAYDICE`（`:2032`）的副作用
    /// 会在本次调用结束时被丢弃。
    ///
    /// 红检：删掉 `write_back_player_gold_deal` 的 `SaleDeal`/`PlayDiceLabel`/`GameGold`
    /// 任一行（或 `seed_player_gold_deal` 的任一行）⇒ 对应断言红；同函数里 `PlayObject.Gold`
    /// 那一行的牙在 [`take_gold_persists_to_session_gold_through_production_path`]。
    #[test]
    fn t142_gold_deal_seed_and_write_back_round_trip() {
        use mir2_script::engine::ScriptPlayer as _;
        let mut sg = test_session_ground(1);
        sg.game_gold = 150;
        let mut session = ShopSession::default();
        let mut sell_off = game_svr::selloff::SellOffState::default();
        let catalog = game_svr::ability::StdItemCatalog::new();
        let vars = game_svr::npc::NpcVars::default();
        let mut rng = |_v: i32| 0;
        {
            let mut p = npc_player_from_session(&mut rng, "hero", &sg, "0", &catalog, &vars);
            // 脚本 `PLAYDICE ... @dice` / `OPENYBDEAL 100` 的落点。
            p.set_play_dice_label("@dice");
            p.set_sale_deal(true);
            p.set_game_gold(50);
            write_back_player_gold_deal(&p, &mut sg, &mut session, &mut sell_off);
        }
        assert!(sell_off.sale_deal, "SaleDeal 写回 `SellOffState`（真源）");
        assert_eq!(session.play_dice_label.as_deref(), Some("@dice"));
        assert_eq!(sg.game_gold, 50, "GameGold 写回会话（OPENYBDEAL 扣费）");
        // 反向：会话 → `NpcPlayer`（下一次 `GotoLable` 必须看到上一次的副作用）。
        let mut rng = |_v: i32| 0;
        let mut p = npc_player_from_session(&mut rng, "hero", &sg, "0", &catalog, &vars);
        seed_player_gold_deal(&mut p, &session, &sell_off);
        assert!(
            p.sale_deal(),
            "`ActionOfOpenSaleDeal` 的前置读必须看到已开通"
        );
        assert_eq!(p.play_dice_label(), Some("@dice".to_string()));
        assert_eq!(p.game_gold, 50);
    }

    /// **T-142 F1 夹具**：一条商人脚本动作（`n_cmd_code` = `codes.rs` 的 `field_index`
    /// = C# 枚举值：42 `PLAYDICE` / 191 `GAMEGOLD` / 342 `OPENYBDEAL`）。
    fn t142_act(code: i32, p1: &str, n1: i32, p2: &str) -> mir2_script::QuestActionInfo {
        mir2_script::QuestActionInfo {
            n_cmd_code: code,
            s_param1: p1.to_string(),
            n_param1: n1,
            s_param2: p2.to_string(),
            ..Default::default()
        }
    }

    /// 一个 label 的说词记录。**每个动作单独一条 procedure**：oracle
    /// `GotoLableQuestActionProcess` 对每个 process 只执行**第一个已注册动作**后返回
    /// （`Engine::run_actions` 的 1:1 移植），同一 `action_list` 里的后续动作不会执行。
    fn t142_record(
        label: &str,
        say: &str,
        actions: Vec<mir2_script::QuestActionInfo>,
    ) -> mir2_script::SayingRecord {
        let procedure_list = actions
            .into_iter()
            .enumerate()
            .map(|(i, a)| mir2_script::SayingProcedure {
                condition_list: Vec::new(),
                action_list: vec![a],
                else_action_list: Vec::new(),
                s_say_msg: if i == 0 {
                    say.to_string()
                } else {
                    String::new()
                },
                s_else_say_msg: String::new(),
            })
            .collect();
        mir2_script::SayingRecord {
            s_label: label.to_string(),
            procedure_list,
            bo_ext_jmp: false,
        }
    }

    /// **T-142 F1/F2 夹具**：世界（玩家 `hero` (10,10) + 商人 (11,10)，同图 ±15 内）、
    /// 会话（元宝 250、`GamePoint = 0x00010002`、`SoftVersionDateEx != 0`）、在线登记表、
    /// 网关下行缓冲与商店/寄售会话态。
    ///
    /// 这个夹具走的是**生产入口**（`handle_shop_cmd` / `handle_click_npc_cmd`），
    /// 直接调 `seed_player_gold_deal` 的往返用例（`t142_gold_deal_seed_and_write_back_round_trip`）
    /// 是辅助函数级假牙，删掉生产接线它不会红。
    struct T142Rig {
        world: mir2_world::World,
        merchant_id: i32,
        sessions: HashMap<String, SessionGround>,
        online: OnlineRegistry,
        gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>>,
        rx: mpsc::UnboundedReceiver<SimToGate>,
        shop_sessions: HashMap<String, ShopSession>,
        sell_off_sessions: HashMap<String, game_svr::selloff::SellOffState>,
        sell_off_book: game_svr::selloff::SellOffBook,
        book: game_svr::npc::MerchantScriptBook,
        npc_vars: game_svr::npc::NpcVars,
        catalog: game_svr::ability::StdItemCatalog,
        shop_cfg: ShopCfg,
        colors: MsgColors,
        item_number: i32,
    }

    impl T142Rig {
        fn new(records: Vec<mir2_script::SayingRecord>) -> Self {
            let mut world = mir2_world::World::new(32, 32);
            let hero = world.add_entity({
                let mut e = mir2_world::Entity::new(1, "hero", 10, 10);
                e.race = mir2_world::ACTOR_RACE_PLAY;
                e
            });
            let merchant_id = world
                .insert_merchant(mir2_world::merchant::MerchantSpawn {
                    name: "商人".to_string(),
                    x: 11,
                    y: 10,
                    map_id: 0,
                    state: mir2_world::merchant::MerchantState::new(
                        "卫家店".to_string(),
                        "0".to_string(),
                        0,
                        0,
                        100,
                        false,
                        false,
                        0,
                        mir2_world::merchant::MerchantFlags {
                            is_buy: true,
                            ..Default::default()
                        },
                        vec![0, 5],
                        Vec::new(),
                        0,
                    ),
                })
                .expect("商人入世界");
            let mut book = game_svr::npc::MerchantScriptBook::new(30);
            book.insert(game_svr::npc::MerchantNpc {
                def: game_svr::npc::NpcDef {
                    chr_name: "寄售商".to_string(),
                    file_path: "Market_Def".to_string(),
                    script_name: Some("寄售商-0103".to_string()),
                    is_hide: false,
                    is_quest: false,
                    scripts: vec![mir2_script::ScriptInfo {
                        is_quest: false,
                        quest_info: Default::default(),
                        record_list: records,
                        quest_count: 0,
                    }],
                    loaded: true,
                    actor_id: merchant_id,
                },
                price_rate: 100,
                castle: None,
                map_name: "0".to_string(),
                curr_x: 11,
                curr_y: 10,
            });
            let mut sg = test_session_ground(hero);
            sg.game_gold = 250;
            sg.game_point = 0x0001_0002;
            // 真冻结客户端的 `SoftVersionDateEx != 0`（同 `spell_session_ground`）。
            sg.soft_version_date = 120_020_522;
            let mut sessions: HashMap<String, SessionGround> = HashMap::new();
            sessions.insert("hero".to_string(), sg);
            let mut online: OnlineRegistry = Vec::new();
            online_set(
                &mut online,
                OnlineEntry {
                    account: "ua".to_string(),
                    chr_name: "hero".to_string(),
                    session_id: 1,
                    gate_idx: 0,
                    socket: 901,
                    actor_id: hero,
                },
            );
            let (tx0, rx) = mpsc::unbounded_channel::<SimToGate>();
            let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
            gates.insert(0, tx0);
            Self {
                world,
                merchant_id,
                sessions,
                online,
                gates,
                rx,
                shop_sessions: HashMap::new(),
                sell_off_sessions: HashMap::new(),
                sell_off_book: game_svr::selloff::SellOffBook::default(),
                book,
                npc_vars: game_svr::npc::NpcVars::default(),
                catalog: game_svr::ability::StdItemCatalog::new(),
                shop_cfg: ShopCfg {
                    castle_member_price_rate: 100,
                    super_repair_price_rate: 100,
                    repair_item_dec_dura: 0,
                    make_durg_price: 100,
                    get_all_npc_tax: false,
                    human_max_gold: 10_000_000,
                    ..ShopCfg::default()
                },
                colors: MsgColors {
                    red_f: 255,
                    red_b: 56,
                    hear_f: 0,
                    hear_b: 255,
                    whisper_f: 0,
                    whisper_b: 0,
                    green_f: 0xDB,
                    green_b: 0xFF,
                    blue_f: 0xFF,
                    blue_b: 0xFC,
                },
                item_number: 0,
            }
        }

        fn game_gold(&self) -> i32 {
            self.sessions["hero"].game_gold
        }

        /// 生产入口 ①：`CM_MERCHANTDLGSELECT`（`PlayObject.Operate.cs:114-128`）。
        fn dlg_select(&mut self, label: &str) {
            let trade: HashMap<String, game_svr::trade::DealState> = HashMap::new();
            handle_shop_cmd(
                game_svr::shop::CM_MERCHANTDLGSELECT,
                self.merchant_id,
                0,
                0,
                Some(label),
                "hero",
                901,
                &self.online,
                &mut self.sessions,
                &mut self.shop_sessions,
                &mut self.sell_off_sessions,
                &mut self.sell_off_book,
                &trade,
                &self.gates,
                &mut self.world,
                &self.catalog,
                &self.shop_cfg,
                &self.colors,
                None,
                &mut self.item_number,
                &self.book,
                &self.npc_vars,
            );
        }

        /// 生产入口 ②：`CM_CLICKNPC`（`PlayObject.Message.cs:2071-2095` 的 `Click` 支）。
        fn click(&mut self) -> bool {
            handle_click_npc_cmd(
                self.merchant_id,
                "hero",
                901,
                &self.online,
                &mut self.sessions,
                &mut self.world,
                &self.book,
                &mut self.shop_sessions,
                &mut self.sell_off_sessions,
                &self.npc_vars,
                &self.catalog,
                &self.gates,
            )
        }

        /// 生产入口 ③：`CM_USERREPAIRITEM`（`PlayObject.Operate.cs:1585`）。`MakeIndex = 0`
        /// ⇒ `repair_target_index` 走 BUG-REPLICA 的「回落最后一件」支。
        fn repair(&mut self) {
            let trade: HashMap<String, game_svr::trade::DealState> = HashMap::new();
            handle_shop_cmd(
                game_svr::shop::CM_USERREPAIRITEM,
                self.merchant_id,
                0,
                0,
                Some(""),
                "hero",
                901,
                &self.online,
                &mut self.sessions,
                &mut self.shop_sessions,
                &mut self.sell_off_sessions,
                &mut self.sell_off_book,
                &trade,
                &self.gates,
                &mut self.world,
                &self.catalog,
                &self.shop_cfg,
                &self.colors,
                None,
                &mut self.item_number,
                &self.book,
                &self.npc_vars,
            );
        }

        fn drain(&mut self) -> Vec<Vec<u8>> {
            drain_frames(&mut self.rx)
        }
    }

    /// **T-142 F1（Important，复核实证的假牙缺口）**：`CM_MERCHANTDLGSELECT` 的**生产路径**上，
    /// `PLAYDICE` 的 `PlayDiceLabel`、`OPENYBDEAL` 的 `SaleDeal`/`GameGold` 副作用必须跨
    /// `GotoLable` 存活（oracle 里它们是同一个 `PlayObject` 的字段，`PlayObject.cs:588/856`）。
    ///
    /// 夹具脚本三层：
    /// - `@main`：说词 `<开通/@open>` + `PLAY DICE 1 @dice`（`ExecutionProcessingSys.cs:2030-2034`）；
    /// - `@open`：说词 `<返回/@main>` + `OPENYBDEAL 100`（`:2329-2357`）；
    /// - `@dice`：说词 `<返回/@main>` + `OPENYBDEAL 100` + `GAMEGOLD + 10`。
    ///
    /// `@dice` **不出现在任何说词里** ⇒ 进入资格只能来自 `LableIsCanJmp` 第三支
    /// （`PlayObject.Base.cs:2824-2828`，命中即清 `string.Empty` ⇒ 一次性）。
    ///
    /// 牙（删生产接线必红）：删 `run_merchant_goto` 的 `seed_player_gold_deal` ⇒ 实测**先红在
    /// 第一次 `@dice` 的 `LableIsCanJmp` 断言**（`lib.rs` 的
    /// `assert_eq!(play_dice_label.as_deref(), Some(""))`：快照没 seed 到会话里的
    /// `PlayDiceLabel` ⇒ 第三支不放行 ⇒ `left: None, right: Some("")`，日志
    /// `LableIsCanJmp(@dice) == false`），根本到不了第③段的扣费分支（因此「160 变 60」只是
    /// 更后段的假设后果，不是首个失败点）；删其
    /// `write_back_player_gold_deal` ⇒ 第②段元宝不落会话（250 而非 150）。
    #[test]
    fn t142_merchant_dlg_select_openybdeal_and_playdice_through_production_path() {
        let mut rig = T142Rig::new(vec![
            t142_record(
                "@main",
                r"掷骰还是开通?\ <开通/@open>",
                vec![t142_act(42, "", 1, "@dice")],
            ),
            t142_record(
                "@open",
                r"开通寄售\ <返回/@main>",
                vec![t142_act(342, "100", 0, "")],
            ),
            t142_record(
                "@dice",
                r"骰子\ <返回/@main>",
                vec![t142_act(342, "100", 0, ""), t142_act(191, "+", 10, "10")],
            ),
        ]);

        // —— `@main`：`PLAY DICE 1 @dice` 只写标签（不涉元宝）。
        rig.dlg_select("@main");
        assert_eq!(rig.game_gold(), 250, "PLAYDICE 不扣元宝");
        assert_eq!(
            rig.shop_sessions["hero"].play_dice_label.as_deref(),
            Some("@dice"),
            "PLAYDICE 的 sParam2 必须经生产路径写回会话（否则客户端回跳必被拒）"
        );
        assert!(
            !rig.sell_off_sessions["hero"].sale_deal,
            "未 OPENYBDEAL 前 SaleDeal 必须为 false"
        );
        assert!(
            rig.drain()
                .iter()
                .any(|b| hdr(b).0 == mir2_protocol::messages::SM_MERCHANTSAY),
            "@main 说词必须下发"
        );

        // —— `@open`：经说词 `CanJmpScriptLableMap` 第二支放行；`OPENYBDEAL 100` 扣费 + 置 SaleDeal。
        rig.dlg_select("@open");
        assert_eq!(
            rig.game_gold(),
            150,
            "① OPENYBDEAL 100 必须经生产路径扣会话元宝（写回生效）"
        );
        assert!(
            rig.sell_off_sessions["hero"].sale_deal,
            "① SaleDeal 必须写回 `SellOffState`"
        );
        let _ = rig.drain();

        // —— 第一次 `@dice`：只能经 `LableIsCanJmp` 第三支（`@dice` 不在任何说词里）。
        rig.dlg_select("@dice");
        assert_eq!(
            rig.shop_sessions["hero"].play_dice_label.as_deref(),
            Some(""),
            "② 第三支命中即清成空串（一次性）"
        );
        assert_eq!(
            rig.game_gold(),
            160,
            "②③ 第三支放行 ⇒ 脚本执行：已开通支不扣费（150）+ GAMEGOLD +10 ⇒ 160（seed 生效）"
        );
        assert!(
            !rig.drain().is_empty(),
            "② 第三支放行 ⇒ 脚本执行（说词 + 元宝帧），不可能零帧"
        );

        // —— 第二次 `@dice`：第三支已被消费 ⇒ `LableIsCanJmp == false` ⇒ 零帧、零副作用。
        rig.dlg_select("@dice");
        assert!(
            rig.drain().is_empty(),
            "② 第三支只能放行一次（第二次被拒 ⇒ `GotoLable` 被 boExtJmp 挡下 ⇒ 零帧）"
        );
        assert_eq!(rig.game_gold(), 160, "② 被拒 ⇒ 脚本不执行，元宝不变");
    }

    /// `take`/`give` 的 **`nParam2`** 口径（`ScriptParsers.cs:554`：动作的件数在 **sParam2** ⇒
    /// `nParam2`；`sParam1` 是物品名，`nParam1` 留 0）。`take 筹码包 1` 的真实解析结果。
    fn t142_act_n2(code: i32, p1: &str, n2: i32) -> mir2_script::QuestActionInfo {
        mir2_script::QuestActionInfo {
            n_cmd_code: code,
            s_param1: p1.to_string(),
            n_param2: n2,
            ..Default::default()
        }
    }

    /// **线程卡 `openmir2-script-take-persist`（tier R）**：`take` 的副作用必须落到**会话背包**
    /// `SessionGround.state.item_list`（存档 `build_save_record` → `bag_items_for_save` 读它），
    /// 否则断线存档后 DB 里物品仍在（r9 真机现象）。
    ///
    /// oracle：`GotoLableTakeItem`（`ScriptEngine.cs:667`）**从尾往前**扫 `ItemList` 并
    /// `RemoveAt(i)`——同名多件时摘的是**最后几件**；本用例用
    /// `[筹码包(4201), 木剑(4202), 筹码包(4203)]` 钉住该顺序（摘 1 件必须摘 4203）。
    ///
    /// 牙（先备份 sha256，改完还原并核对）：
    /// ① 删 `run_merchant_goto` 里的 `write_back_player_bag` 调用 ⇒ 本用例红（背包仍 3 件）；
    /// ② 把回写摘除改成「从头往前」⇒ 4201 被摘 ⇒ 顺序断言红。
    #[test]
    fn take_removes_from_session_bag_through_production_path() {
        use game_svr::bag::BagItem;
        let mut rig = T142Rig::new(vec![
            t142_record(
                "@main",
                r"领筹码\ <领取/@ya52>",
                vec![t142_act(191, "+", 0, "")],
            ),
            t142_record("@ya52", "", vec![t142_act_n2(2, "筹码包", 1)]),
        ]);
        rig.catalog.insert(
            1,
            mir2_data::StdItem {
                name: "筹码包".to_string(),
                dura_max: 5000,
                ..mir2_data::StdItem::default()
            },
        );
        rig.catalog.insert(
            2,
            mir2_data::StdItem {
                name: "木剑".to_string(),
                dura_max: 10,
                ..mir2_data::StdItem::default()
            },
        );
        {
            let sg = rig.sessions.get_mut("hero").unwrap();
            sg.state.item_list = vec![
                BagItem {
                    make_index: 4201,
                    index: 1,
                    dura: 5000,
                    dura_max: 5000,
                    desc: [0; 14],
                },
                BagItem {
                    make_index: 4202,
                    index: 2,
                    dura: 10,
                    dura_max: 10,
                    desc: [0; 14],
                },
                BagItem {
                    make_index: 4203,
                    index: 1,
                    dura: 5000,
                    dura_max: 5000,
                    desc: [0; 14],
                },
            ];
        }
        // `@ya52` 的进入资格来自 `@main` 说词里的链接（`LableIsCanJmp` 第二支）。
        rig.dlg_select("@main");
        assert_eq!(
            rig.sessions["hero"].state.item_list.len(),
            3,
            "只跑 @main（无 take）⇒ 背包必须原样"
        );
        rig.dlg_select("@ya52");
        let bag = &rig.sessions["hero"].state.item_list;
        let remaining: Vec<i32> = bag.iter().map(|it| it.make_index).collect();
        assert_eq!(
            remaining,
            vec![4201, 4202],
            "`take 筹码包 1` 必须回写会话背包，且照 oracle 从**尾**摘（摘 4203，留 4201）"
        );
    }

    /// 同一张卡的金币半边：`take 金币 N` 走 `DecGold`（`ScriptEngine.cs:657-660`），改的是同一个
    /// `PlayObject.Gold` ⇒ 必须回写 `SessionGround.state.gold`（`build_save_record` 读它落库）。
    ///
    /// 牙：删 `write_back_player_gold_deal` 里的 `sg.state.gold = p.gold;` ⇒ 本用例红（仍 100）。
    #[test]
    fn take_gold_persists_to_session_gold_through_production_path() {
        let mut rig = T142Rig::new(vec![
            t142_record(
                "@main",
                r"交钱\ <交钱/@ya53>",
                vec![t142_act(191, "+", 0, "")],
            ),
            t142_record("@ya53", "", vec![t142_act_n2(2, "金币", 5)]),
        ]);
        rig.sessions.get_mut("hero").unwrap().state.gold = 100;
        rig.dlg_select("@main");
        assert_eq!(
            rig.sessions["hero"].state.gold, 100,
            "只跑 @main（无 take 金币）⇒ 金币必须原样"
        );
        rig.dlg_select("@ya53");
        assert_eq!(
            rig.sessions["hero"].state.gold, 95,
            "`take 金币 5` 必须回写会话金币（否则断线存档金币不减）"
        );
    }

    /// `give` 半边（同一次对账的「多出的件」）：照 `GotoLableGiveItem`（`ScriptEngine.cs:710-718`）
    /// ⇒ `CopyToUserItemFromName`：`Index` 按名查表、`Dura = DuraMax = tpl.DuraMax`、
    /// `MakeIndex = M2Share.GetItemNumber()`（生产 = sim 循环的 `item_number` 计数器）。
    ///
    /// 牙：删 `write_back_player_bag` 的「多出」分支 ⇒ 本用例红（背包 0 件）。
    #[test]
    fn give_adds_allocated_item_to_session_bag_through_production_path() {
        let mut rig = T142Rig::new(vec![
            t142_record(
                "@main",
                r"给筹码\ <给/@ya54>",
                vec![t142_act(191, "+", 0, "")],
            ),
            t142_record("@ya54", "", vec![t142_act_n2(3, "筹码包", 2)]),
        ]);
        rig.catalog.insert(
            1,
            mir2_data::StdItem {
                name: "筹码包".to_string(),
                dura_max: 5000,
                ..mir2_data::StdItem::default()
            },
        );
        rig.dlg_select("@main");
        rig.dlg_select("@ya54");
        let bag = &rig.sessions["hero"].state.item_list;
        assert_eq!(bag.len(), 2, "`GIVE 筹码包 2` 必须两件都入会话背包");
        assert!(
            bag.iter()
                .all(|it| it.index == 1 && it.dura == 5000 && it.dura_max == 5000),
            "Index/Dura/DuraMax 必须照 `CopyToUserItemFromName`：{bag:?}"
        );
        assert!(
            bag.iter().all(|it| it.make_index > 0),
            "`MakeIndex` 必须由会话计数器分配（`MakeIndex<=0` 在 DBSvr 侧整行被跳过）: {bag:?}"
        );
        let mk: Vec<i32> = bag.iter().map(|it| it.make_index).collect();
        assert_eq!(mk, vec![1, 2], "计数器从 0 起（夹具）⇒ 逐件 +1");
    }

    /// **T-142 F1（第二条入口）**：`CM_CLICKNPC` 的 `@main` 路径同样必须 seed/写回
    /// `SaleDeal`/`PlayDiceLabel`/`GameGold`（`handle_click_npc_cmd` 的 `normNpc.Click` 支）。
    ///
    /// 两次点击：第一次 `OPENYBDEAL 100`（250→150）+ `PLAYDICE` + `GAMEGOLD + 10`（→160）；
    /// 第二次必须命中「已开通」支（不扣费，再 +10 ⇒ 170）——这只能由 `seed_player_gold_deal`
    /// 看到上一次写回的 `SaleDeal` 成立。
    ///
    /// 牙：删 `handle_click_npc_cmd` 的 seed 行 ⇒ 第二次点击再扣 100（170→70）；
    /// 删其写回行 ⇒ 第一次点击的 250→160 不落会话；删其脚本帧排水
    /// （`emit_script_frames`）⇒ `GAMEGOLD + 10` 的 `SM_GAMEGOLDNAME` 帧消失 ⇒ 本用例红。
    #[test]
    fn t142_click_npc_main_seeds_and_writes_back_gold_deal() {
        let mut rig = T142Rig::new(vec![t142_record(
            "@main",
            r"欢迎\ <返回/@main>",
            vec![
                t142_act(342, "100", 0, ""),
                t142_act(42, "", 1, "@dice"),
                t142_act(191, "+", 10, "10"),
            ],
        )]);

        assert!(rig.click(), "第一次点击必须走到 `@main` 说词点");
        assert_eq!(
            rig.game_gold(),
            160,
            "CM_CLICKNPC：OPENYBDEAL 扣费 100 + GAMEGOLD +10 必须写回会话"
        );
        assert!(rig.sell_off_sessions["hero"].sale_deal);
        assert_eq!(
            rig.shop_sessions["hero"].play_dice_label.as_deref(),
            Some("@dice"),
            "CM_CLICKNPC：PLAYDICE 标签必须写回会话"
        );
        // 牙②：`@main` 的 `GAMEGOLD + 10` 必须经 click 的脚本帧排水下发
        // （删 `handle_click_npc_cmd` 的 `emit_script_frames` ⇒ 本断言红）。
        let frames = rig.drain();
        assert!(
            frames
                .iter()
                .any(|b| hdr(b.as_slice()).0 == mir2_protocol::messages::SM_MERCHANTSAY),
            "@main 说词必须下发；实收 {:?}",
            frames.iter().map(|b| hdr(b.as_slice())).collect::<Vec<_>>()
        );
        assert!(
            frames.contains(&game_svr::smframe::sm_gamegoldname(160, 0x0001_0002, &[])),
            "CM_CLICKNPC 的脚本帧排水必须下发 SM_GAMEGOLDNAME(160, GamePoint)；实收 {:?}",
            frames.iter().map(|b| hdr(b.as_slice())).collect::<Vec<_>>()
        );
        // `/code-review` finding 1：`RM_PLAYDICE(10500)` 必须经脚本帧排水下发
        // `SM_PLAYDICE`（`PlayObject.Message.cs:2034-2041`：recog = 入队 NPC ActorId、
        // wParam = 脚本 nParam1、WL 三参 = MDyVal 打包、尾 = EncodeString(sParam2)）。
        // 删 `pickwire::script_frame` 的 RM_PLAYDICE 分支 ⇒ 本断言红。
        assert!(
            frames.contains(&game_svr::smframe_ext::sm_playdice(
                rig.merchant_id,
                1,
                0,
                0,
                0,
                b"@dice"
            )),
            "PLAYDICE 必须下发 SM_PLAYDICE(8001)；实收 {:?}",
            frames.iter().map(|b| hdr(b.as_slice())).collect::<Vec<_>>()
        );

        // `ClickNpcTime` 限频门（`PlayObject.Message.cs:2076`）：清掉再点第二次。
        rig.sessions.get_mut("hero").unwrap().click_npc_time = None;
        assert!(rig.click(), "第二次点击同样走到 `@main`");
        assert_eq!(
            rig.game_gold(),
            170,
            "已开通 ⇒ 第二次点击不得重复扣费，只再 +10（seed 生效）"
        );
    }

    /// **Minor-1（复核）**：修理成功后的 `GotoLable("~@repair")` 必须按 `MsgQueue` 优先级排水
    /// ——说词 `RM_MERCHANTSAY`(1) → 脚本帧 `RM_GAMEGOLDCHANGED`(148) →
    /// `SM_USERREPAIRITEM_OK`(159)（`BaseObject.Message.cs:180`）。
    ///
    /// 旧实现把 `emit_script_frames` 写在 `emit_npc_says` 之前，与本文件另外三处 `GotoLable`
    /// 调用点（1011 `@back`、`CM_CLICKNPC(@main)`）及 `emit_script_frames` 自身文档相反 ⇒
    /// 线上次序变成 脚本帧 → 说词，本用例红。
    ///
    /// 夹具：商人开 `is_repair`、背包一件 4/10 的模板（`repair_item_dec_dura = 30` ⇒ 修满不降上限）、
    /// 会话 `ScriptLable = "@repair"`、脚本 `~@repair` 说词 + `GAMEGOLD + 10`。
    #[test]
    fn t142_repair_says_precede_script_frames() {
        let mut rig = T142Rig::new(vec![t142_record(
            "~@repair",
            r"修好了\ <返回/@main>",
            vec![t142_act(191, "+", 10, "10")],
        )]);
        // `T142Rig` 的商人只开 `is_buy`；修理支还要求 `IsRepair`（`Merchant.ClientRepairItem`）。
        rig.world
            .entities
            .get_mut(rig.merchant_id)
            .and_then(|e| e.merchant.as_mut())
            .expect("商人实体")
            .flags
            .is_repair = true;
        // `T142Rig` 的 `repair_item_dec_dura = 0` ⇒ 修满支会除零；用部署缺省 30。
        rig.shop_cfg.repair_item_dec_dura = 30;
        {
            let sg = rig.sessions.get_mut("hero").expect("会话");
            sg.state.gold = 10_000;
            sg.state.item_list.push(game_svr::bag::BagItem {
                make_index: 9,
                index: 1,
                dura: 4,
                dura_max: 10,
                desc: [0; 14],
            });
        }
        rig.catalog.insert(
            1,
            mir2_data::models::StdItem {
                name: "木剑".to_string(),
                price: 100,
                weight: 5,
                std_mode: 0,
                dura_max: 10,
                ..mir2_data::models::StdItem::default()
            },
        );
        rig.shop_sessions
            .entry("hero".to_string())
            .or_default()
            .script_lable = game_svr::shop::LABEL_REPAIR.to_string();

        rig.repair();

        assert_eq!(
            rig.game_gold(),
            260,
            "`~@repair` 的 GAMEGOLD +10 必须落会话"
        );
        let frames = rig.drain();
        let idents: Vec<u16> = frames.iter().map(|b| hdr(b.as_slice()).0).collect();
        let say_pos = idents
            .iter()
            .position(|&i| i == mir2_protocol::messages::SM_MERCHANTSAY)
            .unwrap_or_else(|| panic!("修理说词必须下发：{idents:?}"));
        let gold_pos = idents
            .iter()
            .position(|&i| i == mir2_protocol::messages::SM_GAMEGOLDNAME)
            .unwrap_or_else(|| panic!("RM_GAMEGOLDCHANGED 脚本帧必须下发：{idents:?}"));
        let ok_pos = idents
            .iter()
            .position(|&i| i == mir2_protocol::messages::SM_USERREPAIRITEM_OK)
            .unwrap_or_else(|| panic!("修理 OK 必须下发：{idents:?}"));
        assert!(
            say_pos < gold_pos,
            "说词（优先级 1）必须先于脚本帧（148）：{idents:?}"
        );
        assert!(
            gold_pos < ok_pos,
            "脚本帧（148）必须先于 SM_USERREPAIRITEM_OK（159）：{idents:?}"
        );
        assert_eq!(
            frames[gold_pos],
            game_svr::smframe::sm_gamegoldname(260, 0x0001_0002, &[]),
            "元宝帧取写回后的会话值：GameGold=260，GamePoint=0x00010002"
        );
    }

    /// **T-142 F2**：脚本 `GAMEGOLD` 动作（`ActionOfGameGold`，`ExecutionProcessingSys.cs:3058-3092`）
    /// 改元宝后必须调 `GameGoldChanged()`（`BaseObject.cs:593-599`：`SendUpdateMsg(RM_GAMEGOLDCHANGED,
    /// 0,0,0,0,"")`，仅本人）；消息泵把它翻成 `SendGoldInfo(false)`
    /// （`PlayObject.Message.cs:1836-1837`）⇒ `SendDefMessage(SM_GAMEGOLDNAME, GameGold,
    /// LoWord(GamePoint), HiWord(GamePoint), 0, "")`（`PlayObject.Base.cs:927-939`）。
    ///
    /// 门：`SoftVersionDateEx == 0` ⇒ 整帧不发（`:930`）。
    ///
    /// 牙：删 `NpcPlayer::game_gold_changed` 覆写（回落 trait 默认 no-op）⇒ 无帧；
    /// 删 `pickwire::script_frame` 的 `RM_GAMEGOLDCHANGED` 映射 ⇒ 无帧。
    #[test]
    fn t142_gamegold_action_emits_gamegoldchanged_frame_through_host() {
        let mut rig = T142Rig::new(vec![t142_record(
            "@main",
            r"充值\ <返回/@main>",
            vec![t142_act(191, "+", 10, "10")],
        )]);

        rig.dlg_select("@main");
        assert_eq!(rig.game_gold(), 260, "GAMEGOLD +10 落会话");
        let frames = rig.drain();
        let want = game_svr::smframe::sm_gamegoldname(260, 0x0001_0002, &[]);
        assert!(
            frames.contains(&want),
            "RM_GAMEGOLDCHANGED ⇒ SM_GAMEGOLDNAME(260, LoWord/HiWord(GamePoint), 空尾)；实收 {:?}",
            frames.iter().map(|b| hdr(b.as_slice())).collect::<Vec<_>>()
        );

        // `SoftVersionDateEx == 0`：值照改，但 `SendGoldInfo` 整帧不发。
        rig.sessions.get_mut("hero").unwrap().soft_version_date = 0;
        rig.dlg_select("@main");
        assert_eq!(rig.game_gold(), 270);
        assert!(
            !rig.drain()
                .iter()
                .any(|b| hdr(b).0 == mir2_protocol::messages::SM_GAMEGOLDNAME),
            "SoftVersionDateEx == 0 ⇒ 零 SM_GAMEGOLDNAME（PlayObject.Base.cs:930）"
        );
    }

    /// **施法用例**的会话态：真冻结客户端的 `PlayObject.SoftVersionDateEx != 0`
    /// （11029/5008 已发；`cert::CertParse::client_version` 实测 120020522），
    /// `ClientTick = 0`（客户端 1018 的 `Recog=0`，设计件 §1.8）。
    /// ⇒ `DoSpell` 的版本门（`MagicManager.cs:167`）「双 0」子句**不成立**，与基线帧面一致。
    fn spell_session_ground(actor_id: i32) -> SessionGround {
        let mut sg = test_session_ground(actor_id);
        sg.soft_version_date = 120_020_522;
        sg
    }

    /// **M3⑥-实现 3 第②片**：`emit_npc_says` 按 oracle `MsgQueue` 出队序（`High` 先）落
    /// `SM_MERCHANTSAY(643)`，且 `recog` 取「`priority` ⇒ 玩家 ActorId；否则 ⇒ NPC ActorId
    /// （隐藏 NPC 恒 0）」（`ScriptEngine.cs:993/997` + `BaseObject.Message.cs:30/180`）。
    ///
    /// 红检：把 `dequeue_order` 改回入队序、或把 `recog` 恒取玩家 ActorId ⇒ 本用例必红。
    #[test]
    fn emit_npc_says_priority_first_and_recog_by_path() {
        let (tx, mut rx) = mpsc::unbounded_channel::<SimToGate>();
        let say = |m: &str, priority| game_svr::npc::SayMsg {
            npc_name: "QManage".to_string(),
            raw_msg: m.to_string(),
            text: format!("QManage/{m}"),
            priority,
            // G-4：非 priority 支的 `Recog` = NPC 的 ActorId（固定输入 0x11223344）。
            npc_actor_id: 0x1122_3344,
        };
        let says = vec![say("a", false), say("b", true)];
        assert_eq!(emit_npc_says(&tx, 7, 4242, &says), 2);
        let mut frames = Vec::new();
        while let Ok(SimToGate::SendFrame { socket, body }) = rx.try_recv() {
            frames.push((socket, body));
        }
        assert_eq!(frames.len(), 2);
        assert_eq!(frames[0].0, 7, "回送给该会话自己的 socket");
        assert_eq!(
            u16::from_le_bytes([frames[0].1[4], frames[0].1[5]]),
            mir2_protocol::messages::SM_MERCHANTSAY,
            "ident"
        );
        assert_eq!(
            i32::from_le_bytes(frames[0].1[0..4].try_into().unwrap()),
            4242,
            "priority 路径 ⇒ recog = 玩家 ActorId"
        );
        assert_eq!(
            i32::from_le_bytes(frames[1].1[0..4].try_into().unwrap()),
            0x1122_3344,
            "SendMsg(normNpc) 路径 ⇒ recog = NPC ActorId（G-4）"
        );
        // 逐字节：`44332211 8302 0000 0000 0100` + EncodeString("QManage/a")。
        let mut expect_npc = vec![0x44, 0x33, 0x22, 0x11, 0x83, 0x02, 0, 0, 0, 0, 1, 0];
        expect_npc.extend_from_slice(&mir2_protocol::edcode::encode(b"QManage/a"));
        assert_eq!(frames[1].1, expect_npc, "643 头字段逐字节（非 priority）");
        assert_eq!(
            frames[0].1,
            smframe::sm_merchantsay(4242, 0, 0, b"QManage/b"),
            "priority 组先出，尾 = EncodeString(ChrName + '/' + sMsg)"
        );
    }

    /// **M3⑥-实现 3 第②片**：`npc_player_from` 的字段快照（`Gold`/`QuestFlag`/`ItemList`）。
    #[test]
    fn npc_player_snapshot_maps_record_fields() {
        let mut rng = mir2_shared::rng::RandomNumber::with_seed(7);
        let mut rngf = |v: i32| rng.random_below(v);
        let cell = record::ServerUserItem {
            make_index: 11,
            index: 22,
            dura: 0,
            dura_max: 0,
            desc: None,
            color_r: 0,
            color_g: 0,
            color_b: 0,
            prefix: None,
        };
        let bag = vec![Some(cell)];
        let catalog = game_svr::ability::StdItemCatalog::new();
        let p = npc_player_from(
            &mut rngf,
            "hero",
            5,
            "0",
            3,
            100,
            Some(&bag),
            Some(&[7, 8, 9]),
            &catalog,
            77,
            &[0, 1, 2],
        );
        assert_eq!(p.chr_name, "hero");
        assert_eq!(p.actor_id, 5);
        assert_eq!(p.map_name, "0");
        assert_eq!(p.level, 3);
        assert_eq!(p.gold, 100);
        assert_eq!(p.group_owner, 77);
        assert_eq!(p.group_member_jobs, vec![0, 1, 2]);
        assert_eq!(&p.quest_flag.as_bytes()[..3], &[7, 8, 9]);
        assert!(
            p.items.is_empty(),
            "空目录 ⇒ `GetStdItem == null` 分支：不入包（不造名）"
        );
    }

    /// oracle 全字段角色记录（`stage6` 向量，`tests/fixtures/player_data_full_oracle.txt`）——存档用例的底稿。
    fn stage6_record() -> record::PlayerRecord {
        let path = concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/tests/fixtures/player_data_full_oracle.txt"
        );
        let text = std::fs::read_to_string(path).expect("player_data_full_oracle.txt");
        let hexs = text
            .split_whitespace()
            .find_map(|t| t.strip_prefix("stage6="))
            .expect("fixture 里必须有 stage6 向量");
        let bytes: Vec<u8> = (0..hexs.len())
            .step_by(2)
            .map(|i| u8::from_str_radix(&hexs[i..i + 2], 16).unwrap())
            .collect();
        record::parse_player_data(&bytes).expect("stage6 必须可解为全字段记录")
    }

    /// 存档记录 = 原始记录 + 会话实时增量（`MakeSaveRcd` 口径）。用 **DBSvr 侧类型**解回断言，
    /// 覆盖实时坐标/Gold/物品与 Helmet/Necklace 交换 + 46 槽补位。
    #[test]
    fn save_record_reflects_live_state_and_item_layout() {
        use mir2_storage::MemPack;
        let saved = SavedHuman {
            account: "acct".into(),
            record: stage6_record(),
            enter_map: "0".into(),
        };
        let weapon = game_svr::bag::BagItem {
            make_index: 9001,
            index: 207,
            dura: 4000,
            dura_max: 4000,
            desc: [0; 14],
        };
        let necklace = game_svr::bag::BagItem::new(9002, 88);
        let helmet = game_svr::bag::BagItem::new(9003, 99);
        let mut use_items = vec![None; game_svr::ability::USE_ITEMS_LEN];
        use_items[game_svr::ability::SLOT_WEAPON] = Some(weapon.clone());
        use_items[game_svr::ability::SLOT_NECKLACE] = Some(necklace);
        use_items[game_svr::ability::SLOT_HELMET] = Some(helmet);
        let sg = SessionGround {
            gm: gmcmd::GmSession::default(),
            state: game_svr::ground::GroundState {
                item_list: vec![weapon],
                gold: 649,
                wabil: test_ability(),
            },
            storage: storage::StorageState::new(),
            actor_id: 1,
            game_gold: 77,
            p22: gamegold::P22GameGold::default(),
            soft_version_date: 0,
            client_tick: 0,
            game_point: 0,
            sys_msg: None,
            use_items,
            sub: game_svr::ability::SubAbility::first_call(),
            hit_speed: 0,
            equip: test_equip_inputs(),
            recovery: game_svr::recover::Recovery {
                inc_health: 3,
                inc_spell: 4,
                ..game_svr::recover::Recovery::new(0)
            },
            stamina: game_svr::stamina::Stamina::new(0),
            show_hp: false,
            abil_see_heal_gauge: false,
            user_unlock_durg: false,
            hunger_status: 55,
            dec_hp_tick: 0,
            inc_hp_tick: 0,
            dec_hunger_point_tick: 0,
            query_bag_items_tick: None,
            bo_reconnection: false,
            shout_msg_tick: 0,
            bo_soft_close: false,
            bo_emergency_close: false,
            is_can_deal: true,
            click_npc_time: None,
            goto_npc_label: String::new(),
            val_type: 0,
            val_label: 0,
            val_npc_type: 0,
            mns_val: vec![String::new(); 100],
            mnm_val: vec![0; 100],
            save_rcd_tick: 0,
            server_index: 0,
            switch_state: SwitchDataState::default(),
            // **PL-2 / P31**：`AutoGetExpTick` ctor = `GetTickCount()`（`PlayObject.cs:1009`）；
            // 登录复位 = 本 ctor（宿主进世界时建会话）；换图复位见 `:3796`。不落库、死亡不清。
            auto_get_exp_tick: now_ms(),
            auto_get_exp_time: 0,
            auto_get_exp_point: 0,
            auto_get_exp_envir: None,
            auto_get_exp_envir_map_id: None,
            auto_get_exp_in_safe_zone: false,
            guild: guild_cmd::GuildSession::default(),
        };
        let mut world = mir2_world::World::with_maps(vec![(100, 100)]);
        world.open_session("hero");
        world
            .enter_map("hero", mir2_world::Entity::new(0, "hero", 11, 22), 0)
            .expect("进世界");
        let rec = build_save_record(&saved, "hero", &world, &sg, None);
        let parsed = mir2_storage::SaveCharacterData::from_bytes(
            &record::encode_save_character_data(&saved.account, "hero", &rec),
        )
        .expect("DBSvr 侧必须能解存档体");
        let d = parsed.character_data.unwrap().data.unwrap();
        assert_eq!(d.cur_map.as_deref(), Some("0"));
        assert_eq!((d.cur_x, d.cur_y), (11, 22), "实时坐标来自世界实体");
        assert_eq!(d.gold, 649);
        assert_eq!(d.game_gold, 77);
        assert_eq!(d.inc_health, 3);
        assert_eq!(d.inc_spell, 4);
        assert_eq!(d.hunger_status, 55);
        assert!(
            d.abil.as_ref().unwrap().hp == 0,
            "保存的 Abil 取自会话 WAbil（test_ability hp=0）"
        );
        let bag = d.bag_items.as_ref().expect("bag_items 非 null");
        assert_eq!(bag.len(), 46, "BagItems 是 46 槽定长");
        assert_eq!(bag[0].as_ref().unwrap().index, 207);
        assert_eq!(
            bag[1].as_ref().unwrap().index,
            0,
            "空槽 = 默认物品（Index 0）"
        );
        let hum = d.hum_items.as_ref().expect("hum_items 非 null");
        assert_eq!(hum.len(), 13, "HumItems 是 13 槽定长");
        assert_eq!(
            hum[game_svr::ability::SLOT_WEAPON].as_ref().unwrap().index,
            207
        );
        assert_eq!(
            hum[game_svr::ability::SLOT_HELMET].as_ref().unwrap().index,
            99,
            "HumItems[Helmet] = UseItems[Helmet]（d7ead5b2a 后 1:1）"
        );
        assert_eq!(
            hum[game_svr::ability::SLOT_NECKLACE]
                .as_ref()
                .unwrap()
                .index,
            88,
            "HumItems[Necklace] = UseItems[Necklace]（d7ead5b2a 后 1:1）"
        );
    }

    /// **G-19 登录侧**：`recovery_from_record` 必须把 `IncHealing` 从记录拷进会话
    /// （`WorldServer.cs:1151`）。红检：删掉 `inc_healing: u16::from(d.inc_healing)` ⇒ 必红。
