    /// **接线批 A 端到端（SM_CHANGELIGHT）**：卸下一件 `Light>0` 的装备 ⇒ `RecalcAbilitys` 的
    /// `oldlight != Light` 支 ⇒ `SM_CHANGELIGHT(654)` 广播给 ±`SendRefMsgRange` 格内的玩家（含自己）。
    ///
    /// 造：actor 42 在世界上；`UseItems[Dress]` 放一件 `Light=5` 的衣；展示表 `light=5`
    /// （进世界时的 `GetMyLight`）；卸下后 `my_light` 回落到 0 ⇒ 出帧。
    /// **红检**：删掉 `handle_bag_cmd` 里的 `changelight_frame` 广播 ⇒ 本用例必红。
    #[test]
    fn bag_takeoff_emits_changelight_when_light_drops() {
        use std::collections::HashMap;
        let mut catalog = game_svr::ability::StdItemCatalog::new();
        catalog.insert(
            1,
            mir2_data::StdItem {
                name: "布衣".into(),
                std_mode: 5,
                light: 5,
                ..Default::default()
            },
        );
        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        let mut sg = test_session_ground(42);
        sg.use_items[0] = Some(game_svr::bag::BagItem {
            make_index: 60001,
            index: 1,
            dura: 10,
            dura_max: 10,
            desc: [0u8; 14],
        });
        sessions.insert("hero".into(), sg);
        let mut online: OnlineRegistry = Vec::new();
        online_set(
            &mut online,
            OnlineEntry {
                account: "ua".into(),
                chr_name: "hero".into(),
                session_id: 1,
                gate_idx: 0,
                socket: 901,
                actor_id: 42,
            },
        );
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        let mut world = mir2_world::World::new(8, 8);
        world.add_entity(mir2_world::Entity::new(42, "hero", 3, 3));
        let mut displays = downlink::DisplayTable::new();
        displays.set(
            42,
            downlink::ActorDisplay::new(2, 5, 111, 0, 0, 255, b"hero".to_vec()),
        );
        handle_bag_cmd(
            game_svr::bag::CM_TAKEOFFITEM,
            60001,
            0,
            0,
            Some("布衣"),
            "hero",
            901,
            &online,
            &mut sessions,
            &gates,
            &catalog,
            &mut world,
            &mut displays,
            12,
            false,
            true,
        );
        let mut ids = Vec::new();
        while let Ok(SimToGate::SendFrame { socket, body }) = rx0.try_recv() {
            assert_eq!(socket, 901, "回帧发给该用户 socket");
            ids.push(u16::from_le_bytes([body[4], body[5]]));
        }
        assert!(
            ids.contains(&mir2_protocol::messages::SM_CHANGELIGHT),
            "卸下 Light=5 装备 ⇒ 出 SM_CHANGELIGHT(654)；实得 idents {ids:?}"
        );
        assert_eq!(
            displays.get(42).unwrap().light,
            0,
            "重算后展示表 Light 回落到 0"
        );
    }

    /// **L1 TransMap 端到端 + 帧序**：玩家走一格踩中 `MapRoute` ⇒ `handle_move_cmd` 先冲换图簇
    /// （`SM_CLEAROBJECTS(633)` → `SM_CHANGEMAP(634)`，`SendMsg` 只发 hero），再广播移动帧
    /// （`SM_WALK` 给**换图后新图**近邻 obs）——oracle 序：簇先、移动帧后
    /// （`PlayObject.Walk` 尾段才 `SendRefMsg(nIdent,…)`）。
    ///
    /// **帧序回归牙**：去掉 `handle_move_cmd` 里 `if outcome.changed_map { drain_map_change(...) }`
    /// ⇒ 633/634 只剩 tick 尾的 drain（本测不调 tick）⇒ 帧序断言（633 先于 SM_WALK）必红。
    #[test]
    fn move_cmd_route_emits_transmap_cluster_before_move_frame() {
        use mir2_protocol::messages::{CM_WALK, SM_CHANGEMAP, SM_CLEAROBJECTS, SM_WALK};
        use std::collections::HashMap;
        let mut world = mir2_world::World::new(64, 64);
        world.maps.push(mir2_world::map::MapGrid::new(64, 64));
        world.open_session("hero");
        let hero = world
            .enter_map("hero", new_player_entity("hero".to_string(), 5, 4), 0)
            .expect("hero 进图");
        // obs 在目标图 (7,9) ±12 格内 ⇒ 收移动帧（oracle 用换图后新坐标广播）。
        world.open_session("obs");
        let obs = world
            .enter_map("obs", new_player_entity("obs".to_string(), 8, 9), 1)
            .expect("obs 进图");
        // map0 (5,5) → map1 (7,9)
        assert_eq!(
            world.add_map_routes(vec![mir2_world::map::MapRouteSpec {
                map_id: 0,
                x: 5,
                y: 5,
                route_id: 1,
                hop: mir2_world::map::RouteHop {
                    dst_map_id: 1,
                    dst_x: 7,
                    dst_y: 9,
                },
            }]),
            1
        );
        let mut displays = downlink::DisplayTable::new();
        for id in [hero, obs] {
            displays.set(
                id,
                downlink::ActorDisplay::new(0, 0, 111, 0, 0, 255, b"n".to_vec()),
            );
        }
        let mut online: OnlineRegistry = Vec::new();
        for (acct, nm, sid, sock, id) in [("a", "hero", 1, 901, hero), ("b", "obs", 2, 902, obs)] {
            online_set(
                &mut online,
                OnlineEntry {
                    account: acct.into(),
                    chr_name: nm.into(),
                    session_id: sid,
                    gate_idx: 0,
                    socket: sock,
                    actor_id: id,
                },
            );
        }
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);

        // 目标 = (5,5)（hero 当前格正下方）⇒ 方向 Down，走一格踩中 route。
        handle_move_cmd(
            CM_WALK,
            game_svr::feature::make_long(5, 5),
            0,
            "hero",
            901,
            &online,
            &mut HashMap::new(),
            &mut world,
            &mut displays,
            &gates,
            None,
        );

        // 换图落地：hero 在 map1 (7,9)。
        let he = world.entities.get(hero).unwrap();
        assert_eq!((he.map_id, he.x, he.y), (1, 7, 9));

        // 同一 gate 0 通道，保序收集出帧。
        let mut seq: Vec<(i32, u16)> = Vec::new();
        while let Ok(SimToGate::SendFrame { socket, body }) = rx0.try_recv() {
            seq.push((socket, u16::from_le_bytes([body[4], body[5]])));
        }
        assert!(seq.contains(&(901, SM_CLEAROBJECTS)), "hero 收 633");
        assert!(seq.contains(&(901, SM_CHANGEMAP)), "hero 收 634");
        assert!(
            seq.iter().any(|(sk, id)| *sk == 902 && *id == SM_WALK),
            "obs 收移动帧 SM_WALK"
        );
        let i_clear = seq
            .iter()
            .position(|(_, id)| *id == SM_CLEAROBJECTS)
            .unwrap();
        let i_walk = seq.iter().position(|(_, id)| *id == SM_WALK).unwrap();
        assert!(
            i_clear < i_walk,
            "oracle 序：换图簇(633) 先于移动帧(SM_WALK)，实际 {seq:?}"
        );
    }

    // ==========================================================================
    // 片 `openmir2-default-arm-spell-surface`（帧面）：`DoSpell` **无条件** `RM_SPELL` 的牙
    // ==========================================================================
    //
    // 界定件 `tests/parity/m3/design-default-arm-spell-frames-20261017.md` §5.1（J1–J8）；
    // 范围 = 编排侧**宽口径**裁决（卡上 comment `e6d8e8353ebb6f9a64013a1ec88110c450b10a7d`）。
    // 全部走**生产入口** `handle_spell_cmd`（不直调 `World::cast_*`、不碰派生路径）。

    /// 帧面片的共用夹具：施法者 `caster`(10,10)/socket 911、若干观察者（名, x, y, Ghost, socket）、
    /// 存档里学会的魔号、魔法模板表（逐 `(魔号, Effect)`），以及 `ArmRingl` 槽里的护身符
    /// （`dura = 600` ⇒ `Round(600/100) = 6`，满足 `CheckAmulet` 三档需求 1/5/2）。
    struct SpellFrameRig {
        world: mir2_world::World,
        caster: i32,
        online: OnlineRegistry,
        saves: std::collections::HashMap<String, SavedHuman>,
        ground_sessions: std::collections::HashMap<String, SessionGround>,
        magic_table: magics::MagicTable,
        displays: downlink::DisplayTable,
        gates: std::collections::HashMap<u8, mpsc::UnboundedSender<SimToGate>>,
        rx: mpsc::UnboundedReceiver<SimToGate>,
        /// **P3-B2**：`[Setup]` 三个 AoE 半径（缺省 = oracle `GameSvrConf.cs:1770-1772`）。
        fire_boom_rage: i32,
        snow_wind_range: i32,
        elec_blizzard_range: i32,
    }

    impl SpellFrameRig {
        fn new(
            learned: u16,
            table: &[(u16, u8)],
            observers: &[(&str, i32, i32, bool, i32)],
        ) -> Self {
            use std::collections::HashMap;
            let mut world = mir2_world::World::new(64, 64);
            let caster = world.add_entity(new_player_entity("caster".to_string(), 10, 10));
            let mut displays = downlink::DisplayTable::new();
            displays.set(
                caster,
                downlink::ActorDisplay::new(4, 0, 111, 0, 0, 255, b"caster".to_vec()),
            );
            let mut online: OnlineRegistry = Vec::new();
            online_set(
                &mut online,
                OnlineEntry {
                    account: "uc".into(),
                    chr_name: "caster".into(),
                    session_id: 1,
                    gate_idx: 0,
                    socket: 911,
                    actor_id: caster,
                },
            );
            for (i, o) in observers.iter().enumerate() {
                let (name, x, y, ghost, socket): (&str, i32, i32, bool, i32) = *o;
                let id = world.add_entity(new_player_entity(name.to_string(), x, y));
                if ghost {
                    world.entities.get_mut(id).unwrap().ghost = true;
                }
                displays.set(
                    id,
                    downlink::ActorDisplay::new(
                        4,
                        0,
                        112 + i32::try_from(i).unwrap_or(0),
                        0,
                        0,
                        255,
                        enter::gbk(name),
                    ),
                );
                online_set(
                    &mut online,
                    OnlineEntry {
                        account: format!("u{i}"),
                        chr_name: name.to_string(),
                        session_id: 10 + i32::try_from(i).unwrap_or(0),
                        gate_idx: 0,
                        socket,
                        actor_id: id,
                    },
                );
            }
            world.tick();
            let (tx0, rx) = mpsc::unbounded_channel::<SimToGate>();
            let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
            gates.insert(0, tx0);
            let mut record = stage6_record();
            record.data.magic = Some(vec![Some(record::MagicRcd {
                mag_idx: learned,
                level: 1,
                magic_key: u16::from(b'm'),
                tran_point: 0,
            })]);
            let mut saves: HashMap<String, SavedHuman> = HashMap::new();
            saves.insert(
                "caster".into(),
                SavedHuman {
                    account: "uc".into(),
                    record,
                    enter_map: "0".into(),
                },
            );
            let mut ground_sessions: HashMap<String, SessionGround> = HashMap::new();
            let mut sg = spell_session_ground(caster);
            sg.use_items[game_svr::ability::SLOT_ARMRING_L] = Some(game_svr::bag::BagItem {
                make_index: 1,
                index: 1,
                dura: 600,
                dura_max: 1000,
                desc: [0; 14],
            });
            ground_sessions.insert("caster".into(), sg);
            let magic_table = magics::MagicTable::new(
                table
                    .iter()
                    .map(|(id, eff)| mir2_data::MagicInfo {
                        magic_id: *id,
                        effect: *eff,
                        effect_type: 4,
                        train_lv: 3,
                        ..mir2_data::MagicInfo::default()
                    })
                    .collect(),
            );
            Self {
                world,
                caster,
                online,
                saves,
                ground_sessions,
                magic_table,
                displays,
                gates,
                rx,
                fire_boom_rage: 1,
                snow_wind_range: 1,
                elec_blizzard_range: 2,
            }
        }

        /// 走一次生产入口。`click` = 客户端报的点击格（`Recog` 的低/高字）；
        /// `target_actor_id` = `MakeLong(Param, Series)`（0 = 无目标对象）。
        /// `magic_attack_rage` 传 8（oracle `SystemShare.Config.MagicAttackRage` 探针默认值，
        /// 与既有 `spell_cmd_*` 用例同）。
        fn cast(&mut self, magic_id: u16, click: (i32, i32), target_actor_id: i32) {
            let mut catalog = game_svr::ability::StdItemCatalog::new();
            catalog.insert(
                1,
                mir2_data::StdItem {
                    name: "护身符".into(),
                    std_mode: 25,
                    shape: 5,
                    ..mir2_data::StdItem::default()
                },
            );
            let pet_cfg = mir2_data::pet_slave::PetSlaveConfig::default();
            let table = game_svr::mongen::MonsterTable::new(Vec::new());
            let registry = mir2_envir::MapRegistry::from_entries(
                mir2_envir::MapLoader::new(".", "map", "envir"),
                Vec::new(),
            );
            handle_spell_cmd(
                game_svr::feature::make_long(
                    u16::try_from(click.0).unwrap_or(0),
                    u16::try_from(click.1).unwrap_or(0),
                ),
                magic_id,
                u16::try_from(target_actor_id).unwrap_or(0),
                0,
                "caster",
                911,
                &self.online,
                &mut self.world,
                &mut self.saves,
                &mut self.ground_sessions,
                &catalog,
                &self.magic_table,
                &pet_cfg,
                8,
                Some(&registry),
                &table,
                &mut self.displays,
                &self.gates,
                self.fire_boom_rage,
                self.snow_wind_range,
                self.elec_blizzard_range,
            );
        }

        /// 取空 gate 通道：`(SM_* 帧体, `SendRaw` 短包/`+GD` ack)`。
        fn drain(&mut self) -> (Vec<SfFrame>, Vec<SfFrame>) {
            let mut frames = Vec::new();
            let mut raws = Vec::new();
            while let Ok(m) = self.rx.try_recv() {
                match m {
                    SimToGate::SendFrame { socket, body } => frames.push((socket, body)),
                    SimToGate::SendRaw { socket, payload } => raws.push((socket, payload)),
                    other => panic!("意外的下行：{other:?}"),
                }
            }
            (frames, raws)
        }
    }

    /// gate 通道上取到的一条下行：`(socket, 帧体 / `SendRaw` 短包字节)`。
    type SfFrame = (i32, Vec<u8>);

    /// 帧体的 `Ident`（`body[4..6]`；与文件末既有用例同口径）。
    fn sf_ident(b: &[u8]) -> u16 {
        mir2_protocol::frame::CommandMessage::from_bytes(b)
            .unwrap()
            .ident
    }

    fn sf_count(frames: &[SfFrame], socket: i32, ident: u16) -> usize {
        frames
            .iter()
            .filter(|(s, b)| *s == socket && sf_ident(b) == ident)
            .count()
    }

    /// 某连接上的 `Ident` 序列（**到达序** = 该连接的帧序）。
    fn sf_seq(frames: &[SfFrame], socket: i32) -> Vec<u16> {
        frames
            .iter()
            .filter(|(s, _)| *s == socket)
            .map(|(_, b)| sf_ident(b))
            .collect()
    }

    /// **J1**：**未建模**魔号也必须广播**恰好一条** `SM_SPELL`。取两个子类：
    /// 55 = 字面 `default`（`MagicManager.cs:172-643` 里无 `case`，≤80，落 `:644` 共享尾）；
    /// 81 = `:167` 版本门（`MagicId > 80` 早退）——**门在 `:159` 之后**，故 oracle 同样已发帧。
    ///
    /// 红检：① 去掉 `handle_spell_cmd` 里那条无条件广播 ⇒ 必红；② 把它挪到版本门之后 ⇒
    /// 81 子类必红（55 子类仍绿）。
    #[test]
    fn spell_frame_unmodeled_magic_broadcasts_exactly_one() {
        for (magic_id, effect) in [(55u16, 9u8), (81, 11)] {
            let mut rig = SpellFrameRig::new(
                magic_id,
                &[(magic_id, effect)],
                &[("obs", 12, 12, false, 912)],
            );
            rig.cast(magic_id, (12, 12), 0);
            let (frames, _raws) = rig.drain();
            assert_eq!(
                sf_count(&frames, 912, mir2_protocol::messages::SM_SPELL),
                1,
                "[魔号 {magic_id}] 未建模魔号也必须广播**恰好一条** SM_SPELL；实得 {:?}",
                sf_seq(&frames, 912)
            );
        }
    }

    /// **J2**：逐字段 = oracle `PlayObject.Message.cs:1457-1458` 的
    /// `MakeMessage(SM_SPELL, ActorId, nParam1, nParam2, wParam)` + 尾 `nParam3.ToString()`：
    /// `Recog`=施法者、`Param`=`nParam1`=`snap 后`的 x、`Tag`=`nParam2`=snap 后的 y、
    /// `Series`=`wParam`=`Magic.Effect`、**尾 = `MagicId` 的 ASCII**。
    ///
    /// 布置：点击 (12,10)、目标实体在 (13,10) 的 1×1 邻域内 ⇒ `CretInNearXy` 命中 ⇒ snap 成 (13,10)
    /// （`PlayObject.Attack.cs:1272-1277` 就地改写）⇒ 帧参必须是 **13/10** 而不是 12/10。
    /// `Effect = 9 ≠ MagicId = 55` ⇒ 红检「把 `Effect` 与 `MagicId` 对调」必红。
    #[test]
    fn spell_frame_fields_match_oracle_layout() {
        let mut rig = SpellFrameRig::new(55, &[(55, 9)], &[("target", 13, 10, false, 912)]);
        let target = rig
            .online
            .iter()
            .find(|e| e.chr_name == "target")
            .unwrap()
            .actor_id;
        rig.cast(55, (12, 10), target);
        let (frames, _raws) = rig.drain();
        let got: Vec<&Vec<u8>> = frames
            .iter()
            .filter(|(s, b)| *s == 912 && sf_ident(b) == mir2_protocol::messages::SM_SPELL)
            .map(|(_, b)| b)
            .collect();
        assert_eq!(got.len(), 1, "观察者应收恰 1 帧 SM_SPELL；实得 {got:?}");
        let cmd = mir2_protocol::frame::CommandMessage::from_bytes(got[0]).unwrap();
        assert_eq!(cmd.recog, rig.caster, "Recog = ActorId（施法者）");
        assert_eq!(
            cmd.param, 13,
            "nParam1 = snap 后的 nTargetX（13，不是点击格 12）"
        );
        assert_eq!(cmd.tag, 10, "nParam2 = snap 后的 nTargetY");
        assert_eq!(
            cmd.series, 9,
            "wParam = Magic.Effect（=9，不是 MagicId 55）"
        );
        assert_eq!(got[0].len(), 12 + 2, "12B 头 + 尾（`\"55\"`）");
        assert_eq!(&got[0][12..], b"55", "尾 = MagicId 的 ASCII（不是 Effect）");
    }

    /// **J3**：施法者**自己那条连接不收** `SM_SPELL`
    /// （`PlayObject.Message.cs:1455` 的 `if (processMsg.ActorId != ActorId)` 守卫）；
    /// 但仍收 `+GD` ack（`PlayObject.Message.cs:1339-1400` 成功支）。
    ///
    /// 红检：把 `broadcast_ref_msg` 换成 `broadcast_ref_msg_with_self`（`RM_MAGICFIRE` 的口径）
    /// ⇒ 必红。
    #[test]
    fn spell_frame_never_reaches_caster_connection() {
        let mut rig = SpellFrameRig::new(55, &[(55, 9)], &[("obs", 12, 12, false, 912)]);
        rig.cast(55, (12, 12), 0);
        let (frames, raws) = rig.drain();
        assert_eq!(
            sf_count(&frames, 911, mir2_protocol::messages::SM_SPELL),
            0,
            "施法者自身不得收 SM_SPELL；实得 {:?}",
            sf_seq(&frames, 911)
        );
        assert!(
            raws.iter()
                .any(|(s, p)| *s == 911 && p.starts_with(b"+GD/")),
            "施法者仍应收 +GD ack；实得 {raws:?}"
        );
        assert_eq!(
            sf_count(&frames, 912, mir2_protocol::messages::SM_SPELL),
            1,
            "阳性对照：观察者收恰 1 帧 SM_SPELL"
        );
    }

    /// **J4**：广播范围 = ±`SendRefMsgRange`(=12) 内 `Race==Play && !Ghost` 的**其它**玩家
    /// （`BaseObject.Message.cs:383-445` ⇒ `chat::hear_targets`）——
    /// 近处非 Ghost 观察者收 1 帧；远处（|Δy|=30 > 12）与 Ghost 观察者**都不收**。
    ///
    /// 红检：把广播改成全图（不按 AOI 过滤 / 不过滤 `ghost`）⇒ 必红。
    #[test]
    fn spell_frame_aoi_range_and_ghost_filter() {
        let mut rig = SpellFrameRig::new(
            55,
            &[(55, 9)],
            &[
                ("near", 12, 11, false, 912),
                ("far", 10, 40, false, 913),
                ("ghost", 11, 11, true, 914),
            ],
        );
        rig.cast(55, (12, 12), 0);
        let (frames, _raws) = rig.drain();
        assert_eq!(
            sf_count(&frames, 912, mir2_protocol::messages::SM_SPELL),
            1,
            "AOI 内非 Ghost 观察者收 1 帧"
        );
        assert_eq!(
            sf_count(&frames, 913, mir2_protocol::messages::SM_SPELL),
            0,
            "AOI 外（|Δy|=30 > SendRefMsgRange=12）观察者不得收；实得 {:?}",
            sf_seq(&frames, 913)
        );
        assert_eq!(
            sf_count(&frames, 914, mir2_protocol::messages::SM_SPELL),
            0,
            "Ghost 观察者不得收；实得 {:?}",
            sf_seq(&frames, 914)
        );
    }

    /// **J5**：距离门（`MagicManager.cs:155`）越界 ⇒ **0 帧**。两个子类：
    /// ① 原始点击越界（(20,10)，|Δx|=10 > 8）；② **snap 后**越界（点击 (18,10) 在界、目标实体在
    /// (19,10) 邻域内 ⇒ snap 成 (19,10) ⇒ |Δx|=9 > 8）——口径 = A-5 修好的「门读 snap 后坐标」。
    ///
    /// 红检：把门换回**原始**坐标 ⇒ ② 必红；去掉门 ⇒ ① 必红。
    #[test]
    fn spell_frame_out_of_range_sends_nothing() {
        // ① 原始坐标越界（无目标对象 ⇒ 无 snap）。
        let mut rig = SpellFrameRig::new(55, &[(55, 9)], &[("obs", 12, 12, false, 912)]);
        rig.cast(55, (20, 10), 0);
        let (frames, _raws) = rig.drain();
        assert_eq!(
            sf_count(&frames, 912, mir2_protocol::messages::SM_SPELL),
            0,
            "|Δx|=10 > MagicAttackRage=8 ⇒ 0 帧；实得 {:?}",
            sf_seq(&frames, 912)
        );

        // ② snap 后越界：点击在界、目标实体把坐标推到界外。
        let mut rig = SpellFrameRig::new(55, &[(55, 9)], &[("target", 19, 10, false, 912)]);
        let target = rig
            .online
            .iter()
            .find(|e| e.chr_name == "target")
            .unwrap()
            .actor_id;
        rig.cast(55, (18, 10), target);
        let (frames, _raws) = rig.drain();
        assert_eq!(
            sf_count(&frames, 912, mir2_protocol::messages::SM_SPELL),
            0,
            "snap 后 |Δx|=9 > 8 ⇒ 0 帧（门读 snap 后坐标）；实得 {:?}",
            sf_seq(&frames, 912)
        );
    }

    /// **J6**：帧序 —— `SM_SPELL` 早于 `SM_MAGICFIRE`（oracle `MagicManager.cs:159` 早于 `:648`）。
    /// 取建模面 17（`SKILL_SKELLETON`，带护身符 ⇒ `boSpellFire` 真）。
    ///
    /// 红检：把无条件广播挪到三个效果体块**之后** ⇒ 必红。
    #[test]
    fn spell_frame_spell_precedes_magicfire() {
        let mut rig = SpellFrameRig::new(17, &[(17, 3)], &[("obs", 11, 10, false, 912)]);
        rig.cast(17, (11, 10), 0);
        let (frames, _raws) = rig.drain();
        let seq = sf_seq(&frames, 912);
        let i_spell = seq
            .iter()
            .position(|id| *id == mir2_protocol::messages::SM_SPELL)
            .unwrap_or_else(|| panic!("观察者应收 SM_SPELL；实得 {seq:?}"));
        let i_fire = seq
            .iter()
            .position(|id| *id == mir2_protocol::messages::SM_MAGICFIRE)
            .unwrap_or_else(|| panic!("观察者应收 SM_MAGICFIRE；实得 {seq:?}"));
        assert!(
            i_spell < i_fire,
            "oracle 序：`:159` 的 SM_SPELL 先于 `:648` 的 SM_MAGICFIRE；实得 {seq:?}"
        );
    }

    /// **J7**：战士技能分两类。
    /// ① 12（`SKILL_ERGUM`）——`ClientSpellXY` 的独立 `case`（不进 `default`）**且** `IsWarrSkill`
    ///    命中（两道门各挡一次）⇒ 连 `DoSpell` 都不调用 ⇒ **0 帧**（无 `SM_SPELL`、无 639）。
    /// ② 3/4/7（如 `SKILL_YEDO`）——**进 `default`**（不在 8 条独立 `case` 里）却命中
    ///    `IsWarrSkill`（`MagicManager.cs:82-100` 的 9 个魔号之一）⇒ `MagicManager.cs:151`
    ///    `return false` 在 `:159` 的 `RM_SPELL` **之前** ⇒ 调用方 `Attack.cs:1279-1281` 回
    ///    `RM_MAGICFIREFAIL` ⇒ **恰一条 639**（含自己），且无 `SM_SPELL`/无 MP 扣减/无 53。
    ///
    /// 红检：① 去掉本片新加的 `default_arm && is_warr_skill` 发帧块 ⇒ ② 的 639 计数红；
    /// ② 把战士门挪到 `SM_SPELL` 之后（或从 `!is_warr_skill` 的 RM_SPELL 块里漏过）⇒ ② 的
    /// `SM_SPELL == 0` 断言红。
    #[test]
    fn spell_frame_warr_skill_explicit_case_sends_nothing_and_default_arm_gets_639() {
        // ① 显式 case（12）：两道门都挡 ⇒ 0 帧。
        let mut rig = SpellFrameRig::new(12, &[(12, 3)], &[("obs", 12, 12, false, 912)]);
        rig.cast(12, (12, 12), 0);
        let (frames, raws) = rig.drain();
        assert_eq!(
            sf_count(&frames, 912, mir2_protocol::messages::SM_SPELL),
            0,
            "显式 case（12）不进 default ⇒ 无 SM_SPELL；实得 {:?}",
            sf_seq(&frames, 912)
        );
        assert_eq!(
            frames
                .iter()
                .filter(|(_, b)| sf_ident(b) == mir2_protocol::messages::SM_MAGICFIRE_FAIL)
                .count(),
            0,
            "显式 case 不调用 DoSpell ⇒ 无 639；实得 {:?}",
            sf_seq(&frames, 912)
        );
        assert!(
            raws.iter()
                .any(|(s, p)| *s == 911 && p.starts_with(b"+GD/")),
            "显式 case 仍走完 ClientSpellXY ⇒ 自身收 +GD"
        );

        // ② 走 default 的战士魔号（3/4/7）：恰一条 639，无 SM_SPELL。
        for magic_id in [3u16, 4, 7] {
            let mut rig =
                SpellFrameRig::new(magic_id, &[(magic_id, 3)], &[("obs", 11, 10, false, 912)]);
            rig.ground_sessions
                .get_mut("caster")
                .expect("caster 会话")
                .state
                .wabil
                .mp = 50;
            let seed = 11;
            rig.world.rng = mir2_shared::rng::RandomNumber::with_seed(seed);
            let fresh = mir2_shared::rng::RandomNumber::with_seed(seed);
            let caster = rig.caster;
            rig.cast(magic_id, (11, 10), 0);
            let (frames, raws) = rig.drain();
            let fails: Vec<&(i32, Vec<u8>)> = frames
                .iter()
                .filter(|(_, b)| sf_ident(b) == mir2_protocol::messages::SM_MAGICFIRE_FAIL)
                .collect();
            assert_eq!(
                fails.len(),
                2,
                "[魔号 {magic_id}] 战士门失败 ⇒ 自己 + 同图观察者各一条 639；实得 {:?}",
                sf_seq(&frames, 912)
            );
            assert!(
                fails.iter().any(|(s, _)| *s == 911) && fails.iter().any(|(s, _)| *s == 912),
                "[魔号 {magic_id}] 639 收件人须含自己（无 ActorId 守卫）+ 同图观察者"
            );
            for (_, body) in &fails {
                assert_eq!(
                    *body,
                    smframe_ext::sm_magicfire_fail(caster),
                    "[魔号 {magic_id}] 639 逐字节 = header-only + Recog=施法者"
                );
            }
            for forbidden in [
                mir2_protocol::messages::SM_SPELL,
                mir2_protocol::messages::SM_HEALTHSPELLCHANGED,
                mir2_protocol::messages::SM_MAGICFIRE,
                mir2_protocol::messages::SM_MAGIC_LVEXP,
            ] {
                assert!(
                    !frames.iter().any(|(_, b)| sf_ident(b) == forbidden),
                    "[魔号 {magic_id}] 战士门在 :159/:644 之前 ⇒ 不得有 ident {forbidden}；实得 {:?}",
                    sf_seq(&frames, 912)
                );
            }
            assert_eq!(
                rig.ground_sessions["caster"].state.wabil.mp, 50,
                "[魔号 {magic_id}] IsWarrSkill ⇒ 包装层跳过 ⇒ MP 不变（与蓝不足支对照）"
            );
            assert_eq!(
                draws_between(&fresh, &rig.world.rng),
                0,
                "[魔号 {magic_id}] 战士门 ⇒ 世界 RNG 零抽"
            );
            let mut probe = fresh.clone();
            let mut got = rig.world.rng.clone();
            for k in 0..3 {
                assert_eq!(
                    got.random_below(10),
                    probe.random_below(10),
                    "[魔号 {magic_id}] 阴性对照第 {k} 抽 = 参照流"
                );
            }
            assert_eq!(
                raws.iter()
                    .filter(|(s, p)| *s == 911 && p.starts_with(b"+GD/"))
                    .count(),
                1,
                "[魔号 {magic_id}] 失败仍回 +GD（ClientSpellXY default 支恒 result=true）"
            );
        }
    }

    /// **回归牙（本片独有风险）**：17/20/30/41/46 各一次施法 —— 观察者收**恰一条** `SM_SPELL`
    /// （防「块内发 + 头上发」**双发**），且该魔号原有的后续帧 `SM_MAGICFIRE` 仍在（防错序/发漏）。
    ///
    /// 红检：恢复成「块内发」而不删块内发 ⇒ 计数变 2 必红；把广播挪到效果体之后 ⇒ 序断言必红。
    #[test]
    fn spell_frame_modeled_ids_single_spell_and_followup() {
        for magic_id in [17u16, 20, 30, 41, 46] {
            let mut rig =
                SpellFrameRig::new(magic_id, &[(magic_id, 3)], &[("obs", 11, 10, false, 912)]);
            rig.cast(magic_id, (11, 10), 0);
            let (frames, _raws) = rig.drain();
            let seq = sf_seq(&frames, 912);
            println!("SPELLFRAME_REGRESSION magic_id={magic_id} obs_seq={seq:?}");
            assert_eq!(
                seq.iter()
                    .filter(|id| **id == mir2_protocol::messages::SM_SPELL)
                    .count(),
                1,
                "[魔号 {magic_id}] 一次施法恰一条 SM_SPELL（防双发）；实得 {seq:?}"
            );
            let i_spell = seq
                .iter()
                .position(|id| *id == mir2_protocol::messages::SM_SPELL)
                .expect("应收 SM_SPELL");
            let i_fire = seq
                .iter()
                .position(|id| *id == mir2_protocol::messages::SM_MAGICFIRE)
                .unwrap_or_else(|| {
                    panic!("[魔号 {magic_id}] 后续帧 SM_MAGICFIRE 不得丢；实得 {seq:?}")
                });
            assert!(
                i_spell < i_fire,
                "[魔号 {magic_id}] SM_SPELL 必须仍排在 SM_MAGICFIRE 之前；实得 {seq:?}"
            );
        }
    }

    // ---- 魔号 8（SKILL_FIREWIND）/ 21（SKILL_SPACEMOVE）效果体接线（卡 openmir2-m3-firewind-spacemove-wire）----

    /// 8/21 专用布置的公共件：世界 + 施法者 + 0 号图 / 1 号 Home 图 + 合成注册表 + 会话。
    ///
    /// 注册表用临时目录造两张 64×64 全走格 `.map`（`[0|f0]` / `[home|f1]`）⇒ `id_of("home") == 1`，
    /// 与 `world.maps[1]` 同下标（宿主生产路径同一口径，见 `enter::set_world_map` 的 `/ 1` 约定）。
    #[allow(clippy::type_complexity)]
    fn effect_rig(
        caster_level: u8,
        magic_id: u16,
        home_map: Option<&str>,
        tag: &str,
    ) -> (
        mir2_world::World,
        i32,
        OnlineRegistry,
        std::collections::HashMap<String, SavedHuman>,
        magics::MagicTable,
        downlink::DisplayTable,
        std::collections::HashMap<u8, mpsc::UnboundedSender<SimToGate>>,
        mpsc::UnboundedReceiver<SimToGate>,
        std::path::PathBuf,
    ) {
        use std::collections::HashMap;
        let mut world = mir2_world::World::new(64, 64);
        world.maps.push(mir2_world::MapGrid::new(64, 64));
        world.open_session("caster");
        let mut e = new_player_entity("caster".to_string(), 10, 10);
        e.level = caster_level;
        let caster = world.enter_map("caster", e, 0).expect("进图");
        let mut displays = downlink::DisplayTable::new();
        displays.set(
            caster,
            downlink::ActorDisplay::new(4, 0, 111, 0, 0, 255, b"caster".to_vec()),
        );
        let mut online: OnlineRegistry = Vec::new();
        online_set(
            &mut online,
            OnlineEntry {
                account: "uc".into(),
                chr_name: "caster".into(),
                session_id: 1,
                gate_idx: 0,
                socket: 911,
                actor_id: caster,
            },
        );
        let (tx0, rx) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        let mut record = stage6_record();
        record.data.magic = Some(vec![Some(record::MagicRcd {
            mag_idx: magic_id,
            level: 1,
            magic_key: u16::from(b'm'),
            tran_point: 0,
        })]);
        record.data.home_map = home_map.map(str::to_string);
        let mut saves: HashMap<String, SavedHuman> = HashMap::new();
        saves.insert(
            "caster".into(),
            SavedHuman {
                account: "uc".into(),
                record,
                enter_map: "0".into(),
            },
        );
        // `train_level` 全部拉高 ⇒ 训练尾 `TrainLevel[Level] <= Abil.Level` 恒假 ⇒ 尾**不抽**
        // （本用例只验证效果体的取数，不把共享尾的 `Random(3)` 混进来）。
        let magic_table = magics::MagicTable::new(vec![mir2_data::MagicInfo {
            magic_id,
            effect: 3,
            effect_type: 4,
            train_lv: 3,
            train_level: [255; 4],
            ..mir2_data::MagicInfo::default()
        }]);
        let dir = std::env::temp_dir().join(format!("mir2-m821-{}-{tag}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(dir.join("Envir")).expect("建 Envir");
        std::fs::create_dir_all(dir.join("Map")).expect("建 Map");
        let synth = |w: u16, h: u16| {
            let mut buf = vec![
                0u8;
                mir2_envir::HEADER_BYTES
                    + usize::from(w) * usize::from(h) * mir2_envir::CELL_BYTES
            ];
            buf[0..2].copy_from_slice(&w.to_le_bytes());
            buf[2..4].copy_from_slice(&h.to_le_bytes());
            buf
        };
        std::fs::write(dir.join("Map").join("f0.map"), synth(64, 64)).expect("写 f0");
        std::fs::write(dir.join("Map").join("f1.map"), synth(64, 64)).expect("写 f1");
        std::fs::write(dir.join("Envir").join("MapInfo.txt"), "[0|f0]\n[home|f1]\n")
            .expect("写 MapInfo");
        (
            world,
            caster,
            online,
            saves,
            magic_table,
            displays,
            gates,
            rx,
            dir,
        )
    }

    /// 取一次施法在 gate 通道上产生的帧 `(socket, ident 序列)`（`SendFrame` only）。
    fn effect_drain(rx: &mut mpsc::UnboundedReceiver<SimToGate>) -> Vec<(i32, Vec<u16>)> {
        let mut out: Vec<(i32, Vec<u16>)> = Vec::new();
        while let Ok(m) = rx.try_recv() {
            if let SimToGate::SendFrame { socket, body } = m {
                if body.len() < 6 {
                    continue;
                }
                let ident = u16::from_le_bytes([body[4], body[5]]);
                match out.iter_mut().find(|(s, _)| *s == socket) {
                    Some((_, ids)) => ids.push(ident),
                    None => out.push((socket, vec![ident])),
                }
            }
        }
        out
    }

    fn effect_seq(frames: &[(i32, Vec<u16>)], socket: i32) -> Vec<u16> {
        frames
            .iter()
            .find(|(s, _)| *s == socket)
            .map(|(_, ids)| ids.clone())
            .unwrap_or_default()
    }

    /// **MP 包装层测试台**（`PlayObject.DoSpell`，`PlayObject.Base.cs:1505-1531`）：
    /// 施法者 (10,10)/等级 20、目标 (11,10)/等级 1（`SKILL_FIREWIND` 的推挤需要）；
    /// `magic_spell`/`magic_def_spell` 决定 `GetSpellPoint`，`caster_mp` 是 `WAbil.MP`。
    /// 返回 `(SendFrame（按发送序）, SendRaw, world, ground_sessions, caster, target)`。
    #[allow(clippy::type_complexity)]
    fn mp_wrap_run(
        magic_id: u16,
        magic_spell: u16,
        magic_def_spell: u8,
        caster_mp: u16,
        show_hp: bool,
        seed: i32,
    ) -> (
        Vec<(i32, Vec<u8>)>,
        Vec<(i32, Vec<u8>)>,
        mir2_world::World,
        std::collections::HashMap<String, SessionGround>,
        i32,
        i32,
    ) {
        use std::collections::HashMap;
        let mut world = mir2_world::World::new(64, 64);
        world.maps.push(mir2_world::MapGrid::new(64, 64));
        world.open_session("caster");
        let mut e = new_player_entity("caster".to_string(), 10, 10);
        e.level = 20;
        let caster = world.enter_map("caster", e, 0).expect("进图");
        let target = {
            let mut t = new_player_entity("target".to_string(), 11, 10);
            t.level = 1;
            world.add_entity(t)
        };
        world.tick();
        world.entities.get_mut(caster).unwrap().visible_actors =
            vec![mir2_world::entity::VisibleBaseObject {
                target,
                flag: mir2_world::entity::VisibleFlag::Show,
            }];
        world.rng = mir2_shared::rng::RandomNumber::with_seed(seed);
        let mut displays = downlink::DisplayTable::new();
        displays.set(
            caster,
            downlink::ActorDisplay::new(4, 0, 111, 0, 0, 255, b"caster".to_vec()),
        );
        displays.set(
            target,
            downlink::ActorDisplay::new(4, 0, 112, 0, 0, 255, b"target".to_vec()),
        );
        let mut online: OnlineRegistry = Vec::new();
        online_set(
            &mut online,
            OnlineEntry {
                account: "uc".into(),
                chr_name: "caster".into(),
                session_id: 1,
                gate_idx: 0,
                socket: 911,
                actor_id: caster,
            },
        );
        online_set(
            &mut online,
            OnlineEntry {
                account: "ut".into(),
                chr_name: "target".into(),
                session_id: 2,
                gate_idx: 0,
                socket: 912,
                actor_id: target,
            },
        );
        let (tx0, mut rx) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        let mut record = stage6_record();
        record.data.magic = Some(vec![Some(record::MagicRcd {
            mag_idx: magic_id,
            level: 1,
            magic_key: u16::from(b'm'),
            tran_point: 0,
        })]);
        let mut saves: HashMap<String, SavedHuman> = HashMap::new();
        saves.insert(
            "caster".into(),
            SavedHuman {
                account: "uc".into(),
                record,
                enter_map: "0".into(),
            },
        );
        // `train_level = 255` ⇒ 训练尾 `TrainLevel[Level] <= Abil.Level` 恒假（不混入尾抽数）。
        let magic_table = magics::MagicTable::new(vec![mir2_data::MagicInfo {
            magic_id,
            effect: 3,
            effect_type: 4,
            spell: magic_spell,
            def_spell: magic_def_spell,
            train_lv: 3,
            train_level: [255; 4],
            ..mir2_data::MagicInfo::default()
        }]);
        let mut ground_sessions: HashMap<String, SessionGround> = HashMap::new();
        let mut sg = spell_session_ground(caster);
        sg.state.wabil.hp = 30;
        sg.state.wabil.mp = caster_mp;
        sg.state.wabil.max_hp = 100;
        sg.state.wabil.max_mp = 100;
        sg.show_hp = show_hp;
        ground_sessions.insert("caster".into(), sg);
        let catalog = game_svr::ability::StdItemCatalog::new();
        let pet_cfg = mir2_data::pet_slave::PetSlaveConfig::default();
        let table = game_svr::mongen::MonsterTable::new(Vec::new());
        handle_spell_cmd(
            game_svr::feature::make_long(11, 10),
            magic_id,
            0,
            0,
            "caster",
            911,
            &online,
            &mut world,
            &mut saves,
            &mut ground_sessions,
            &catalog,
            &magic_table,
            &pet_cfg,
            8,
            None,
            &table,
            &mut displays,
            &gates,
            1,
            1,
            2,
        );
        let mut frames = Vec::new();
        let mut raws = Vec::new();
        while let Ok(msg) = rx.try_recv() {
            match msg {
                SimToGate::SendFrame { socket, body } => frames.push((socket, body)),
                SimToGate::SendRaw { socket, payload } => raws.push((socket, payload)),
                _ => {}
            }
        }
        (frames, raws, world, ground_sessions, caster, target)
    }

    fn mp_ident(body: &[u8]) -> u16 {
        u16::from_le_bytes([body[4], body[5]])
    }

    /// **判据①（MP 包装层，生产入口 `handle_spell_cmd`）**：蓝足 ⇒ MP 恰减 `GetSpellPoint`
    /// （= `Round(Spell/4*(Level+1)) + DefSpell` = `Round(8/4*2)+2 = 6`）；
    /// `SM_HEALTHSPELLCHANGED(53)` 在 `SM_SPELL(17)` **之前**，且 53 的 `(hp, mp)` = 扣后值；
    /// `SM_SPELL` 与效果体帧与「`spell=0` 对照 run」逐字节相同。
    ///
    /// 红检（变异牙）：① 去掉「蓝不足早退」⇒ 判据②红；② 把 53 移到 `SM_SPELL` 之后 ⇒ 本用例红；
    /// ③ 扣减公式改 `+1` ⇒ 本用例红（实测记录见补丁说明）。
    #[test]
    fn spell_cmd_mp_wrapper_deducts_and_health_frame_precedes_spell() {
        let magic_id = mir2_world::magic::SKILL_FIREWIND;
        let (frames, _raws, _world, sessions, caster, _target) =
            mp_wrap_run(magic_id, 8, 2, 50, false, 1);
        let want = mir2_world::magic::get_spell_point(
            &mir2_data::MagicInfo {
                spell: 8,
                def_spell: 2,
                ..mir2_data::MagicInfo::default()
            },
            1,
        );
        assert_eq!(want, 6, "期望表自洽：Round(8/4*2)+2 = 6");
        assert_eq!(
            sessions["caster"].state.wabil.mp,
            50 - want,
            "oracle DamageSpell：MP 恰减 GetSpellPoint"
        );

        // 53 只给自己（ShowHp=false ⇒ 无 SendRefMsg 支），且先于 SM_SPELL。
        let i_53 = frames
            .iter()
            .position(|(s, b)| {
                *s == 911 && mp_ident(b) == mir2_protocol::messages::SM_HEALTHSPELLCHANGED
            })
            .expect("蓝足 ⇒ HealthSpellChanged 必发 53 给自己");
        let i_spell = frames
            .iter()
            .position(|(_, b)| mp_ident(b) == mir2_protocol::messages::SM_SPELL)
            .expect("效果层 RM_SPELL ⇒ SM_SPELL");
        assert!(
            i_53 < i_spell,
            "oracle 序：DamageSpell/HealthSpellChanged（:1518-1519）先于 RM_SPELL（:159）；实得序 {frames:?}"
        );
        // 53 的 header 字段 = 扣后值（param=HP、tag=MP、series=MaxHP）。
        let b53 = &frames[i_53].1;
        assert_eq!(
            b53[0..4],
            caster.to_le_bytes(),
            "53 的 Recog = 施法者 ActorId"
        );
        assert_eq!(u16::from_le_bytes([b53[6], b53[7]]), 30, "53.HP = 扣后 HP");
        assert_eq!(
            u16::from_le_bytes([b53[8], b53[9]]),
            44,
            "53.MP = 扣后 MP（50-6）"
        );
        assert_eq!(u16::from_le_bytes([b53[10], b53[11]]), 100, "53.MaxHP");
        assert_eq!(
            frames
                .iter()
                .filter(|(_, b)| mp_ident(b) == mir2_protocol::messages::SM_HEALTHSPELLCHANGED)
                .count(),
            1,
            "ShowHp=false ⇒ 仅 SendUpdateMsg 一条（无 SendRefMsg 支）"
        );

        // 效果体帧不受扣 MP 影响：与 spell=0 的对照 run 逐字节相同（滤掉 53）。
        let (ctrl_frames, _craws, _w, _cs, _c, _t) = mp_wrap_run(magic_id, 0, 0, 50, false, 1);
        let a: Vec<_> = frames
            .iter()
            .filter(|(_, b)| mp_ident(b) != mir2_protocol::messages::SM_HEALTHSPELLCHANGED)
            .cloned()
            .collect();
        assert_eq!(
            a, ctrl_frames,
            "SM_SPELL 与效果体帧须与 spell=0 对照逐字节相同"
        );
        assert!(
            ctrl_frames
                .iter()
                .any(|(_, b)| mp_ident(b) == mir2_protocol::messages::SM_BACKSTEP),
            "前提：效果体确实跑起来（有 SM_BACKSTEP）"
        );
    }

    /// **判据②（蓝不足早退）**：`MP(5) < nSpellPoint(6)` ⇒ `DoSpell` 包装层 `return false`：
    /// 零 `SM_SPELL`/效果体帧/`SM_BACKSTEP`；世界 RNG 零抽数（随后连续三抽对照）；MP 不变；
    /// 恰一条逻辑 `SM_MAGICFIRE_FAIL(639)`，ActorId = 施法者，收件人 = `RM_MAGICFIREFAIL` 的
    /// `SendRefMsg` 集合（含自己 + 同图观察者；处理器无 `ActorId != ActorId` 守卫）。
    #[test]
    fn spell_cmd_mp_wrapper_insufficient_mp_fails_without_frames_or_draws() {
        use mir2_shared::rng::RandomNumber;
        let seed = 7;
        let magic_id = mir2_world::magic::SKILL_FIREWIND;
        let (frames, raws, world, sessions, caster, _target) =
            mp_wrap_run(magic_id, 8, 2, 5, false, seed);

        assert_eq!(
            sessions["caster"].state.wabil.mp, 5,
            "蓝不足 ⇒ 不扣 MP（早退在 DamageSpell 之前）"
        );
        let ids: Vec<u16> = frames.iter().map(|(_, b)| mp_ident(b)).collect();
        for forbidden in [
            mir2_protocol::messages::SM_SPELL,
            mir2_protocol::messages::SM_BACKSTEP,
            mir2_protocol::messages::SM_MAGICFIRE,
            mir2_protocol::messages::SM_HEALTHSPELLCHANGED,
        ] {
            assert!(
                !ids.contains(&forbidden),
                "蓝不足 ⇒ 不得有 ident {forbidden}；实得 {ids:?}"
            );
        }
        // 世界 RNG 零抽数：状态 == 全新同 seed 流；随后连续三抽也与参照流逐项相同。
        let fresh = RandomNumber::with_seed(seed);
        assert_eq!(
            draws_between(&fresh, &world.rng),
            0,
            "蓝不足 ⇒ 一个随机数都不抽（早退在效果体/尾之前）"
        );
        let mut probe = fresh.clone();
        let mut got = world.rng.clone();
        for k in 0..3 {
            assert_eq!(
                got.random_below(10),
                probe.random_below(10),
                "阴性对照第 {k} 抽 = 参照流（世界 RNG 未被消费）"
            );
        }
        // 恰一条逻辑 639：`RM_MAGICFIREFAIL` 的 SendRefMsg 收件人 = 自己 + 同图观察者。
        let fails: Vec<&(i32, Vec<u8>)> = frames
            .iter()
            .filter(|(_, b)| mp_ident(b) == mir2_protocol::messages::SM_MAGICFIRE_FAIL)
            .collect();
        assert_eq!(fails.len(), 2, "含自己（911）+ 同图观察者（912）各一条");
        for (_sock, body) in &fails {
            assert_eq!(body[0..4], caster.to_le_bytes(), "639 的 Recog = 施法者");
        }
        assert!(
            frames.iter().filter(|(s, _)| *s == 912).count() == 1,
            "观察者恰好收到一条 639"
        );
        assert!(
            fails.iter().any(|(s, _)| *s == 911),
            "施法者自己也收到（无 ActorId 守卫）"
        );
        assert!(fails.iter().any(|(s, _)| *s == 912), "同图观察者收到");
        // 调用方 `Attack.cs:1282` 的 `result = true` ⇒ 蓝不足仍回 `+GD`（`PlayObject.Message.cs:1343`）。
        assert_eq!(
            raws.iter()
                .filter(|(s, p)| *s == 911 && p.starts_with(b"+GD/"))
                .count(),
            1,
            "蓝不足仍须给施法者回 +GD（ClientSpellXY default 支恒 result=true）"
        );
    }

    /// **判据③（`nSpellPoint == 0`）**：`spell = def_spell = 0` ⇒ 不扣 MP、不发 53、正常施放
    /// （`SM_SPELL` + 效果体照常）。
    #[test]
    fn spell_cmd_mp_wrapper_zero_spell_point_is_transparent() {
        let magic_id = mir2_world::magic::SKILL_FIREWIND;
        let (frames, raws, _world, sessions, _caster, _target) =
            mp_wrap_run(magic_id, 0, 0, 50, false, 3);
        assert_eq!(
            sessions["caster"].state.wabil.mp, 50,
            "nSpellPoint=0 ⇒ 不扣 MP"
        );
        let ids: Vec<u16> = frames.iter().map(|(_, b)| mp_ident(b)).collect();
        assert!(
            !ids.contains(&mir2_protocol::messages::SM_HEALTHSPELLCHANGED),
            "nSpellPoint=0 ⇒ 不发 53"
        );
        assert!(
            ids.contains(&mir2_protocol::messages::SM_SPELL),
            "正常施放 SM_SPELL"
        );
        assert!(
            ids.contains(&mir2_protocol::messages::SM_BACKSTEP),
            "效果体照常（8 推挤目标）"
        );
        assert_eq!(
            raws.iter()
                .filter(|(s, p)| *s == 911 && p.starts_with(b"+GD/"))
                .count(),
            1,
            "正常施放同样回 +GD"
        );
    }

    /// **距离门失败测试台**（`MagicManager.cs:155-157` ⇒ 调用方
    /// `PlayObject.Attack.cs:1279-1281` 回 `RM_MAGICFIREFAIL`）：
    /// 施法者 (10,10)/等级 20；**只有施法者自己在线**（无观察者 ⇒ 捕获队列里
    /// `SM_MAGICFIRE_FAIL` 恰一条，且能直接核对「处理器无 `ActorId != ActorId` 守卫」）；
    /// 点击点由入参给、且不建目标实体（`target_actor_id = 0` ⇒ `CretInNearXy` 不命中、
    /// 不做 snap，距离门读的就是点击点）。
    /// `magic_spell`/`magic_def_spell` 决定 `GetSpellPoint`，`caster_mp` 是 `WAbil.MP`。
    #[allow(clippy::type_complexity)]
    fn distfail_run(
        magic_id: u16,
        magic_spell: u16,
        magic_def_spell: u8,
        caster_mp: u16,
        target_x: u16,
        target_y: u16,
        seed: i32,
    ) -> (
        Vec<(i32, Vec<u8>)>,
        Vec<(i32, Vec<u8>)>,
        mir2_world::World,
        std::collections::HashMap<String, SessionGround>,
        i32,
    ) {
        use std::collections::HashMap;
        let mut world = mir2_world::World::new(64, 64);
        world.maps.push(mir2_world::MapGrid::new(64, 64));
        world.open_session("caster");
        let mut e = new_player_entity("caster".to_string(), 10, 10);
        e.level = 20;
        let caster = world.enter_map("caster", e, 0).expect("进图");
        world.tick();
        world.rng = mir2_shared::rng::RandomNumber::with_seed(seed);
        let mut displays = downlink::DisplayTable::new();
        displays.set(
            caster,
            downlink::ActorDisplay::new(4, 0, 111, 0, 0, 255, b"caster".to_vec()),
        );
        let mut online: OnlineRegistry = Vec::new();
        online_set(
            &mut online,
            OnlineEntry {
                account: "uc".into(),
                chr_name: "caster".into(),
                session_id: 1,
                gate_idx: 0,
                socket: 911,
                actor_id: caster,
            },
        );
        let (tx0, mut rx) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        let mut record = stage6_record();
        record.data.magic = Some(vec![Some(record::MagicRcd {
            mag_idx: magic_id,
            level: 1,
            magic_key: u16::from(b'm'),
            tran_point: 0,
        })]);
        let mut saves: HashMap<String, SavedHuman> = HashMap::new();
        saves.insert(
            "caster".into(),
            SavedHuman {
                account: "uc".into(),
                record,
                enter_map: "0".into(),
            },
        );
        let magic_table = magics::MagicTable::new(vec![mir2_data::MagicInfo {
            magic_id,
            effect: 3,
            effect_type: 4,
            spell: magic_spell,
            def_spell: magic_def_spell,
            train_lv: 3,
            train_level: [255; 4],
            ..mir2_data::MagicInfo::default()
        }]);
        let mut ground_sessions: HashMap<String, SessionGround> = HashMap::new();
        let mut sg = spell_session_ground(caster);
        sg.state.wabil.hp = 30;
        sg.state.wabil.mp = caster_mp;
        sg.state.wabil.max_hp = 100;
        sg.state.wabil.max_mp = 100;
        sg.show_hp = false;
        ground_sessions.insert("caster".into(), sg);
        let catalog = game_svr::ability::StdItemCatalog::new();
        let pet_cfg = mir2_data::pet_slave::PetSlaveConfig::default();
        let table = game_svr::mongen::MonsterTable::new(Vec::new());
        handle_spell_cmd(
            game_svr::feature::make_long(target_x, target_y),
            magic_id,
            0,
            0,
            "caster",
            911,
            &online,
            &mut world,
            &mut saves,
            &mut ground_sessions,
            &catalog,
            &magic_table,
            &pet_cfg,
            8,
            None,
            &table,
            &mut displays,
            &gates,
            1,
            1,
            2,
        );
        let mut frames = Vec::new();
        let mut raws = Vec::new();
        while let Ok(msg) = rx.try_recv() {
            match msg {
                SimToGate::SendFrame { socket, body } => frames.push((socket, body)),
                SimToGate::SendRaw { socket, payload } => raws.push((socket, payload)),
                _ => {}
            }
        }
        (frames, raws, world, ground_sessions, caster)
    }

    /// **判据①（距离门失败 ⇒ 639，生产入口 `handle_spell_cmd`）**：越界施法
    /// （点击 (25,25)，|Δ| = 15 > `MagicAttackRage` = 8）⇒ 捕获队列里**恰一条**
    /// `SM_MAGICFIRE_FAIL(639)`（Recog = 施法者、字节 == [`smframe_ext::sm_magicfire_fail`]）；
    /// **无** `SM_SPELL`、无任何效果体帧；世界 RNG **零抽数**（随后连续三抽与参照流逐项相同）。
    /// 魔号 14（A-5 buff 生产者）与 8（`default` 支效果体）各跑一遍。
    ///
    /// 红检（变异牙，实测见补丁说明）：① 去掉 `else` 里的 639 ⇒ 本用例红；② 在效果体块里
    /// 再发一次 639 ⇒「恰一条」红。
    #[test]
    fn spell_cmd_distance_gate_failure_emits_exactly_one_639() {
        use mir2_shared::rng::RandomNumber;
        for magic_id in [
            mir2_world::world::SKILL_HANGMAJINBUB,
            mir2_world::magic::SKILL_FIREWIND,
        ] {
            let seed = 7;
            let (frames, raws, world, sessions, caster) =
                distfail_run(magic_id, 0, 0, 50, 25, 25, seed);
            assert_eq!(
                frames.len(),
                1,
                "[魔号 {magic_id}] 越界 ⇒ 捕获队列恰 1 帧；实得 {frames:?}"
            );
            let (sock, body) = &frames[0];
            assert_eq!(*sock, 911, "[魔号 {magic_id}] 唯一的帧发给施法者自己");
            assert_eq!(
                mp_ident(body),
                mir2_protocol::messages::SM_MAGICFIRE_FAIL,
                "[魔号 {magic_id}] 越界 ⇒ 唯一帧是 639；实得 {body:?}"
            );
            assert_eq!(
                body,
                &smframe_ext::sm_magicfire_fail(caster),
                "[魔号 {magic_id}] 639 逐字节 = header-only + Recog=施法者"
            );
            assert!(
                !frames
                    .iter()
                    .any(|(_, b)| mp_ident(b) == mir2_protocol::messages::SM_SPELL),
                "[魔号 {magic_id}] 越界 ⇒ 不得有 SM_SPELL"
            );
            assert!(
                !frames
                    .iter()
                    .any(|(_, b)| mp_ident(b) == mir2_protocol::messages::SM_HEALTHSPELLCHANGED),
                "[魔号 {magic_id}] spell=0 ⇒ 无 53"
            );
            assert_eq!(sessions["caster"].state.wabil.mp, 50, "spell=0 ⇒ MP 不变");
            // 世界 RNG 零抽数：状态 == 全新同 seed 流；随后连续三抽也与参照流逐项相同。
            let fresh = RandomNumber::with_seed(seed);
            assert_eq!(
                draws_between(&fresh, &world.rng),
                0,
                "[魔号 {magic_id}] 越界 ⇒ 距离门在任何取数之前 return false"
            );
            let mut probe = fresh.clone();
            let mut got = world.rng.clone();
            for k in 0..3 {
                assert_eq!(
                    got.random_below(10),
                    probe.random_below(10),
                    "[魔号 {magic_id}] 阴性对照第 {k} 抽 = 参照流（世界 RNG 未被消费）"
                );
            }
            // 调用方 `Attack.cs:1282` 的 `result = true` ⇒ 越界仍回 `+GD`。
            assert_eq!(
                raws.iter()
                    .filter(|(s, p)| *s == 911 && p.starts_with(b"+GD/"))
                    .count(),
                1,
                "[魔号 {magic_id}] 越界仍须给施法者回 +GD（ClientSpellXY default 支恒 result=true）"
            );
        }
    }

    /// **判据②（越界仍扣 MP，且 53 先于 639）**：MP 包装层在 `DoSpell` **之前**
    /// （`PlayObject.Base.cs:1518-1521`）⇒ 越界同样按 `GetSpellPoint` 扣减并发 53；
    /// 随后距离门失败回 639。magic 8 / spell 8 / def 2 / level 1 / MP 50 ⇒ MP 44。
    #[test]
    fn spell_cmd_distance_gate_failure_deducts_mp_before_639() {
        let magic_id = mir2_world::magic::SKILL_FIREWIND;
        let (frames, raws, _world, sessions, caster) = distfail_run(magic_id, 8, 2, 50, 25, 25, 1);
        assert_eq!(
            sessions["caster"].state.wabil.mp, 44,
            "Round(8/4*2)+2 = 6 ⇒ 越界也扣 MP（wrapper 先于 DoSpell）"
        );
        let ids: Vec<u16> = frames.iter().map(|(_, b)| mp_ident(b)).collect();
        assert_eq!(
            ids.iter()
                .filter(|id| **id == mir2_protocol::messages::SM_HEALTHSPELLCHANGED)
                .count(),
            1,
            "越界 ⇒ 53 照发（恰一条，只给自己）；实得 {ids:?}"
        );
        assert_eq!(
            ids.iter()
                .filter(|id| **id == mir2_protocol::messages::SM_MAGICFIRE_FAIL)
                .count(),
            1,
            "越界 ⇒ 恰一条 639；实得 {ids:?}"
        );
        let i_53 = ids
            .iter()
            .position(|id| *id == mir2_protocol::messages::SM_HEALTHSPELLCHANGED)
            .expect("53 必发");
        let i_639 = ids
            .iter()
            .position(|id| *id == mir2_protocol::messages::SM_MAGICFIRE_FAIL)
            .expect("639 必发");
        assert!(
            i_53 < i_639,
            "oracle 序：HealthSpellChanged（:1519）先于 DoSpell 失败回帧（Attack.cs:1279）；实得 {ids:?}"
        );
        let b53 = &frames[i_53].1;
        assert_eq!(u16::from_le_bytes([b53[6], b53[7]]), 30, "53.HP");
        assert_eq!(u16::from_le_bytes([b53[8], b53[9]]), 44, "53.MP = 扣后值");
        assert_eq!(u16::from_le_bytes([b53[10], b53[11]]), 100, "53.MaxHP");
        assert_eq!(
            &frames[i_639].1,
            &smframe_ext::sm_magicfire_fail(caster),
            "639 逐字节 = Recog 施法者"
        );
        assert!(
            !ids.contains(&mir2_protocol::messages::SM_SPELL),
            "越界 ⇒ 无 SM_SPELL；实得 {ids:?}"
        );
        assert_eq!(
            raws.iter()
                .filter(|(s, p)| *s == 911 && p.starts_with(b"+GD/"))
                .count(),
            1,
            "越界仍回 +GD"
        );
    }

    /// **判据③（阴性对照：in-range）**：同一生产入口、目标在门内（施法者 (10,10)、
    /// 点击 (11,10)，|Δ| = 1 ≤ 8）⇒ 恰一条 `SM_SPELL`，**无** 639。
    #[test]
    fn spell_cmd_distance_gate_in_range_has_no_639() {
        let (frames, _raws, _world, _sessions, _caster, _target) =
            mp_wrap_run(mir2_world::magic::SKILL_FIREWIND, 8, 2, 50, false, 1);
        let ids: Vec<u16> = frames.iter().map(|(_, b)| mp_ident(b)).collect();
        assert_eq!(
            ids.iter()
                .filter(|id| **id == mir2_protocol::messages::SM_SPELL)
                .count(),
            1,
            "门内 ⇒ 恰一条 SM_SPELL；实得 {ids:?}"
        );
        assert!(
            !ids.contains(&mir2_protocol::messages::SM_MAGICFIRE_FAIL),
            "门内 ⇒ 不得有 639；实得 {ids:?}"
        );
    }

    // ---- 片 `openmir2-spell-dospell-fail-rest`：`DoSpell` 其余 false 路径的 639 ----
    //
    // oracle：`MagicManager.DoSpell` 的 `:151-153` 战士门与 `:644-647 if (boSpellFail) return false`
    // 都 `return false` ⇒ `ClientSpellXY` 的 default 支回 `RM_MAGICFIREFAIL`
    // （`PlayObject.Attack.cs:1279-1281`）⇒ `SM_MAGICFIRE_FAIL(639)`。全部用例走**生产入口**
    // `handle_spell_cmd`，断言一律「恰一条 / 不含某 ident / 逐字节 / 零抽」，不用单抽。

    /// **召唤面（17/30/41）护身符门失败 ⇒ 恰一条 639**（`MagicManager.cs:322/451/463` 的
    /// `boSpellFail = true` 保持到 `:644-647`）。
    ///
    /// 布置：施法者 (10,10)/socket 911、同图观察者 (11,10)/socket 912；`ArmRingl` 槽**清空**
    /// （三档需求 1/5/2 全部不满足）⇒ `CheckAmulet` 不过。`spell = def_spell = 0` ⇒ MP 包装层
    /// 透明（无 53，便于把 639 之外的帧面收窄到 `:159` 的 `SM_SPELL`）。
    ///
    /// oracle 帧面：`:159 SM_SPELL`（观察者收；施法者那条连接因 `RmSpell` 的自守卫不收）→
    /// `:644-647 return false` → 调用方 639（**含自己**，处理器无自守卫）。
    /// **不得**有 `SM_MAGICFIRE`（`:648` 在 return 之后）或 `SM_MAGIC_LVEXP`（`:659` 同）。
    ///
    /// 牙（实测后复原）：① 去掉召唤块的 `!outcome.accepted` 发帧 ⇒ 本用例红（639 计数 0）；
    /// ② 在成功支也发 639 ⇒ [`spell_cmd_slave_amulet_gate_success_has_no_639`] 红；
    /// ③ 让失败支仍走尾（`bo_spell_fail=false`）⇒ 本用例的 `SM_MAGICFIRE`/尾帧/RNG 断言红。
    #[test]
    fn spell_cmd_slave_amulet_gate_failure_emits_exactly_one_639() {
        use mir2_shared::rng::RandomNumber;
        for magic_id in [17u16, 30, 41] {
            let mut rig =
                SpellFrameRig::new(magic_id, &[(magic_id, 3)], &[("obs", 11, 10, false, 912)]);
            // `CheckAmulet`：ArmRingl / Bujuk 都查；这里把 ArmRingl 清空（Bujuk 本就 None）。
            rig.ground_sessions
                .get_mut("caster")
                .expect("caster 会话")
                .use_items[game_svr::ability::SLOT_ARMRING_L] = None;
            rig.ground_sessions
                .get_mut("caster")
                .expect("caster 会话")
                .state
                .wabil
                .mp = 50;
            let seed = 23;
            rig.world.rng = RandomNumber::with_seed(seed);
            let fresh = RandomNumber::with_seed(seed);
            let caster = rig.caster;
            rig.cast(magic_id, (11, 10), 0);
            let (frames, raws) = rig.drain();

            // 恰一条 639 给自己 + 一条给同图观察者，Recog = 施法者，字节 = 编码器输出。
            let fails: Vec<&(i32, Vec<u8>)> = frames
                .iter()
                .filter(|(_, b)| sf_ident(b) == mir2_protocol::messages::SM_MAGICFIRE_FAIL)
                .collect();
            assert_eq!(
                fails.len(),
                2,
                "[魔号 {magic_id}] 护身符门失败 ⇒ 自己 + 同图观察者各一条 639；实得 {:?}",
                sf_seq(&frames, 912)
            );
            assert!(
                fails.iter().any(|(s, _)| *s == 911) && fails.iter().any(|(s, _)| *s == 912),
                "[魔号 {magic_id}] 639 收件人须含自己 + 同图观察者"
            );
            for (_, body) in &fails {
                assert_eq!(
                    *body,
                    smframe_ext::sm_magicfire_fail(caster),
                    "[魔号 {magic_id}] 639 逐字节 = header-only + Recog=施法者"
                );
            }

            // `:159` 的 SM_SPELL：观察者恰 1 条；施法者自己那条连接不收（RM_SPELL 有自守卫）。
            let obs_seq = sf_seq(&frames, 912);
            let self_seq = sf_seq(&frames, 911);
            assert_eq!(
                obs_seq
                    .iter()
                    .filter(|id| **id == mir2_protocol::messages::SM_SPELL)
                    .count(),
                1,
                "[魔号 {magic_id}] oracle 在 :159 先发 SM_SPELL（失败在 :644 之后才发生）⇒ 观察者恰 1 条；实得 {obs_seq:?}"
            );
            assert_eq!(
                self_seq
                    .iter()
                    .filter(|id| **id == mir2_protocol::messages::SM_SPELL)
                    .count(),
                0,
                "[魔号 {magic_id}] 施法者连接不收 SM_SPELL（RM_SPELL 自守卫）；实得 {self_seq:?}"
            );
            // 帧序：SM_SPELL（:159）先于 639（:644 之后）。
            let i_spell = obs_seq
                .iter()
                .position(|id| *id == mir2_protocol::messages::SM_SPELL)
                .expect("观察者收 SM_SPELL");
            let i_fail = obs_seq
                .iter()
                .position(|id| *id == mir2_protocol::messages::SM_MAGICFIRE_FAIL)
                .expect("观察者收 639");
            assert!(
                i_spell < i_fail,
                "[魔号 {magic_id}] oracle 序 :159 的 SM_SPELL 先于失败回帧；实得 {obs_seq:?}"
            );

            // 失败在共享尾之前 ⇒ 无 RM_MAGICFIRE、无训练尾、无 53。
            for forbidden in [
                mir2_protocol::messages::SM_MAGICFIRE,
                mir2_protocol::messages::SM_MAGIC_LVEXP,
                mir2_protocol::messages::SM_HEALTHSPELLCHANGED,
            ] {
                assert!(
                    !frames.iter().any(|(_, b)| sf_ident(b) == forbidden),
                    "[魔号 {magic_id}] boSpellFail ⇒ 不得有 ident {forbidden}；实得 {obs_seq:?}"
                );
            }
            assert_eq!(
                rig.ground_sessions["caster"].state.wabil.mp, 50,
                "[魔号 {magic_id}] spell=def_spell=0 ⇒ MP 包装层透明"
            );

            // 世界 RNG 零抽：护身符门/共享尾都在任何取数之前返回。
            assert_eq!(
                draws_between(&fresh, &rig.world.rng),
                0,
                "[魔号 {magic_id}] boSpellFail ⇒ 世界 RNG 零抽"
            );
            let mut probe = fresh.clone();
            let mut got = rig.world.rng.clone();
            for k in 0..3 {
                assert_eq!(
                    got.random_below(10),
                    probe.random_below(10),
                    "[魔号 {magic_id}] 阴性对照第 {k} 抽 = 参照流"
                );
            }
            assert_eq!(
                raws.iter()
                    .filter(|(s, p)| *s == 911 && p.starts_with(b"+GD/"))
                    .count(),
                1,
                "[魔号 {magic_id}] 失败仍回 +GD（ClientSpellXY default 支恒 result=true）"
            );
        }
    }

    /// **成功支对照（阳性）**：护身符门通过 ⇒ `accepted == true` ⇒ **无 639**、
    /// `SM_SPELL`（`:159`）+ `SM_MAGICFIRE`（`:648`）+ 训练尾取数照旧。
    ///
    /// 与 [`spell_cmd_slave_amulet_gate_failure_emits_exactly_one_639`] 同一夹具，唯一差别 =
    /// `ArmRingl` 里有耐久 600 的护身符（`Round(600/100)=6` ≥ 三档需求 1/5/2）。
    /// 红检：本片若在 `accepted == true` 时也发 639 ⇒ 本用例红。
    #[test]
    fn spell_cmd_slave_amulet_gate_success_has_no_639() {
        use mir2_shared::rng::RandomNumber;
        for magic_id in [17u16, 30, 41] {
            let mut rig =
                SpellFrameRig::new(magic_id, &[(magic_id, 3)], &[("obs", 11, 10, false, 912)]);
            let seed = 5;
            rig.world.rng = RandomNumber::with_seed(seed);
            let fresh = RandomNumber::with_seed(seed);
            rig.cast(magic_id, (11, 10), 0);
            let (frames, _raws) = rig.drain();
            let obs_seq = sf_seq(&frames, 912);
            assert_eq!(
                obs_seq
                    .iter()
                    .filter(|id| **id == mir2_protocol::messages::SM_MAGICFIRE_FAIL)
                    .count(),
                0,
                "[魔号 {magic_id}] accepted=true ⇒ 不得有 639；实得 {obs_seq:?}"
            );
            assert_eq!(
                obs_seq
                    .iter()
                    .filter(|id| **id == mir2_protocol::messages::SM_SPELL)
                    .count(),
                1,
                "[魔号 {magic_id}] 成功支仍恰 1 条 SM_SPELL；实得 {obs_seq:?}"
            );
            assert_eq!(
                obs_seq
                    .iter()
                    .filter(|id| **id == mir2_protocol::messages::SM_MAGICFIRE)
                    .count(),
                1,
                "[魔号 {magic_id}] 成功支共享尾 :648 ⇒ 观察者恰 1 条 SM_MAGICFIRE；实得 {obs_seq:?}"
            );
            // 帧面与现状逐项相同：观察者恰 `[SM_SPELL, SM_MAGICFIRE]`（`:159` 先于 `:648`），
            // 本片新增的 `!accepted` 支不得插入任何帧。
            assert_eq!(
                obs_seq,
                vec![
                    mir2_protocol::messages::SM_SPELL,
                    mir2_protocol::messages::SM_MAGICFIRE
                ],
                "[魔号 {magic_id}] 成功支帧序须与现状一致（SM_SPELL → SM_MAGICFIRE）"
            );
            // 取数与现状相同：本夹具的 `MonsterTable`/`MapRegistry` 皆空 ⇒ 召唤不 `Spawned`
            // ⇒ `boTrain=false` ⇒ `:659` 训练尾门不过 ⇒ **0 抽**（现状如此；召唤成功支的
            // `Random(3)+1` 次序由 `crates/world::slave` 的既有用例覆盖）。本片不碰成功路径。
            assert_eq!(
                draws_between(&fresh, &rig.world.rng),
                0,
                "[魔号 {magic_id}] 成功支取数须与现状相同（本夹具 boTrain=false ⇒ 0 抽）"
            );
        }
    }

    /// **魔号 8 正例（生产入口 `handle_spell_cmd`）**：效果体被进入、取数逐项等于 oracle 期望、
    /// 位移与 oracle 一致、帧序 `SM_SPELL < SM_BACKSTEP* < SM_MAGICFIRE`。
    ///
    /// 期望表**独立复算**：另起一条同 seed 的 `RandomNumber`，按 `MagicManager.cs:37/41` 的
    /// 字面式重算 `Random(20)` 门与 `Random(2)` 步数；落点用**已验收**的
    /// [`mir2_world::magic::char_pushed`]（对拍向量覆盖）在同一初始格上复算。
    #[test]
    fn spell_cmd_firewind_enters_effect_draws_and_pushes() {
        use mir2_shared::rng::RandomNumber;
        let (
            mut world,
            caster,
            mut online,
            mut saves,
            magic_table,
            mut displays,
            gates,
            mut rx,
            dir,
        ) = effect_rig(20, mir2_world::magic::SKILL_FIREWIND, None, "fw");
        // 目标：相邻（11,10）、等级 15；远端（20,20）也在 VisibleActors 里（应被 |Δ|<=1 门挡掉）。
        let target = {
            let mut e = new_player_entity("target".to_string(), 11, 10);
            e.level = 15;
            world.add_entity(e)
        };
        let far = {
            let mut e = new_player_entity("far".to_string(), 20, 20);
            e.level = 15;
            world.add_entity(e)
        };
        world.tick();
        displays.set(
            target,
            downlink::ActorDisplay::new(4, 0, 112, 0, 0, 255, b"target".to_vec()),
        );
        online_set(
            &mut online,
            OnlineEntry {
                account: "ut".into(),
                chr_name: "target".into(),
                session_id: 2,
                gate_idx: 0,
                socket: 912,
                actor_id: target,
            },
        );
        world.entities.get_mut(caster).unwrap().visible_actors = vec![
            mir2_world::entity::VisibleBaseObject {
                target: far,
                flag: mir2_world::entity::VisibleFlag::Show,
            },
            mir2_world::entity::VisibleBaseObject {
                target,
                flag: mir2_world::entity::VisibleFlag::Show,
            },
        ];
        let seed = 1;
        world.rng = RandomNumber::with_seed(seed);
        let before = world.rng.clone();
        // ---- 期望表（独立复算）----
        let mut exp = RandomNumber::with_seed(seed);
        let gap = 20 - 15;
        let push_level = 1;
        let want_chance = exp.random_below(20) < 6 + push_level * 3 + gap;
        let want_steps = if want_chance {
            1 + exp.random_below(2)
        } else {
            0
        };
        assert!(want_chance, "本 seed 必须让门通过，否则正例无判别力");
        let mut probe_map = mir2_world::MapGrid::new(64, 64);
        let (mut px, mut py, mut pdir) = (11_i32, 10_i32, 0_u8);
        let want_moved = mir2_world::magic::char_pushed(
            &mut probe_map,
            &mut px,
            &mut py,
            &mut pdir,
            mir2_world::magic::next_direction(10, 10, 11, 10),
            u8::try_from(want_steps).unwrap(),
            target,
            mir2_world::map::CellType::Play,
        );
        assert_eq!(
            want_moved, want_steps,
            "期望表自洽：全走格下步数 = 推进格数"
        );

        let mut ground_sessions: std::collections::HashMap<String, SessionGround> =
            std::collections::HashMap::new();
        // **牙的布置修正（P2，设计件 §7-10）**：14/15 补 `CheckAmulet(1,1)` 后，夹具必须同时有
        // `ArmRingl` 槽与 catalog 模板（`index=1`、`std_mode=25`、`shape=5`、`dura=600`）；
        // 只加槽不加模板 ⇒ `amulet_slot` 返回 None ⇒ 门不过。
        ground_sessions.insert("caster".into(), a5_session_with_amulet(caster, 600));
        let catalog = a5_amulet_catalog();
        let pet_cfg = mir2_data::pet_slave::PetSlaveConfig::default();
        let table = game_svr::mongen::MonsterTable::new(Vec::new());
        handle_spell_cmd(
            game_svr::feature::make_long(11, 10),
            mir2_world::magic::SKILL_FIREWIND,
            0,
            0,
            "caster",
            911,
            &online,
            &mut world,
            &mut saves,
            &mut ground_sessions,
            &catalog,
            &magic_table,
            &pet_cfg,
            8,
            None,
            &table,
            &mut displays,
            &gates,
            1,
            1,
            2,
        );
        // ① 取数：恰好 2 抽（`Random(20)` + `Random(2)`；训练尾被 train_level=255 挡住）。
        assert_eq!(
            draws_between(&before, &world.rng),
            2,
            "8 的效果体必须恰抽 2 次（门 20 + 步数 2）"
        );
        // ② 位移：与 oracle 独立复算一致。
        let e = world.entities.get(target).unwrap();
        assert_eq!((e.x, e.y), (px, py), "落点必须等于 oracle 复算");
        assert_eq!(
            e.dir(),
            mir2_world::magic::back_dir(2),
            "CharPushed 收尾 Dir = nBackDir"
        );
        // ③ 帧序：SM_SPELL 先；逐格 SM_BACKSTEP；SM_MAGICFIRE 在共享尾最后。
        let seq = effect_seq(&effect_drain(&mut rx), 912);
        println!("FIREWIND_SEQ {seq:?}");
        assert_eq!(
            seq.iter()
                .filter(|id| **id == mir2_protocol::messages::SM_SPELL)
                .count(),
            1
        );
        assert_eq!(
            seq.iter()
                .filter(|id| **id == mir2_protocol::messages::SM_BACKSTEP)
                .count(),
            want_steps as usize,
            "每推进一格一条 SM_BACKSTEP"
        );
        let i_spell = seq
            .iter()
            .position(|id| *id == mir2_protocol::messages::SM_SPELL)
            .unwrap();
        let i_fire = seq
            .iter()
            .position(|id| *id == mir2_protocol::messages::SM_MAGICFIRE)
            .expect("共享尾必发 SM_MAGICFIRE");
        let i_push = seq
            .iter()
            .position(|id| *id == mir2_protocol::messages::SM_BACKSTEP)
            .expect("应至少一条 SM_BACKSTEP");
        assert!(
            i_spell < i_push && i_push < i_fire,
            "oracle 帧序 159 -> CharPushed -> 尾"
        );
        let _ = std::fs::remove_dir_all(dir);
    }

    /// **魔号 8 阴性对照**：`Abil.Level > target.Level` 门不过 ⇒ **零抽数、零位移、零 SM_BACKSTEP**；
    /// 断言用**随后连续三抽**（单抽在 seed=42 下多个索引同为 1，判别力不足）。
    #[test]
    fn spell_cmd_firewind_level_gate_blocks_all_draws() {
        use mir2_shared::rng::RandomNumber;
        let (
            mut world,
            caster,
            mut online,
            mut saves,
            magic_table,
            mut displays,
            gates,
            mut rx,
            dir,
        ) = effect_rig(15, mir2_world::magic::SKILL_FIREWIND, None, "fw-neg");
        let target = {
            let mut e = new_player_entity("target".to_string(), 11, 10);
            e.level = 15;
            world.add_entity(e)
        };
        world.tick();
        displays.set(
            target,
            downlink::ActorDisplay::new(4, 0, 112, 0, 0, 255, b"target".to_vec()),
        );
        online_set(
            &mut online,
            OnlineEntry {
                account: "ut".into(),
                chr_name: "target".into(),
                session_id: 2,
                gate_idx: 0,
                socket: 912,
                actor_id: target,
            },
        );
        world.entities.get_mut(caster).unwrap().visible_actors =
            vec![mir2_world::entity::VisibleBaseObject {
                target,
                flag: mir2_world::entity::VisibleFlag::Show,
            }];
        let seed = 1;
        world.rng = RandomNumber::with_seed(seed);
        let before = world.rng.clone();
        let mut ground_sessions: std::collections::HashMap<String, SessionGround> =
            std::collections::HashMap::new();
        // **牙的布置修正（P2，设计件 §7-10）**：14/15 补 `CheckAmulet(1,1)` 后，夹具必须同时有
        // `ArmRingl` 槽与 catalog 模板（`index=1`、`std_mode=25`、`shape=5`、`dura=600`）。
        ground_sessions.insert("caster".into(), a5_session_with_amulet(caster, 600));
        let catalog = a5_amulet_catalog();
        let pet_cfg = mir2_data::pet_slave::PetSlaveConfig::default();
        let table = game_svr::mongen::MonsterTable::new(Vec::new());
        handle_spell_cmd(
            game_svr::feature::make_long(11, 10),
            mir2_world::magic::SKILL_FIREWIND,
            0,
            0,
            "caster",
            911,
            &online,
            &mut world,
            &mut saves,
            &mut ground_sessions,
            &catalog,
            &magic_table,
            &pet_cfg,
            8,
            None,
            &table,
            &mut displays,
            &gates,
            1,
            1,
            2,
        );
        assert_eq!(
            draws_between(&before, &world.rng),
            0,
            "等级门不过 ⇒ 一个随机数都不抽"
        );
        let e = world.entities.get(target).unwrap();
        assert_eq!((e.x, e.y), (11, 10), "等级门不过 ⇒ 不位移");
        let seq = effect_seq(&effect_drain(&mut rx), 912);
        assert!(
            !seq.contains(&mir2_protocol::messages::SM_BACKSTEP),
            "无推挤帧；实得 {seq:?}"
        );
        // 随后连续三抽：与「未被消费的参照流」逐项相同。
        let mut control = before.clone();
        for k in 0..3 {
            assert_eq!(
                world.rng.random_below(10),
                control.random_below(10),
                "阴性对照第 {k} 抽必须等于参照流"
            );
        }
        let _ = std::fs::remove_dir_all(dir);
    }

    /// **魔号 21 正例（生产入口 `handle_spell_cmd`）**：门通过 ⇒ 取数逐项等于 oracle 期望
    /// （门下 11 + `MapRandomMove` 两抽，全走格 ⇒ `SpaceMoveGetRandXY` 首查即中、不再抽）；
    /// 落点/换图与 `MapRandomMove` 期望一致；帧 `SM_MAGICFIRE` → `SM_SPACEMOVE_HIDE2`；
    /// `SessionRegistry` 记一条 `space_move_show = Some(true)` 的换图事件（宿主出 633/634/807）。
    #[test]
    fn spell_cmd_spacemove_enters_effect_draws_and_moves_home() {
        use mir2_shared::rng::RandomNumber;
        let (mut world, caster, online, mut saves, magic_table, mut displays, gates, mut rx, dir) =
            effect_rig(50, mir2_world::magic::SKILL_SPACEMOVE, Some("home"), "sm");
        let seed = 1;
        world.rng = RandomNumber::with_seed(seed);
        let before = world.rng.clone();
        // ---- 期望表（独立复算）：`Random(11)` 门 → `Random(43)+20` 两次（高 64 ∈ [30,150) ⇒ nEgdey=20）----
        let mut exp = RandomNumber::with_seed(seed);
        let magic_level = 1;
        let want_gate = exp.random_below(11) < magic_level * 2 + 4;
        assert!(want_gate, "本 seed 必须让 21 的门通过，否则正例无判别力");
        let want_x = exp.random_below(64 - 20 - 1) + 20;
        let want_y = exp.random_below(64 - 20 - 1) + 20;

        let mut ground_sessions: std::collections::HashMap<String, SessionGround> =
            std::collections::HashMap::new();
        ground_sessions.insert("caster".into(), spell_session_ground(caster));
        let catalog = game_svr::ability::StdItemCatalog::new();
        let pet_cfg = mir2_data::pet_slave::PetSlaveConfig::default();
        let table = game_svr::mongen::MonsterTable::new(Vec::new());
        handle_spell_cmd(
            game_svr::feature::make_long(10, 10),
            mir2_world::magic::SKILL_SPACEMOVE,
            0,
            0,
            "caster",
            911,
            &online,
            &mut world,
            &mut saves,
            &mut ground_sessions,
            &catalog,
            &magic_table,
            &pet_cfg,
            8,
            Some(&registry_for(&dir)),
            &table,
            &mut displays,
            &gates,
            1,
            1,
            2,
        );
        // ① 取数：门 + 两次 `MapRandomMove`；全走格 ⇒ 移位环 0 抽。恰 3 抽。
        assert_eq!(
            draws_between(&before, &world.rng),
            3,
            "21 正例：Random(11) + MapRandomMove 两抽，移位环首查即中"
        );
        // ② 落点 = 独立复算；跨图 ⇒ map_id 1。
        let e = world.entities.get(caster).unwrap();
        assert_eq!(
            (e.x, e.y, e.map_id),
            (want_x, want_y, 1),
            "落点必须等于 oracle 复算"
        );
        // ③ 换图事件：`space_move_show = Some(true)` ⇒ SM_SPACEMOVE_SHOW2（oracle nInt == 1）。
        let changes = world.sessions.map_changes();
        assert_eq!(changes.len(), 1, "成功落地恰一条 MapChange");
        assert_eq!(changes[0].map_id, 1);
        assert_eq!((changes[0].x, changes[0].y), (want_x, want_y));
        assert_eq!(changes[0].space_move_show, Some(true));
        // ④ 帧：`RM_MAGICFIRE`（case 内、先）→ `RM_SPACEMOVE_FIRE2` ⇒ `SM_SPACEMOVE_HIDE2`。
        let seq = effect_seq(&effect_drain(&mut rx), 911);
        println!("SPACEMOVE_SEQ {seq:?}");
        let i_fire = seq
            .iter()
            .position(|id| *id == mir2_protocol::messages::SM_MAGICFIRE)
            .expect("case 内 RM_MAGICFIRE");
        let i_hide = seq
            .iter()
            .position(|id| *id == mir2_protocol::messages::SM_SPACEMOVE_HIDE2)
            .expect("门通过 ⇒ RM_SPACEMOVE_FIRE2 -> SM_SPACEMOVE_HIDE2");
        assert!(
            i_fire < i_hide,
            "oracle 序：:406 的 RM_MAGICFIRE 先于 :881 的 FIRE2"
        );
        let _ = std::fs::remove_dir_all(dir);
    }

    /// **魔号 21 `SM_SPACEMOVE_HIDE2(806)` 的收件人与发送次序牙**：oracle `MagicManager.cs:881`
    /// 的 `SendRefMsg(RM_SPACEMOVE_FIRE2, …)` 送达施法者所在格 ±12 内**全部玩家（含自己）**
    /// （`BaseObject.Message.cs:383-449`；每个接收端 `PlayObject.Message.cs:1956-1965` 各自发 806），
    /// 且发生在 `MapRandomMove` **之前** ⇒ 收件人按**旧图/旧坐标**算。
    ///
    /// 布置：观察者 `obs` 在旧图 (11,10)（socket 913，与施法者 (10,10) 相邻）；HomeMap 是 1 号图。
    /// 断言：施法者 socket 911 与观察者 socket 913 **各**收到恰好一条 806。
    /// 变异牙：改回 `send_self_frame` ⇒ 913 一条都收不到；把发送挪到换图之后 ⇒ 施法者已到
    /// 1 号图，旧图上的 913 不在 `hear_targets`（`map_id` 不同）⇒ 913 的断言同样必红。
    #[test]
    fn spell_cmd_spacemove_hide2_reaches_old_map_observers() {
        use mir2_shared::rng::RandomNumber;
        let (
            mut world,
            caster,
            mut online,
            mut saves,
            magic_table,
            mut displays,
            gates,
            mut rx,
            dir,
        ) = effect_rig(
            50,
            mir2_world::magic::SKILL_SPACEMOVE,
            Some("home"),
            "sm-obs",
        );
        // 旧图观察者：与施法者 (10,10) 相邻，±12 内且 Race==Play（`new_player_entity` 已置）。
        let obs = {
            let mut e = new_player_entity("obs".to_string(), 11, 10);
            e.race = mir2_world::ACTOR_RACE_PLAY;
            world.add_entity(e)
        };
        online_set(
            &mut online,
            OnlineEntry {
                account: "uo".into(),
                chr_name: "obs".into(),
                session_id: 3,
                gate_idx: 0,
                socket: 913,
                actor_id: obs,
            },
        );
        world.tick();
        let seed = 1;
        world.rng = RandomNumber::with_seed(seed);
        assert!(
            RandomNumber::with_seed(seed).random_below(11) < 2 + 4,
            "本 seed 必须让 21 的门通过"
        );
        let mut ground_sessions: std::collections::HashMap<String, SessionGround> =
            std::collections::HashMap::new();
        ground_sessions.insert("caster".into(), spell_session_ground(caster));
        let catalog = game_svr::ability::StdItemCatalog::new();
        let pet_cfg = mir2_data::pet_slave::PetSlaveConfig::default();
        let table = game_svr::mongen::MonsterTable::new(Vec::new());
        handle_spell_cmd(
            game_svr::feature::make_long(10, 10),
            mir2_world::magic::SKILL_SPACEMOVE,
            0,
            0,
            "caster",
            911,
            &online,
            &mut world,
            &mut saves,
            &mut ground_sessions,
            &catalog,
            &magic_table,
            &pet_cfg,
            8,
            Some(&registry_for(&dir)),
            &table,
            &mut displays,
            &gates,
            1,
            1,
            2,
        );
        // 施法者确实换到 1 号图（否则「次序」变异无法被收件人集合暴露）。
        assert_eq!(
            world.entities.get(caster).unwrap().map_id,
            1,
            "成功落地应换图"
        );
        assert_eq!(world.entities.get(obs).unwrap().map_id, 0, "观察者仍在旧图");
        let frames = effect_drain(&mut rx);
        let caster_seq = effect_seq(&frames, 911);
        let obs_seq = effect_seq(&frames, 913);
        println!("SPACEMOVE_OBS caster={caster_seq:?} obs={obs_seq:?}");
        let count = |seq: &[u16]| {
            seq.iter()
                .filter(|id| **id == mir2_protocol::messages::SM_SPACEMOVE_HIDE2)
                .count()
        };
        assert_eq!(
            count(&caster_seq),
            1,
            "施法者自己恰收一条 806；实得 {caster_seq:?}"
        );
        assert_eq!(
            count(&obs_seq),
            1,
            "旧图观察者恰收一条 806（SendRefMsg ±12 含旁观者）；实得 {obs_seq:?}"
        );
        let _ = std::fs::remove_dir_all(dir);
    }

    /// **魔号 21 阴性对照**：`Random(11)` 门不过 ⇒ **零抽数、零位移、无几换图事件、无 HIDE2**；
    /// 随后连续三抽与参照流逐项相同。
    #[test]
    fn spell_cmd_spacemove_gate_blocks_all_draws() {
        use mir2_shared::rng::RandomNumber;
        let (mut world, caster, online, mut saves, magic_table, mut displays, gates, mut rx, dir) =
            effect_rig(
                0,
                mir2_world::magic::SKILL_SPACEMOVE,
                Some("home"),
                "sm-neg",
            );
        // 把 `UserMagic.Level` 降到 0（`effect_rig` 缺省 1）⇒ 门 = `Random(11) < 4`。
        // 固定 seed=7：首抽 = 4，`4 < 4` ⇒ 假（门不过）。
        saves
            .get_mut("caster")
            .unwrap()
            .record
            .data
            .magic
            .as_mut()
            .unwrap()[0]
            .as_mut()
            .unwrap()
            .level = 0;
        let seed = 7;
        world.rng = RandomNumber::with_seed(seed);
        let before = world.rng.clone();
        assert!(
            RandomNumber::with_seed(seed).random_below(11) >= 4,
            "负数对照的 seed 必须让门失败"
        );
        let mut ground_sessions: std::collections::HashMap<String, SessionGround> =
            std::collections::HashMap::new();
        ground_sessions.insert("caster".into(), spell_session_ground(caster));
        let catalog = game_svr::ability::StdItemCatalog::new();
        let pet_cfg = mir2_data::pet_slave::PetSlaveConfig::default();
        let table = game_svr::mongen::MonsterTable::new(Vec::new());
        handle_spell_cmd(
            game_svr::feature::make_long(10, 10),
            mir2_world::magic::SKILL_SPACEMOVE,
            0,
            0,
            "caster",
            911,
            &online,
            &mut world,
            &mut saves,
            &mut ground_sessions,
            &catalog,
            &magic_table,
            &pet_cfg,
            8,
            Some(&registry_for(&dir)),
            &table,
            &mut displays,
            &gates,
            1,
            1,
            2,
        );
        // oracle `:879` 的门本身**恒抽一次** `Random(11)`；门不过时**不再**抽 `MapRandomMove`
        // 的两抽、也不进移位环 ⇒ 恰好 1 抽。
        assert_eq!(
            draws_between(&before, &world.rng),
            1,
            "门不过 ⇒ 只有 Random(11) 一抽，不抽 MapRandomMove"
        );
        let e = world.entities.get(caster).unwrap();
        assert_eq!((e.x, e.y, e.map_id), (10, 10, 0), "门不过 ⇒ 不位移");
        assert!(
            world.sessions.map_changes().is_empty(),
            "门不过 ⇒ 无换图事件"
        );
        let seq = effect_seq(&effect_drain(&mut rx), 911);
        assert!(
            !seq.contains(&mir2_protocol::messages::SM_SPACEMOVE_HIDE2),
            "门不过 ⇒ 不发 RM_SPACEMOVE_FIRE2；实得 {seq:?}"
        );
        // 随后连续三抽：参照流先复现门的那一抽，再逐项比。
        let mut control = before.clone();
        let _ = control.random_below(11);
        for k in 0..3 {
            assert_eq!(
                world.rng.random_below(10),
                control.random_below(10),
                "阴性对照第 {k} 抽必须等于参照流"
            );
        }
        let _ = std::fs::remove_dir_all(dir);
    }

