    // ======================================================================
    // 卡 P3-B2（2/29/23/24/33/47）：治疗/爆炸 AoE 效果体 + RM_MAGSTRUCK 交付链
    // ======================================================================
    //
    // 全部走**生产入口** `handle_spell_cmd`（default 支 ∧ 非战士 ∧ 距离门 ⇒ `:159 SM_SPELL`）；
    // 取数断言 = 手写 oracle 调用序的对照流逐状态相等（不调用生产 helper 生成期望）。
    // 夹具 = 合同 §3.1 F-B2（seed 42 / 20261017）。

    fn b2_magic_info(id: u16, effect: u8) -> mir2_data::MagicInfo {
        // 合同 §4.3 的真实魔表行（spell 供 MP 包装层出 53；power 组决定 4 抽的 max）。
        let (spell, power, max_power, def_spell, def_power, def_max_power) = match id {
            2 => (7u16, 14u16, 20u16, 0u8, 0u8, 0u8),
            29 => (12, 10, 10, 25, 4, 4),
            23 => (15, 8, 8, 10, 6, 6),
            24 => (35, 10, 30, 20, 10, 30),
            33 => (12, 12, 12, 30, 12, 12),
            47 => (32, 10, 30, 16, 10, 30),
            _ => unreachable!("B2 六魔号"),
        };
        mir2_data::MagicInfo {
            magic_id: id,
            effect,
            effect_type: 2,
            spell,
            power,
            max_power,
            def_spell,
            def_power,
            def_max_power,
            train_lv: 3,
            train_level: [0; 4],
            max_train: [1000; 4],
            ..mir2_data::MagicInfo::default()
        }
    }

    fn b2_rig(id: u16, effect: u8, observers: &[(&str, i32, i32, bool, i32)]) -> SpellFrameRig {
        let mut rig = SpellFrameRig::new(id, &[(id, effect)], observers);
        rig.magic_table = magics::MagicTable::new(vec![b2_magic_info(id, effect)]);
        {
            let e = rig.world.entities.get_mut(rig.caster).unwrap();
            e.level = 50;
            e.luck = 0;
            e.power_rate = 100;
            e.hp = 500;
            e.max_hp = 500;
        }
        {
            let sg = rig.ground_sessions.get_mut("caster").unwrap();
            sg.state.wabil.level = 50;
            sg.state.wabil.mc = 0x0F05;
            sg.state.wabil.sc = 0x0C04;
            sg.state.wabil.mp = 500;
            sg.state.wabil.max_mp = 500;
            sg.state.wabil.hp = 500;
            sg.state.wabil.max_hp = 500;
        }
        // F-B2：`userMagic.Level = 3` ⇒ 训练门关（无第 5 抽、无 640）。
        rig.saves
            .get_mut("caster")
            .unwrap()
            .record
            .data
            .magic
            .as_mut()
            .unwrap()[0]
            .as_mut()
            .unwrap()
            .level = 3;
        rig
    }

    fn b2_add_player(
        rig: &mut SpellFrameRig,
        name: &str,
        x: i32,
        y: i32,
        hp: u16,
        max_hp: u16,
        socket: i32,
    ) -> i32 {
        let mut e = new_player_entity(name.to_string(), x, y);
        e.level = 30;
        e.hp = hp;
        e.max_hp = max_hp;
        e.mp = 500;
        e.max_mp = 500;
        e.anti_magic = 255;
        let id = rig.world.add_entity(e);
        rig.world.tick();
        rig.displays.set(
            id,
            downlink::ActorDisplay::new(4, 0, 200, 0, 0, 255, name.as_bytes().to_vec()),
        );
        online_set(
            &mut rig.online,
            OnlineEntry {
                account: name.into(),
                chr_name: name.into(),
                session_id: socket,
                gate_idx: 0,
                socket,
                actor_id: id,
            },
        );
        id
    }

    fn b2_add_monster(rig: &mut SpellFrameRig, name: &str, x: i32, y: i32, mac: u16) -> i32 {
        let mut e = mir2_world::Entity::new(0, name.to_string(), x, y);
        e.race = mir2_world::ACTOR_RACE_ANIMAL;
        e.level = 30;
        e.hp = 1000;
        e.max_hp = 1000;
        e.mac = mac;
        e.anti_magic = 255;
        e.ai.animal = true;
        e.ai.target_creature = None;
        let id = rig.world.add_entity(e);
        rig.world.tick();
        rig.displays.set(
            id,
            downlink::ActorDisplay::new(4, 0, 220, 0, 0, 255, name.as_bytes().to_vec()),
        );
        id
    }

    /// 取某连接上的 `(ident, recog)` 序列。
    fn b2_seq(frames: &[SfFrame], socket: i32) -> Vec<(u16, i32)> {
        frames
            .iter()
            .filter(|(s, _)| *s == socket)
            .map(|(_, b)| {
                let cm = mir2_protocol::frame::CommandMessage::from_bytes(b).unwrap();
                (cm.ident, cm.recog)
            })
            .collect()
    }

    fn b2_delay_targets(rig: &SpellFrameRig) -> Vec<(i32, i32)> {
        rig.world
            .self_delay_msgs
            .iter()
            .filter(|m| m.ident == mir2_world::slave::RM_MAGHEALING)
            .map(|m| (m.actor_id, m.n_param1))
            .collect()
    }

    /// **B2-2（治愈术）**：施法者侧恰 4 抽（`R(6)/R(0)/R(18)/R(10)`，seed42 ⇒ nPower=28）；
    /// `IsProperFriend` 门在抽数**之前**；`RM_MAGHEALING` 延迟 800 且只给 `HP<MaxHP` 的目标；
    /// `RM_ABILSEEHEALGAUGE` 的 1103 **发给施法者**且排在 638 之后（优先级 174 > 136）。
    ///
    /// 红检：① 把 Ap 移到 friend 门之前 ⇒ 非友方场景多 4 抽；② 满血时提前 return ⇒ 抽数 0；
    /// ③ 1103 直发目标/排到 638 前 ⇒ 收件人/帧序断言红；④ 死亡目标不回落 ⇒ 尾坐标/id 红。
    #[test]
    fn spell_p3b2_healing_draws_gate_and_gauge_order() {
        const SM_53: u16 = mir2_protocol::messages::SM_HEALTHSPELLCHANGED;
        const SM_638: u16 = mir2_protocol::messages::SM_MAGICFIRE;
        const SM_1103: u16 = mir2_protocol::messages::SM_INSTANCEHEALGUAGE;
        // ① 正常友方（HP<MaxHP）⇒ 4 抽 + 延迟治疗 + 尾。
        {
            let mut rig = b2_rig(2, 2, &[("obs", 12, 11, false, 912)]);
            let target = b2_add_player(&mut rig, "t", 12, 12, 50, 1000, 921);
            rig.world.rng = mir2_shared::rng::RandomNumber::with_seed(42);
            let before = rig.world.rng.clone();
            rig.cast(2, (12, 12), target);
            let (frames, _raws) = rig.drain();
            assert_eq!(
                draws_between(&before, &rig.world.rng),
                4,
                "2 施法者侧恰 4 抽"
            );
            let mut c = mir2_shared::rng::RandomNumber::with_seed(42);
            let _ = c.random_below(6);
            let _ = c.random_below(0);
            let _ = c.random_below(18);
            let _ = c.random_below(10);
            assert_eq!(
                format!("{:?}", rig.world.rng),
                format!("{c:?}"),
                "2 取数序 = MPow(R6) → GetPower(R0) → AP(R18,R10)"
            );
            let fire = sf_first(&frames, 912, SM_638);
            assert_eq!(sf_magicfire_target_id(fire), target, "尾目标 = 治疗对象");
            let cmd = mir2_protocol::frame::CommandMessage::from_bytes(fire).unwrap();
            assert_eq!((cmd.param, cmd.tag), (12, 12), "尾坐标 = snap 后点击格");
            // 施法者：MP 包装层 53 先于 638；无 1103（gauge 关）。
            let self_seq: Vec<u16> = sf_seq(&frames, 911);
            assert_eq!(self_seq, vec![SM_53, SM_638], "caster 帧序 53 → 638");
            assert_eq!(
                b2_delay_targets(&rig),
                vec![(target, 28)],
                "RM_MAGHEALING(target, nPower=28)，seed42"
            );
            // 恢复期：nPower=28 ⇒ ceil(28/5)=6 条 53（合同 §2.1(b)）。
            rig.world.clock_ms += 800;
            let delivered = rig.world.deliver_self_delay_msgs();
            let n = delivered[0].mag_healing.expect("RM_MAGHEALING");
            assert_eq!(n, 28);
            let sg = rig.ground_sessions.get_mut("caster").unwrap();
            // 治疗的收件人是目标（这里用会话模拟目标恢复：t 不是 caster，单独建状态）。
            let mut rec = game_svr::recover::Recovery::new(0);
            let mut wabil = game_svr::ability::Ability {
                level: 30,
                hp: 50,
                max_hp: 1000,
                mp: 500,
                max_mp: 500,
                ..sg.state.wabil
            };
            if i32::from(rec.inc_healing) + n < 300 {
                rec.inc_healing += u16::try_from(n).unwrap();
                rec.per_healing = 5;
            } else {
                rec.inc_healing = 300;
            }
            let mut health_frames = 0;
            for _ in 0..40 {
                rig.world.clock_ms += 200;
                if game_svr::recover::recovery_tick(&mut rec, &mut wabil, false, rig.world.clock_ms)
                {
                    health_frames += 1;
                }
                if rec.inc_healing == 0 {
                    break;
                }
            }
            assert_eq!(health_frames, 6, "ceil(28/5)=6 条恢复 53");
            assert_eq!(wabil.hp, 78, "50 + 28");
        }
        // ② gauge=true ⇒ 施法者帧序 53 → 638 → 1103，且 1103 的 Recog=目标。
        {
            let mut rig = b2_rig(2, 2, &[]);
            let target = b2_add_player(&mut rig, "t", 12, 12, 50, 1000, 921);
            rig.ground_sessions
                .get_mut("caster")
                .unwrap()
                .abil_see_heal_gauge = true;
            rig.cast(2, (12, 12), target);
            let (frames, _raws) = rig.drain();
            let seq: Vec<u16> = sf_seq(&frames, 911);
            assert_eq!(seq, vec![SM_53, SM_638, SM_1103], "1103 在 638 之后");
            let gauge = sf_first(&frames, 911, SM_1103);
            assert_eq!(
                mir2_protocol::frame::CommandMessage::from_bytes(gauge)
                    .unwrap()
                    .recog,
                target,
                "1103 的 ActorId = 目标（收件人仍是施法者）"
            );
            assert_eq!(
                sf_count(&frames, 921, SM_1103),
                0,
                "**不得**把 1103 发给目标（合同 §5-C1）"
            );
        }
        // ③ 满血友方 ⇒ 仍 4 抽、无 RM_MAGHEALING。
        {
            let mut rig = b2_rig(2, 2, &[]);
            let target = b2_add_player(&mut rig, "t", 12, 12, 1000, 1000, 921);
            rig.world.rng = mir2_shared::rng::RandomNumber::with_seed(42);
            let before = rig.world.rng.clone();
            rig.cast(2, (12, 12), target);
            assert_eq!(draws_between(&before, &rig.world.rng), 4, "满血仍 4 抽");
            assert!(b2_delay_targets(&rig).is_empty());
        }
        // ④ 死亡目标 ⇒ 回落为自己并改写尾坐标/id。
        {
            let mut rig = b2_rig(2, 2, &[]);
            let target = b2_add_player(&mut rig, "t", 12, 12, 50, 1000, 921);
            rig.world.entities.get_mut(target).unwrap().death = true;
            rig.world.entities.get_mut(rig.caster).unwrap().hp = 100;
            rig.cast(2, (12, 12), target);
            let (frames, _raws) = rig.drain();
            let fire = sf_first(&frames, 911, SM_638);
            assert_eq!(
                sf_magicfire_target_id(fire),
                rig.caster,
                "死亡目标 ⇒ 尾 id = 施法者（合同 §5-C7）"
            );
            let cmd = mir2_protocol::frame::CommandMessage::from_bytes(fire).unwrap();
            assert_eq!((cmd.param, cmd.tag), (10, 10), "死亡目标 ⇒ 尾坐标 = 施法者");
            assert_eq!(
                b2_delay_targets(&rig),
                vec![(rig.caster, 28)],
                "治疗对象 = 施法者"
            );
        }
    }

    /// **B2-29（群体治疗术）**：恒 4 抽；3×3 有序枚举；只治 `HP<MaxHP` 的 proper friend；
    /// 同格双友方按 `ObjList` 插入序；gauge 不看 HP 且 1103 只发施法者。
    ///
    /// 红检：① 中心用施法者坐标 ⇒ 收件人集合红；② 用槽位序 ⇒ P6/P7 顺序红；
    /// ③ 漏 `HP<MaxHP` ⇒ 满血友方也收 RM_MAGHEALING；④ boTrain 恒 true ⇒ 空集场景多 640。
    #[test]
    fn spell_p3b2_big_healing_ordered_enumeration_and_gauge() {
        let build = |gauge: bool| {
            let mut rig = b2_rig(29, 27, &[]);
            let p1 = b2_add_player(&mut rig, "p1", 12, 12, 50, 1000, 921);
            let _p2 = b2_add_player(&mut rig, "p2", 11, 12, 1000, 1000, 922);
            let p6 = b2_add_player(&mut rig, "p6", 12, 11, 10, 1000, 923);
            let p7 = b2_add_player(&mut rig, "p7", 12, 11, 10, 1000, 924);
            let _m1 = b2_add_monster(&mut rig, "m1", 13, 12, 0);
            let p4 = b2_add_player(&mut rig, "p4", 11, 11, 10, 1000, 925);
            rig.world.entities.get_mut(p4).unwrap().death = true;
            let p5 = b2_add_player(&mut rig, "p5", 13, 13, 10, 1000, 926);
            rig.world.entities.get_mut(p5).unwrap().ghost = true;
            let _p3 = b2_add_player(&mut rig, "p3", 14, 12, 10, 1000, 927);
            if gauge {
                rig.ground_sessions
                    .get_mut("caster")
                    .unwrap()
                    .abil_see_heal_gauge = true;
            }
            rig.world.rng = mir2_shared::rng::RandomNumber::with_seed(42);
            (rig, p1, p6, p7)
        };
        {
            let (mut rig, p1, p6, p7) = build(false);
            let before = rig.world.rng.clone();
            rig.cast(29, (12, 12), p1);
            assert_eq!(draws_between(&before, &rig.world.rng), 4, "29 恒 4 抽");
            assert_eq!(
                b2_delay_targets(&rig),
                vec![(p6, 24), (p7, 24), (p1, 24)],
                "枚举序 = x→y→格内插入序；P2 满血不发；M1 非友方"
            );
        }
        {
            let (mut rig, p1, _p6, _p7) = build(true);
            rig.cast(29, (12, 12), p1);
            let (frames, _raws) = rig.drain();
            let gauges: Vec<(u16, i32)> = b2_seq(&frames, 911)
                .into_iter()
                .filter(|(id, _)| *id == mir2_protocol::messages::SM_INSTANCEHEALGUAGE)
                .collect();
            assert_eq!(gauges.len(), 4, "gauge 目标 = P2,P6,P7,P1（不看 HP）");
            for socket in [921, 922, 923, 924] {
                assert_eq!(
                    sf_count(
                        &frames,
                        socket,
                        mir2_protocol::messages::SM_INSTANCEHEALGUAGE
                    ),
                    0,
                    "1103 不得发给目标"
                );
            }
        }
    }

    /// **B2-23（爆裂火焰）**：4 抽 + 交付段逐目标账本（怪物 `R(1000)`+`MSD`+`R(300)`；
    /// 玩家 `MSD`+`STD R(10)`）；帧序 `638 → 656×3 → 31×4`，受击玩家 `53` 在 `638` 前。
    ///
    /// 红检：① 漏 `R(1000)`/`R(300)` ⇒ 对照流状态不等；② 用 `IsProperFriend` 冒充
    /// `IsProperTarget` ⇒ 怪物全漏；③ 无目标仍 `boTrain=true` ⇒ 训练抽多；④ `nDamage==0`
    /// 仍抽 `R(300)`/发 31/656 ⇒ 零伤害变体红。
    #[test]
    fn spell_p3b2_fireboom_delivery_ledger_and_frames() {
        const SM_53: u16 = mir2_protocol::messages::SM_HEALTHSPELLCHANGED;
        const SM_638: u16 = mir2_protocol::messages::SM_MAGICFIRE;
        const SM_656: u16 = mir2_protocol::messages::SM_CHANGENAMECOLOR;
        const SM_31: u16 = mir2_protocol::messages::SM_STRUCK;
        let build = |m3_mac: u16| {
            let mut rig = b2_rig(23, 21, &[("obs", 10, 13, false, 912)]);
            let m1 = b2_add_monster(&mut rig, "m1", 11, 11, 0x0A00);
            let m2 = b2_add_monster(&mut rig, "m2", 12, 12, 0x0500);
            let p1 = b2_add_player(&mut rig, "p1", 13, 11, 50, 1000, 921);
            rig.world.entities.get_mut(p1).unwrap().mac = 0x0C00;
            let m3 = b2_add_monster(&mut rig, "m3", 13, 13, m3_mac);
            let m4 = b2_add_monster(&mut rig, "m4", 12, 11, 0);
            rig.world.entities.get_mut(m4).unwrap().death = true;
            let m5 = b2_add_monster(&mut rig, "m5", 11, 13, 0);
            rig.world.entities.get_mut(m5).unwrap().ghost = true;
            let _m6 = b2_add_monster(&mut rig, "m6", 14, 12, 0);
            let p2 = b2_add_player(&mut rig, "p2", 12, 13, 50, 1000, 922);
            rig.world.entities.get_mut(p2).unwrap().in_safe_zone = true;
            rig.world.rng = mir2_shared::rng::RandomNumber::with_seed(42);
            (rig, m1, m2, p1, m3)
        };
        // ① 正常：nPower=20；M1/M2/P1/M3 按枚举序完整处理。
        {
            let (mut rig, m1, m2, p1, m3) = build(0x0000);
            let before = rig.world.rng.clone();
            rig.cast(23, (12, 12), m2);
            let (frames, _raws) = rig.drain();
            // 4 施法者抽 + M1(1000,MSD,300) + M2 + P1(MSD,STD) + M3。
            assert_eq!(
                draws_between(&before, &rig.world.rng),
                15,
                "23 = 4 + 3*3（怪）+ 2（玩家）"
            );
            let mut c = mir2_shared::rng::RandomNumber::with_seed(42);
            let _ = c.random_below(0);
            let _ = c.random_below(0);
            let _ = c.random_below(12);
            let _ = c.random_below(10);
            // 精确重放（M1 R11、M2 R6、M3 R1）。
            let mut c = mir2_shared::rng::RandomNumber::with_seed(42);
            let _ = c.random_below(0);
            let _ = c.random_below(0);
            let _ = c.random_below(12);
            let _ = c.random_below(10);
            let _ = c.random_below(1000);
            let _ = c.random_below(11);
            let _ = c.random_below(300);
            let _ = c.random_below(1000);
            let _ = c.random_below(6);
            let _ = c.random_below(300);
            let _ = c.random_below(13);
            let _ = c.random_below(10);
            let _ = c.random_below(1000);
            let _ = c.random_below(1);
            let _ = c.random_below(300);
            assert_eq!(
                format!("{:?}", rig.world.rng),
                format!("{c:?}"),
                "交付段逐目标抽数序（合同 §3.3 账本）"
            );
            // HP：M1 18 / M2 19 / P1 17 / M3 20。
            assert_eq!(rig.world.entities.get(m1).unwrap().hp, 982);
            assert_eq!(rig.world.entities.get(m2).unwrap().hp, 981);
            assert_eq!(rig.world.entities.get(p1).unwrap().hp, 33);
            assert_eq!(rig.world.entities.get(m3).unwrap().hp, 980);
            // 帧序（不同优先级）：施法者/观察者 638 → 656×3 → 31×4；P1 53 在 638 前。
            for socket in [911, 912] {
                let seq: Vec<u16> = sf_seq(&frames, socket);
                let i638 = seq.iter().position(|x| *x == SM_638).unwrap();
                let i656: Vec<usize> = seq
                    .iter()
                    .enumerate()
                    .filter(|(_, x)| **x == SM_656)
                    .map(|(i, _)| i)
                    .collect();
                let i31: Vec<usize> = seq
                    .iter()
                    .enumerate()
                    .filter(|(_, x)| **x == SM_31)
                    .map(|(i, _)| i)
                    .collect();
                assert_eq!(i656.len(), 3, "M1/M2/M3 各一条 656；实得 {seq:?}");
                assert_eq!(i31.len(), 4, "31 给 4 个受击者；实得 {seq:?}");
                assert!(i656.iter().all(|i| *i > i638) && i31.iter().all(|i| *i > i638));
                assert!(i656.iter().max().unwrap() < i31.iter().min().unwrap());
            }
            let p1_seq = sf_seq(&frames, 921);
            let i53 = p1_seq.iter().position(|x| *x == SM_53).unwrap();
            let i638 = p1_seq.iter().position(|x| *x == SM_638).unwrap();
            assert!(i53 < i638, "受击玩家 53 先于 638；实得 {p1_seq:?}");
            // 31 的 Recog = 受击者，顺序 = 枚举序 M1/M2/P1/M3（同优先级按入队序）。
            let struck: Vec<i32> = b2_seq(&frames, 912)
                .into_iter()
                .filter(|(id, _)| *id == SM_31)
                .map(|(_, r)| r)
                .collect();
            assert_eq!(struck, vec![m1, m2, p1, m3]);
        }
        // ② nDamage==0 变体：M3 MAC=0x0014 ⇒ 只有 R(1000)+MSD，无 31/656、无 R(300)。
        {
            let (mut rig, _m1, m2, _p1, _m3) = build(0x0014);
            let before = rig.world.rng.clone();
            rig.cast(23, (12, 12), m2);
            let (frames, _raws) = rig.drain();
            assert_eq!(
                draws_between(&before, &rig.world.rng),
                14,
                "零伤害怪物不抽 R(300)（4+3+3+2+2）"
            );
            let seq: Vec<u16> = sf_seq(&frames, 912);
            assert_eq!(
                seq.iter().filter(|x| **x == SM_656).count(),
                2,
                "零伤害怪物不产生 656；实得 {seq:?}"
            );
            assert_eq!(
                seq.iter().filter(|x| **x == SM_31).count(),
                3,
                "零伤害怪物不产生 31；实得 {seq:?}"
            );
        }
    }

    /// **B2-24（地狱雷光）**：AoE 中心 = **施法者坐标**（点击 (12,12) 只影响尾帧），
    /// 非不死 `nPower/10`（整除）、不死原值；self 靠 `IsProperTarget` 排除。
    ///
    /// 红检：① 中心用点击坐标 ⇒ 受击集合/顺序红；② 漏 `/10` ⇒ M2/P1 扣血 41 而非 4；
    /// ③ self 被命中 ⇒ 施法者掉血。
    #[test]
    fn spell_p3b2_lightflower_center_self_and_undead_division() {
        const SM_638: u16 = mir2_protocol::messages::SM_MAGICFIRE;
        let mut rig = b2_rig(24, 22, &[]);
        let m2 = b2_add_monster(&mut rig, "m2", 8, 8, 0);
        let m1 = b2_add_monster(&mut rig, "m1", 11, 11, 0);
        let m3 = b2_add_monster(&mut rig, "m3", 12, 8, 0);
        let p1 = b2_add_player(&mut rig, "p1", 12, 12, 50, 1000, 921);
        let _p2 = b2_add_player(&mut rig, "p2", 13, 10, 50, 1000, 922);
        rig.world.entities.get_mut(m1).unwrap().life_attrib = 1;
        rig.world.entities.get_mut(m3).unwrap().life_attrib = 1;
        rig.world.rng = mir2_shared::rng::RandomNumber::with_seed(42);
        let before = rig.world.rng.clone();
        rig.cast(24, (12, 12), p1);
        let (frames, _raws) = rig.drain();
        assert_eq!(draws_between(&before, &rig.world.rng), 15);
        // nPower=41：非不死（M2/P1）受 4，不死（M1/M3）受 41。
        assert_eq!(rig.world.entities.get(m2).unwrap().hp, 996);
        assert_eq!(rig.world.entities.get(p1).unwrap().hp, 46);
        assert_eq!(rig.world.entities.get(m1).unwrap().hp, 959);
        assert_eq!(rig.world.entities.get(m3).unwrap().hp, 959);
        assert_eq!(
            rig.world.entities.get(rig.caster).unwrap().hp,
            500,
            "self 不得掉血"
        );
        // 尾帧坐标仍是点击 (12,12)，不是 AoE 中心 (10,10)。
        let cmd = mir2_protocol::frame::CommandMessage::from_bytes(sf_first(&frames, 911, SM_638))
            .unwrap();
        assert_eq!((cmd.param, cmd.tag), (12, 12), "共享尾用点击坐标");
        // 31 的顺序 = 以施法者 (10,10) 为中心的 x→y：M2(8,8) → M1(11,11) → M3(12,8) → P1(12,12)。
        let struck: Vec<i32> = b2_seq(&frames, 911)
            .into_iter()
            .filter(|(id, _)| *id == mir2_protocol::messages::SM_STRUCK)
            .map(|(_, r)| r)
            .collect();
        assert_eq!(struck, vec![m2, m1, m3, p1]);
    }

    /// **B2-33/47 半径来源**：33 读 `SnowWindRange`、47 读 `FireBoomRage`（二者缺省都是 1，
    /// 夹具故意一 2 一 1）；47 的死亡点击目标在共享尾做死亡归一（尾 id=0）。
    ///
    /// 红检：交换配置键 ⇒ (14,14) 命中集合红；47 尾 id 不归一 ⇒ 红。
    #[test]
    fn spell_p3b2_snowwind_fireboom_radius_source_and_death_norm() {
        let run = |id: u16, effect: u8, fire: i32, snow: i32, dead_click: bool| {
            let mut rig = b2_rig(id, effect, &[]);
            let m2 = b2_add_monster(&mut rig, "m2", 12, 12, 0);
            let probe = b2_add_monster(&mut rig, "probe", 14, 14, 0);
            if dead_click {
                rig.world.entities.get_mut(m2).unwrap().death = true;
            }
            rig.fire_boom_rage = fire;
            rig.snow_wind_range = snow;
            rig.cast(id, (12, 12), m2);
            let (frames, _raws) = rig.drain();
            let hp = rig.world.entities.get(probe).unwrap().hp;
            let tail = sf_magicfire_target_id(sf_first(
                &frames,
                911,
                mir2_protocol::messages::SM_MAGICFIRE,
            ));
            (hp, tail)
        };
        // 33：SnowWindRange=2 ⇒ (14,14) 在窗口内；FireBoomRage 被故意设 1（读错则漏）。
        assert!(run(33, 31, 1, 2, false).0 < 1000, "33 必须读 SnowWindRange");
        assert_eq!(run(33, 31, 2, 1, false).0, 1000, "33 半径 1 ⇒ (14,14) 圈外");
        // 47：FireBoomRage=2 ⇒ (14,14) 命中；SnowWindRange=1（读错则漏）。
        assert!(run(47, 65, 2, 1, false).0 < 1000, "47 必须读 FireBoomRage");
        assert_eq!(run(47, 65, 1, 2, false).0, 1000, "47 半径 1 ⇒ (14,14) 圈外");
        // 死亡点击 ⇒ 共享尾目标 id 归零（合同 §2.6(f)）。
        assert_eq!(run(47, 65, 2, 1, true).1, 0, "死亡点击 ⇒ 尾目标 id=0");
    }
    /// **B2 逐魔号抽数表（两个种子）**：施法者侧 4 抽的 max 序列按合同 §3.4；
    /// 单目标交付段（怪物 `R(1000)`+`MSD`+`R(300)`）逐项对拍。
    ///
    /// 红检：任何取数式/max 写错（如 AP 用 `R(17)`/`R(11)`、MPow 参数取反）⇒ 对照流状态不等。
    #[test]
    fn spell_p3b2_all_six_draw_sequences_match_contract_tables() {
        for seed in [42i32, 2026_1017] {
            // 2 / 29：治疗族（player friend；无交付抽）。
            for (id, effect, mpow_max, gp_max, ap_max, want_power) in [
                (
                    2u16,
                    2u8,
                    6i32,
                    0i32,
                    18i32,
                    if seed == 42 { 28 } else { 32 },
                ),
                (29, 27, 0, 0, 18, if seed == 42 { 24 } else { 27 }),
            ] {
                let mut rig = b2_rig(id, effect, &[]);
                let t = b2_add_player(&mut rig, "t", 12, 12, 50, 1000, 921);
                rig.world.rng = mir2_shared::rng::RandomNumber::with_seed(seed);
                let mut c = mir2_shared::rng::RandomNumber::with_seed(seed);
                let _ = c.random_below(mpow_max);
                let _ = c.random_below(gp_max);
                let _ = c.random_below(ap_max);
                let _ = c.random_below(10);
                rig.cast(id, (12, 12), t);
                assert_eq!(
                    format!("{:?}", rig.world.rng),
                    format!("{c:?}"),
                    "[{id}] seed={seed} 治疗族 4 抽"
                );
                assert_eq!(
                    b2_delay_targets(&rig),
                    vec![(t, want_power)],
                    "[{id}] seed={seed} nPower"
                );
            }
            // 23 / 33 / 47：AoE（单怪物目标 ⇒ +R(1000)+MSD(R1)+R(300)）。
            for (id, effect, mpow_max, gp_max, ap_max, undead, want_power) in [
                (
                    23u16,
                    21u8,
                    0i32,
                    0i32,
                    12i32,
                    false,
                    if seed == 42 { 20 } else { 22 },
                ),
                (24, 22, 20, 20, 12, true, if seed == 42 { 41 } else { 53 }),
                (33, 31, 0, 0, 12, false, if seed == 42 { 30 } else { 32 }),
                (47, 65, 20, 20, 12, false, if seed == 42 { 41 } else { 53 }),
            ] {
                let mut rig = b2_rig(id, effect, &[]);
                let t = b2_add_monster(&mut rig, "m", 12, 12, 0);
                if undead {
                    rig.world.entities.get_mut(t).unwrap().life_attrib = 1;
                }
                rig.world.rng = mir2_shared::rng::RandomNumber::with_seed(seed);
                let mut c = mir2_shared::rng::RandomNumber::with_seed(seed);
                let _ = c.random_below(mpow_max);
                let _ = c.random_below(gp_max);
                let _ = c.random_below(ap_max);
                let _ = c.random_below(10);
                let _ = c.random_below(1000);
                let _ = c.random_below(1); // MAC=0 ⇒ R(|0-0|+1)
                let _ = c.random_below(300);
                rig.cast(id, (12, 12), t);
                assert_eq!(
                    format!("{:?}", rig.world.rng),
                    format!("{c:?}"),
                    "[{id}] seed={seed} 施法者 4 抽 + 单怪交付 3 抽"
                );
                assert_eq!(
                    rig.world.entities.get(t).unwrap().hp,
                    1000 - want_power,
                    "[{id}] seed={seed} 伤害 = nPower（MAC=0）"
                );
            }
        }
    }
    // ======================================================================
    // 卡 P3-B3（16/18/19/28/32/40）：状态 / 辅助 / 不死六魔号
    // ======================================================================
    //
    // 全部走**生产入口** `handle_spell_cmd`（default 支 ∧ 非战士 ∧ 距离门 ⇒ `:159 SM_SPELL`），
    // 固定种子 20261017。取数断言 = 按合同 §4.1 的 max 序回放并**逐抽比较 `(max,result)`**；
    // 回放末态必须与生产 `world.rng` 状态逐字节相同（多抽/少抽/换序都红）。
    //
    // 牙（每个魔号 ≥2，共 ≥12；对应合同 §3 的「改坏必红」）：
    // - 16：B3-16-1（不合格对象不归零 result）、B3-16-2（`R(4)` 在校验 `Master` 之后才抽）、
    //        B3-16-3（漏 `CanWalk`）、B3-16-4（只给最后一个对象发 `RM_MAKEHOLYSEIZEMODE`）；
    // - 18：B3-18-1（漏 `R(2)`）、B3-18-2（坐标短路先抽）、B3-18-3（helper 早退时不抽 GP13/RP）、
    //        B3-18-4（657 一条 body 广播 hit_speed=0）；
    // - 19：B3-19-1（helper 内多抽）、B3-19-2（漏 `IsProperFriend`）、B3-19-3（延迟改成 0）、
    //        B3-19-4（投递时不抽 `R(2)`）；
    // - 28：B3-28-1（RP/GP13 顺序反）、B3-28-2（ShowHp 时仍抽）、B3-28-3（漏 *1000）、
    //        B3-28-4（延迟改成 0）；
    // - 32：B3-32-1（非 undead 也抽）、B3-32-2（无视 TargetCret 短路抽 R(6)）、
    //        B3-32-3（MeatQuality 钳 0 而非 ushort 回绕）、B3-32-4（Animal=false 仍抽 R(300)）；
    // - 40：B3-40-1（把 !=0 的赋值写成 =0）、B3-40-2（漏 IsProperFriend）、
    //        B3-40-3（忽略 Level）、B3-40-4（计时器全 0 仍 boTrain）。
    //
    // 下列用例对每个牙都给出**固定种子下的判别值/帧**；任何一条被改坏都会使对应断言红。

    const B3_SEED: i32 = 20261017;

    fn b3_magic_info(id: u16) -> mir2_data::MagicInfo {
        // 合同 §1.2 的部署行（`sql/mir2_data.sql:85/87/88/97/101/108`）。
        // 注意 32 的 `DefSpell = 40`（合同 §3.4 写 38 是把该列漏掉；oracle 以 SQL 行为准，见报告）。
        let (effect, effect_type, spell, def_spell, train_level) = match id {
            16 => (14u8, 10u8, 10u16, 5u8, [28u8, 30, 32, 32]),
            18 => (16, 4, 5, 0, [20, 23, 26, 26]),
            19 => (17, 8, 10, 0, [21, 25, 29, 29]),
            28 => (26, 2, 16, 0, [26, 30, 35, 35]),
            32 => (30, 2, 50, 40, [32, 35, 39, 39]),
            40 => (0, 0, 20, 3, [48, 50, 52, 52]),
            _ => unreachable!("B3 六魔号"),
        };
        mir2_data::MagicInfo {
            magic_id: id,
            effect,
            effect_type,
            spell,
            def_spell,
            power: 0,
            max_power: 0,
            def_power: 0,
            def_max_power: 0,
            train_lv: 3,
            train_level,
            max_train: [200, 300, 500, 500],
            ..mir2_data::MagicInfo::default()
        }
    }

    struct B3Rig {
        world: mir2_world::World,
        caster: i32,
        observer: i32,
        far: i32,
        online: OnlineRegistry,
        saves: std::collections::HashMap<String, SavedHuman>,
        ground_sessions: std::collections::HashMap<String, SessionGround>,
        magic_table: magics::MagicTable,
        displays: downlink::DisplayTable,
        gates: std::collections::HashMap<u8, mpsc::UnboundedSender<SimToGate>>,
        rx: mpsc::UnboundedReceiver<SimToGate>,
    }

    impl B3Rig {
        fn new(magic_id: u16, magic_level: u8, with_amulet: bool) -> Self {
            use std::collections::HashMap;
            let mut world = mir2_world::World::new(64, 64);
            let caster = world.add_entity(new_player_entity("caster".to_string(), 10, 10));
            let observer = world.add_entity(new_player_entity("obs".to_string(), 11, 10));
            let far = world.add_entity(new_player_entity("far".to_string(), 40, 40));
            {
                let e = world.entities.get_mut(caster).unwrap();
                e.level = 60;
                e.attack_mode = 0; // HAM_ALL
                e.hp = 100;
                e.max_hp = 100;
            }
            world.tick();
            let mut displays = downlink::DisplayTable::new();
            displays.set(
                caster,
                downlink::ActorDisplay::new(4, 0, 111, 0, 0, 255, b"caster".to_vec()),
            );
            displays.set(
                observer,
                downlink::ActorDisplay::new(4, 0, 112, 0, 0, 255, b"obs".to_vec()),
            );
            displays.set(
                far,
                downlink::ActorDisplay::new(4, 0, 113, 0, 0, 255, b"far".to_vec()),
            );
            let mut online: OnlineRegistry = Vec::new();
            for (i, (name, socket, actor)) in [
                ("caster", 911, caster),
                ("obs", 912, observer),
                ("far", 914, far),
            ]
            .into_iter()
            .enumerate()
            {
                online_set(
                    &mut online,
                    OnlineEntry {
                        account: format!("u{i}"),
                        chr_name: name.into(),
                        session_id: 10 + i32::try_from(i).unwrap_or(0),
                        gate_idx: 0,
                        socket,
                        actor_id: actor,
                    },
                );
            }
            let (tx0, rx) = mpsc::unbounded_channel::<SimToGate>();
            let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
            gates.insert(0, tx0);
            let mut record = stage6_record();
            record.data.magic = Some(vec![Some(record::MagicRcd {
                mag_idx: magic_id,
                level: magic_level,
                magic_key: u16::from(b'm'),
                tran_point: 0,
            })]);
            let mut saves: HashMap<String, SavedHuman> = HashMap::new();
            saves.insert(
                "caster".into(),
                SavedHuman {
                    account: "u0".into(),
                    record,
                    enter_map: "0".into(),
                },
            );
            let mut ground_sessions: HashMap<String, SessionGround> = HashMap::new();
            let mut sg = spell_session_ground(caster);
            sg.state.wabil.level = 60;
            sg.state.wabil.hp = 100;
            sg.state.wabil.max_hp = 100;
            sg.state.wabil.mp = 1000;
            sg.state.wabil.max_mp = 1000;
            sg.state.wabil.sc = 0x0A05;
            sg.state.wabil.mc = 0;
            if with_amulet {
                sg.use_items[game_svr::ability::SLOT_ARMRING_L] = Some(game_svr::bag::BagItem {
                    make_index: 1,
                    index: 1,
                    dura: 600,
                    dura_max: 1000,
                    desc: [0; 14],
                });
            }
            ground_sessions.insert("caster".into(), sg);
            let magic_table = magics::MagicTable::new(vec![b3_magic_info(magic_id)]);
            let mut world = world;
            world.rng = mir2_shared::rng::RandomNumber::with_seed(B3_SEED);
            Self {
                world,
                caster,
                observer,
                far,
                online,
                saves,
                ground_sessions,
                magic_table,
                displays,
                gates,
                rx,
            }
        }

        fn cast(&mut self, magic_id: u16, click: (i32, i32), target_actor_id: i32) {
            let mut catalog = game_svr::ability::StdItemCatalog::new();
            catalog.insert(
                1,
                mir2_data::StdItem {
                    name: "护身符".into(),
                    std_mode: 25,
                    shape: 5,
                    ..mir2_data::StdItem::default()
                },
            );
            let pet_cfg = mir2_data::pet_slave::PetSlaveConfig::default();
            let table = game_svr::mongen::MonsterTable::new(Vec::new());
            let registry = mir2_envir::MapRegistry::from_entries(
                mir2_envir::MapLoader::new(".", "map", "envir"),
                Vec::new(),
            );
            handle_spell_cmd(
                game_svr::feature::make_long(
                    u16::try_from(click.0).unwrap_or(0),
                    u16::try_from(click.1).unwrap_or(0),
                ),
                magic_id,
                u16::try_from(target_actor_id).unwrap_or(0),
                0,
                "caster",
                911,
                &self.online,
                &mut self.world,
                &mut self.saves,
                &mut self.ground_sessions,
                &catalog,
                &self.magic_table,
                &pet_cfg,
                8,
                Some(&registry),
                &table,
                &mut self.displays,
                &self.gates,
                1,
                1,
                2,
            );
        }

        fn drain(&mut self) -> Vec<SfFrame> {
            let mut frames = Vec::new();
            while let Ok(m) = self.rx.try_recv() {
                if let SimToGate::SendFrame { socket, body } = m {
                    frames.push((socket, body));
                }
            }
            frames
        }

        /// 推进时钟并投递到点的自身延时消息；返回本批出帧。
        fn deliver(&mut self, advance_ms: i64) -> Vec<SfFrame> {
            self.world.clock_ms += advance_ms;
            let outs = self.world.deliver_self_delay_msgs();
            let rec = mir2_world::TickRecord {
                slave_self_deliveries: outs,
                ..Default::default()
            };
            drain_b3_self_deliveries(
                &rec,
                &self.world,
                &self.online,
                &mut self.ground_sessions,
                &self.gates,
            );
            self.drain()
        }

        #[allow(clippy::too_many_arguments)]
        fn add_monster(
            &mut self,
            name: &str,
            x: i32,
            y: i32,
            race: u8,
            animal: bool,
            level: u8,
            life_attrib: u8,
            meat_quality: u16,
            target_creature: Option<i32>,
            master: Option<i32>,
        ) -> i32 {
            let mut e = mir2_world::Entity::new(0, name.to_string(), x, y);
            e.race = race;
            e.level = level;
            e.hp = 100;
            e.max_hp = 100;
            e.life_attrib = life_attrib;
            e.ai.animal = animal;
            e.ai.meat_quality = meat_quality;
            e.ai.target_creature = target_creature;
            e.master = master;
            let id = self.world.add_entity(e);
            self.world.tick();
            id
        }
    }

    /// 按期望 max 序回放 `before`，逐抽返回 `(max,result)`，并要求末态 == `after`。
    fn b3_ledger(
        before: &mir2_shared::rng::RandomNumber,
        after: &mir2_shared::rng::RandomNumber,
        maxes: &[i32],
    ) -> Vec<(i32, i32)> {
        let mut probe = before.clone();
        let mut out = Vec::with_capacity(maxes.len());
        for &m in maxes {
            out.push((m, probe.random_below(m)));
        }
        assert_eq!(
            format!("{probe:?}"),
            format!("{after:?}"),
            "RNG 末态与期望 max 序不一致（多抽/少抽/换序）"
        );
        out
    }

    fn b3_seq(frames: &[SfFrame], socket: i32) -> Vec<u16> {
        frames
            .iter()
            .filter(|(s, _)| *s == socket)
            .map(|(_, b)| sf_ident(b))
            .collect()
    }

    fn b3_count(frames: &[SfFrame], socket: i32, ident: u16) -> usize {
        frames
            .iter()
            .filter(|(s, b)| *s == socket && sf_ident(b) == ident)
            .count()
    }

    /// **16 F16-A**：3 只合格 Animal ⇒ 抽 `[(0,0),(6,2),(4,1),(4,1),(4,1),(3,2)]`；
    /// `nPower=54`、`result=3`、`TranPoint=3`、`Level=2`（未升级）、延迟 640；
    /// 3×`RM_MAKEHOLYSEIZEMODE` ⇒ 投递时 3×656（两个 socket 各 3）。
    ///
    /// 牙：B3-16-2（Master 判定先于 R(4) ⇒ 少第 3–5 抽 ⇒ ledger 红）、B3-16-4（只发最后一个
    /// ⇒ 656 计数 1≠3）、B3-16-3（漏 CanWalk 见 F16-D 用例）。
    #[test]
    fn spell_p3b3_16_holy_shield_ledger_frames_and_reset() {
        const SM_17: u16 = mir2_protocol::messages::SM_SPELL;
        const SM_53: u16 = mir2_protocol::messages::SM_HEALTHSPELLCHANGED;
        const SM_638: u16 = mir2_protocol::messages::SM_MAGICFIRE;
        const SM_640: u16 = mir2_protocol::messages::SM_MAGIC_LVEXP;
        const SM_642: u16 = mir2_protocol::messages::SM_DURACHANGE;
        const SM_656: u16 = mir2_protocol::messages::SM_CHANGENAMECOLOR;

        // ---- F16-A：3 只合格 ----
        let mut rig = B3Rig::new(16, 2, true);
        let m1 = rig.add_monster("m1", 11, 11, 50, true, 30, 0, 0, None, None);
        let m2 = rig.add_monster("m2", 12, 11, 50, true, 30, 0, 0, None, None);
        let m3 = rig.add_monster("m3", 12, 12, 50, true, 30, 0, 0, None, None);
        let before = rig.world.rng.clone();
        rig.cast(16, (12, 12), 0);
        let frames = rig.drain();
        let got = b3_ledger(&before, &rig.world.rng, &[0, 6, 4, 4, 4, 3]);
        assert_eq!(
            got,
            vec![(0, 0), (6, 2), (4, 1), (4, 1), (4, 1), (3, 2)],
            "F16-A 逐抽"
        );
        assert_eq!(
            b3_seq(&frames, 911),
            vec![SM_53, SM_638, SM_642],
            "SELF 立即序（53(68)→638(136)→642(141)；17 排除自己）"
        );
        assert_eq!(b3_seq(&frames, 912), vec![SM_17, SM_638], "OBS 立即序");
        assert!(b3_count(&frames, rig.far, SM_17) == 0, "FAR 不在 ±12");
        assert_eq!(
            rig.world
                .self_delay_msgs
                .iter()
                .filter(|m| m.ident == mir2_world::slave::RM_MAKEHOLYSEIZEMODE)
                .count(),
            3,
            "F16-A 三只怪各收一条 RM_MAKEHOLYSEIZEMODE"
        );
        for id in [m1, m2, m3] {
            assert!(!rig.world.entities.get(id).unwrap().ai.holy_seize);
        }
        // 立即帧取完后再投递 0ms 消息 ⇒ 3×656（怪处理自己的队列）。
        let f656 = rig.deliver(0);
        assert_eq!(b3_count(&f656, 911, SM_656), 3, "SELF 收 3×656");
        assert_eq!(b3_count(&f656, 912, SM_656), 3, "OBS 收 3×656");
        for id in [m1, m2, m3] {
            let e = rig.world.entities.get(id).unwrap();
            assert!(e.ai.holy_seize, "OpenHolySeizeMode 落状态");
            assert_eq!(e.ai.holy_seize_interval, 54_000);
        }
        // 656 的色 = 接收者侧 `GetChrColor` ⇒ 怪的 `name_color`（构造缺省 255）。
        // `MonsterObject.GetChrColor` 的 HolySeize 0x7D 覆写在本处理器不可达。
        let body = f656
            .iter()
            .find(|(s, b)| *s == 911 && sf_ident(b) == SM_656)
            .map(|(_, b)| b)
            .unwrap();
        let cm = mir2_protocol::frame::CommandMessage::from_bytes(body).unwrap();
        assert_eq!(cm.param, 255, "656 的颜色 = 目标 name_color");
        // 640：1000ms 后、仅自己，载荷 (MagicId=16, Level=2, TranPoint=3)。
        assert_eq!(b3_count(&frames, 911, SM_640), 0, "640 不得立即发");
        let f640 = rig.deliver(1000);
        assert_eq!(b3_seq(&f640, 911), vec![SM_640]);
        let body = f640.iter().find(|(s, _)| *s == 911).unwrap().1.clone();
        let cm = mir2_protocol::frame::CommandMessage::from_bytes(&body).unwrap();
        assert_eq!(
            (cm.recog, cm.param, cm.tag, cm.series),
            (16, 2, 3, 0),
            "640 载荷 MagicId/Level/TranPoint"
        );
        assert_eq!(rig.tran_level(), 2, "F16-A 未升级");
        assert_eq!(rig.tran_point(), 3);

        // ---- F16-B：第三只 master=Some(caster) ⇒ result 归零（已发帧不回滚）----
        let mut rig = B3Rig::new(16, 2, true);
        let a = rig.add_monster("a", 11, 12, 50, true, 30, 0, 0, None, None);
        let b = rig.add_monster("b", 12, 12, 50, true, 30, 0, 0, None, None);
        let caster_id = rig.caster;
        let _c = rig.add_monster("c", 13, 12, 50, true, 30, 0, 0, None, Some(caster_id));
        let before = rig.world.rng.clone();
        rig.cast(16, (12, 12), 0);
        let frames = rig.drain();
        let got = b3_ledger(&before, &rig.world.rng, &[0, 6, 4, 4, 4]);
        assert_eq!(
            got,
            vec![(0, 0), (6, 2), (4, 1), (4, 1), (4, 1)],
            "F16-B：master=Some 的怪仍抽 R(4)（B3-16-2 判别）"
        );
        assert_eq!(
            rig.world
                .self_delay_msgs
                .iter()
                .filter(|m| m.ident == mir2_world::slave::RM_MAKEHOLYSEIZEMODE)
                .count(),
            2,
            "两只合格怪各收一条"
        );
        assert_eq!(b3_count(&frames, 911, SM_638), 1);
        let f656 = rig.deliver(0);
        assert_eq!(b3_count(&f656, 911, SM_656), 2, "已发帧不回滚：2×656");
        // result=0 ⇒ 无训练门 ⇒ 无 640（B3-16-1 判别）。
        let f640 = rig.deliver(1000);
        assert_eq!(b3_count(&f640, 911, SM_640), 0, "result 归零 ⇒ 无 640");
        assert_eq!(rig.tran_point(), 0, "result 归零 ⇒ 无熟练点");
        let _ = (a, b);
    }

    /// **16 F16-C/F16-D**：护身符门失败 ⇒ 恰一条 639、零抽；`CanWalk` 失败 ⇒ 只有
    /// `(0,0),(6,2)` 两抽、`result=0`、无 640/656。
    ///
    /// 牙：B3-16-3（漏 CanWalk ⇒ 多 `R(4)`/多 656）。
    #[test]
    fn spell_p3b3_16_gate_and_canwalk() {
        const SM_17: u16 = mir2_protocol::messages::SM_SPELL;
        const SM_53: u16 = mir2_protocol::messages::SM_HEALTHSPELLCHANGED;
        const SM_638: u16 = mir2_protocol::messages::SM_MAGICFIRE;
        const SM_639: u16 = mir2_protocol::messages::SM_MAGICFIRE_FAIL;
        const SM_640: u16 = mir2_protocol::messages::SM_MAGIC_LVEXP;
        const SM_642: u16 = mir2_protocol::messages::SM_DURACHANGE;

        // F16-C：无护身符。
        let mut rig = B3Rig::new(16, 2, false);
        let before = rig.world.rng.clone();
        rig.cast(16, (12, 12), 0);
        let frames = rig.drain();
        assert_eq!(
            b3_ledger(&before, &rig.world.rng, &[]),
            Vec::<(i32, i32)>::new(),
            "F16-C 零抽"
        );
        assert_eq!(b3_seq(&frames, 911), vec![SM_53, SM_639], "SELF 53→639");
        assert_eq!(b3_seq(&frames, 912), vec![SM_17, SM_639], "OBS 17→639");
        assert!(b3_count(&frames, 911, SM_642) == 0, "门失败无 642");
        assert!(b3_count(&frames, 911, SM_638) == 0, "门失败无 638");

        // F16-D：中心格 HighWall ⇒ CanWalk=false。不得用边界外坐标（会被距离门先挡）。
        let mut rig = B3Rig::new(16, 2, true);
        {
            let map = &mut rig.world.maps[0];
            let (cell, ok) = map.get_cell_info_mut(12, 12);
            assert!(ok);
            cell.attribute = mir2_world::CellAttribute::HighWall;
        }
        let before = rig.world.rng.clone();
        rig.cast(16, (12, 12), 0);
        let frames = rig.drain();
        assert_eq!(
            b3_ledger(&before, &rig.world.rng, &[0, 6]),
            vec![(0, 0), (6, 2)],
            "F16-D：实参两抽照发生、helper 零抽"
        );
        assert_eq!(b3_seq(&frames, 911), vec![SM_53, SM_638, SM_642]);
        let f = rig.deliver(1000);
        assert_eq!(b3_count(&f, 911, SM_640), 0, "result=0 ⇒ 无 640");
        assert_eq!(
            b3_count(&f, 911, mir2_protocol::messages::SM_CHANGENAMECOLOR),
            0
        );
    }

    /// **18 F18-A/B/C**：坐标短路（|dx|>1 不抽）、helper 早退时实参两抽照发生、
    /// 657 逐收件人 `HitSpeed`（B3-18-1/2/3/4）。
    #[test]
    fn spell_p3b3_18_cloak_short_circuit_early_exit_and_per_recipient_hit_speed() {
        const SM_17: u16 = mir2_protocol::messages::SM_SPELL;
        const SM_53: u16 = mir2_protocol::messages::SM_HEALTHSPELLCHANGED;
        const SM_638: u16 = mir2_protocol::messages::SM_MAGICFIRE;
        const SM_639: u16 = mir2_protocol::messages::SM_MAGICFIRE_FAIL;
        const SM_640: u16 = mir2_protocol::messages::SM_MAGIC_LVEXP;
        const SM_642: u16 = mir2_protocol::messages::SM_DURACHANGE;
        const SM_657: u16 = mir2_protocol::messages::SM_CHARSTATUSCHANGED;

        // F18-A。
        let mut rig = B3Rig::new(18, 2, true);
        rig.world.entities.get_mut(rig.caster).unwrap().hit_speed = 7;
        rig.world.entities.get_mut(rig.observer).unwrap().hit_speed = 9;
        let caster_id = rig.caster;
        let observer_id = rig.observer;
        let _m1 = rig.add_monster("m1", 11, 10, 50, true, 30, 0, 0, Some(caster_id), None);
        let _m2 = rig.add_monster("m2", 15, 10, 50, true, 30, 0, 0, Some(caster_id), None);
        let m3 = rig.add_monster("m3", 10, 11, 50, true, 30, 0, 0, Some(observer_id), None);
        let before = rig.world.rng.clone();
        rig.cast(18, (10, 10), 0);
        let frames = rig.drain();
        assert_eq!(
            b3_ledger(&before, &rig.world.rng, &[0, 6, 2, 3]),
            vec![(0, 0), (6, 2), (2, 0), (3, 1)],
            "F18-A：M2 |dx|=5 短路不抽（B3-18-2 判别）"
        );
        assert_eq!(
            b3_seq(&frames, 911),
            vec![SM_53, SM_638, SM_642, SM_657],
            "SELF：按优先级 53(68)→638(136)→642(141)→657(155)"
        );
        assert_eq!(
            b3_seq(&frames, 912),
            vec![SM_17, SM_638, SM_657],
            "OBS：17(24)→638(136)→657(155)"
        );
        assert_eq!(b3_count(&frames, 914, SM_657), 0);
        // 逐收件人 HitSpeed：SELF 7、OBS 9（B3-18-4 判别：一条 body 广播会两边相同）。
        for (socket, want) in [(911, 7u16), (912, 9u16)] {
            let body = frames
                .iter()
                .find(|(s, b)| *s == socket && sf_ident(b) == SM_657)
                .map(|(_, b)| b)
                .unwrap();
            let cm = mir2_protocol::frame::CommandMessage::from_bytes(body).unwrap();
            assert_eq!(cm.recog, rig.caster, "657 ActorId = 施法者");
            assert_eq!(cm.series, want, "socket {socket} 的 HitSpeed 取自己的");
        }
        assert_eq!(
            rig.world.entities.get(m3).unwrap().ai.target_creature,
            Some(rig.observer)
        );
        // m1 的 R(2)=0 ⇒ 清目标。
        assert_eq!(
            rig.world.entities.get(_m1).unwrap().ai.target_creature,
            None
        );
        let st = rig.world.entities.get(rig.caster).unwrap();
        assert_eq!(st.status_time[8], 46, "nHTime = 25+7*3");
        assert!(st.hide_mode && st.transparent);
        let f = rig.deliver(1000);
        assert_eq!(b3_seq(&f, 911), vec![SM_640]);
        assert_eq!(rig.tran_point(), 2);

        // F18-B：已隐身 ⇒ helper 早退（无 657），但 GP13/RP 两抽照发生（B3-18-3）。
        let mut rig = B3Rig::new(18, 2, true);
        rig.world.entities.get_mut(rig.caster).unwrap().status_time[8] = 100;
        let before = rig.world.rng.clone();
        rig.cast(18, (10, 10), 0);
        let frames = rig.drain();
        assert_eq!(
            b3_ledger(&before, &rig.world.rng, &[0, 6]),
            vec![(0, 0), (6, 2)],
            "F18-B：实参两抽照发生"
        );
        assert_eq!(b3_seq(&frames, 911), vec![SM_53, SM_638, SM_642]);
        assert_eq!(b3_count(&frames, 911, SM_657), 0);
        let f = rig.deliver(1000);
        assert_eq!(b3_count(&f, 911, SM_640), 0, "helper 早退 ⇒ boTrain=false");

        // F18-C：无护身符 ⇒ 零抽 + 恰一条 639。
        let mut rig = B3Rig::new(18, 2, false);
        let before = rig.world.rng.clone();
        rig.cast(18, (10, 10), 0);
        let frames = rig.drain();
        assert_eq!(
            b3_ledger(&before, &rig.world.rng, &[]),
            Vec::<(i32, i32)>::new()
        );
        assert_eq!(b3_seq(&frames, 911), vec![SM_53, SM_639]);
        assert_eq!(b3_seq(&frames, 912), vec![SM_17, SM_639]);
    }

    /// **19 F19-A/B**：helper 内零抽；`RM_TRANSPARENT` 延迟 800、投递时重读 `StatusTimeArr[8]`
    /// 并逐怪抽 `R(2)`；`IsProperFriend` 门（B3-19-1/2/3/4）。
    #[test]
    fn spell_p3b3_19_bigcloak_delay_and_delivery_ledger() {
        const SM_17: u16 = mir2_protocol::messages::SM_SPELL;
        const SM_53: u16 = mir2_protocol::messages::SM_HEALTHSPELLCHANGED;
        const SM_638: u16 = mir2_protocol::messages::SM_MAGICFIRE;
        const SM_639: u16 = mir2_protocol::messages::SM_MAGICFIRE_FAIL;
        const SM_640: u16 = mir2_protocol::messages::SM_MAGIC_LVEXP;
        const SM_642: u16 = mir2_protocol::messages::SM_DURACHANGE;
        const SM_657: u16 = mir2_protocol::messages::SM_CHARSTATUSCHANGED;

        // F19-A。
        let mut rig = B3Rig::new(19, 2, true);
        // 已隐身玩家 4000（`StatusTimeArr[8] = 100` ⇒ 排除）。
        let hidden = rig
            .world
            .add_entity(new_player_entity("hidden".into(), 10, 11));
        rig.world.entities.get_mut(hidden).unwrap().status_time[8] = 100;
        rig.world.tick();
        // 3×3 内的怪 M4（不是 friend ⇒ 不得收 RM_TRANSPARENT）。
        let caster_id = rig.caster;
        let _m4 = rig.add_monster("m4", 9, 10, 50, true, 30, 0, 0, Some(caster_id), None);
        let before = rig.world.rng.clone();
        rig.cast(19, (10, 10), 0);
        let frames = rig.drain();
        assert_eq!(
            b3_ledger(&before, &rig.world.rng, &[0, 6, 3]),
            vec![(0, 0), (6, 2), (3, 0)],
            "F19-A：helper 内零抽（B3-19-1 判别）"
        );
        assert_eq!(b3_seq(&frames, 911), vec![SM_53, SM_638, SM_642]);
        assert_eq!(b3_seq(&frames, 912), vec![SM_17, SM_638]);
        assert_eq!(
            b3_count(&frames, 911, SM_657),
            0,
            "657 不在施法 tick（B3-19-3）"
        );
        let queued: Vec<i32> = rig
            .world
            .self_delay_msgs
            .iter()
            .filter(|m| m.ident == mir2_world::slave::RM_TRANSPARENT)
            .map(|m| m.actor_id)
            .collect();
        assert_eq!(
            queued,
            vec![rig.caster, rig.observer],
            "恰两名友方（B3-19-2）"
        );
        assert!(rig
            .world
            .self_delay_msgs
            .iter()
            .filter(|m| m.ident == mir2_world::slave::RM_TRANSPARENT)
            .all(|m| m.deliver_at_ms == rig.world.clock_ms + 800 && m.n_param1 == 46));
        // 800ms：两条投递、两条 657；caster 的投递额外抽一次 R(2)（M4 贴身）。
        let before_del = rig.world.rng.clone();
        let f = rig.deliver(800);
        assert_eq!(
            b3_ledger(&before_del, &rig.world.rng, &[2]),
            vec![(2, 0)],
            "投递 tick 的账本（B3-19-4）"
        );
        // 两条投递各广播一次 657；两个玩家互为 ±12 内 ⇒ 每个 socket 各收 2 条。
        assert_eq!(b3_count(&f, 911, SM_657), 2, "SELF 收两次投递的 657");
        assert_eq!(b3_count(&f, 912, SM_657), 2, "OBS 收两次投递的 657");
        let f2 = rig.deliver(200);
        assert_eq!(b3_seq(&f2, 911), vec![SM_640], "1000ms 训练帧");
        assert_eq!(rig.tran_level(), 2);
        assert_eq!(rig.tran_point(), 1);

        // F19-B：无护身符 ⇒ 零抽 + 恰一条 639。
        let mut rig = B3Rig::new(19, 2, false);
        let before = rig.world.rng.clone();
        rig.cast(19, (10, 10), 0);
        let frames = rig.drain();
        assert_eq!(
            b3_ledger(&before, &rig.world.rng, &[]),
            Vec::<(i32, i32)>::new()
        );
        assert_eq!(b3_seq(&frames, 911), vec![SM_53, SM_639]);
        assert_eq!(b3_seq(&frames, 912), vec![SM_17, SM_639]);
    }

    /// **28 F28-A/B/C/D/E**：ShowHp 门、RP→GP13 顺序、`*1000`、1500ms 延迟、无去重。
    #[test]
    fn spell_p3b3_28_showhp_gate_order_interval_and_duplicate() {
        const SM_17: u16 = mir2_protocol::messages::SM_SPELL;
        const SM_53: u16 = mir2_protocol::messages::SM_HEALTHSPELLCHANGED;
        const SM_638: u16 = mir2_protocol::messages::SM_MAGICFIRE;
        const SM_640: u16 = mir2_protocol::messages::SM_MAGIC_LVEXP;
        const SM_1100: u16 = mir2_protocol::messages::SM_OPENHEALTH;

        // F28-A：目标怪 ShowHp=false。
        let mut rig = B3Rig::new(28, 2, true);
        let target = rig.add_monster("t", 12, 10, 80, false, 30, 0, 0, None, None);
        rig.world.entities.get_mut(target).unwrap().hp = 80;
        rig.world.entities.get_mut(target).unwrap().max_hp = 100;
        let before = rig.world.rng.clone();
        rig.cast(28, (12, 10), target);
        let frames = rig.drain();
        assert_eq!(
            b3_ledger(&before, &rig.world.rng, &[6, 6, 0, 3]),
            vec![(6, 5), (6, 2), (0, 0), (3, 1)],
            "F28-A：R(6) → RP → GP13（B3-28-1 判别）"
        );
        assert_eq!(b3_seq(&frames, 911), vec![SM_53, SM_638]);
        assert_eq!(b3_seq(&frames, 912), vec![SM_17, SM_638]);
        assert_eq!(
            b3_count(&frames, 911, SM_1100),
            0,
            "1100 必须延迟（B3-28-4）"
        );
        assert_eq!(
            rig.world.entities.get(target).unwrap().show_hp_interval,
            37_000,
            "ShowHpInterval = 37 * 1000（B3-28-3）"
        );
        let f = rig.deliver(1000);
        assert_eq!(b3_seq(&f, 911), vec![SM_640]);
        let before_del = rig.world.rng.clone();
        let f = rig.deliver(500);
        assert_eq!(
            b3_ledger(&before_del, &rig.world.rng, &[]),
            Vec::<(i32, i32)>::new()
        );
        assert_eq!(b3_count(&f, 911, SM_1100), 1, "1100 投递到 SELF");
        assert_eq!(b3_count(&f, 912, SM_1100), 1, "1100 投递到 OBS");
        assert!(rig.world.entities.get(target).unwrap().show_hp);
        // 1100 的 HP/MaxHP 取目标。
        let body = f
            .iter()
            .find(|(s, b)| *s == 911 && sf_ident(b) == SM_1100)
            .unwrap()
            .1
            .clone();
        let cm = mir2_protocol::frame::CommandMessage::from_bytes(&body).unwrap();
        // 生产用冻结客户端 HIGHHP 布局：`param/tag = lo/hi(HP)`，MaxHP 在 4B 尾里。
        assert_eq!((cm.recog, cm.param, cm.tag), (target, 80, 0));
        let tail = mir2_protocol::edcode::decode(&body[12..]);
        assert_eq!(u16::from_le_bytes([tail[0], tail[1]]), 100, "MaxHP=100");

        // F28-B：ShowHp=true ⇒ 零抽（B3-28-2）。
        let mut rig = B3Rig::new(28, 2, true);
        let target = rig.add_monster("t", 12, 10, 80, false, 30, 0, 0, None, None);
        rig.world.entities.get_mut(target).unwrap().show_hp = true;
        let before = rig.world.rng.clone();
        rig.cast(28, (12, 10), target);
        let frames = rig.drain();
        assert_eq!(
            b3_ledger(&before, &rig.world.rng, &[]),
            Vec::<(i32, i32)>::new()
        );
        assert_eq!(b3_seq(&frames, 911), vec![SM_53, SM_638]);
        let f = rig.deliver(1500);
        assert_eq!(b3_count(&f, 911, SM_1100) + b3_count(&f, 911, SM_640), 0);

        // F28-C：无目标 ⇒ 零抽、无 640、638 targetId=0。
        let mut rig = B3Rig::new(28, 2, true);
        let before = rig.world.rng.clone();
        rig.cast(28, (12, 10), 0);
        let frames = rig.drain();
        assert_eq!(
            b3_ledger(&before, &rig.world.rng, &[]),
            Vec::<(i32, i32)>::new()
        );
        let body = frames
            .iter()
            .find(|(s, b)| *s == 911 && sf_ident(b) == SM_638)
            .unwrap()
            .1
            .clone();
        let tail = mir2_protocol::edcode::decode(&body[12..]);
        assert_eq!(
            i32::from_le_bytes([tail[0], tail[1], tail[2], tail[3]]),
            0,
            "638 尾 targetId=0"
        );
        let f = rig.deliver(1500);
        assert_eq!(b3_count(&f, 911, SM_640), 0);

        // F28-D：Level=0 ⇒ R(6)=5 > 3 门失败（B3-28 gate）。
        let mut rig = B3Rig::new(28, 0, true);
        let target = rig.add_monster("t", 12, 10, 80, false, 30, 0, 0, None, None);
        let before = rig.world.rng.clone();
        rig.cast(28, (12, 10), target);
        let frames = rig.drain();
        assert_eq!(
            b3_ledger(&before, &rig.world.rng, &[6]),
            vec![(6, 5)],
            "F28-D 只抽一次且不过门"
        );
        assert_eq!(b3_seq(&frames, 911), vec![SM_53, SM_638]);
        let f = rig.deliver(1500);
        assert_eq!(b3_count(&f, 911, SM_640), 0);

        // F28-E：1500ms 内重复施法不去重 ⇒ 两条 1100（B3-28-4 反面）。
        let mut rig = B3Rig::new(28, 2, true);
        let target = rig.add_monster("t", 12, 10, 80, false, 30, 0, 0, None, None);
        rig.cast(28, (12, 10), target);
        let _ = rig.drain();
        rig.cast(28, (12, 10), target);
        let _ = rig.drain();
        assert_eq!(
            rig.world
                .self_delay_msgs
                .iter()
                .filter(|m| m.ident == mir2_world::slave::RM_DOOPENHEALTH)
                .count(),
            2,
            "重复施法各入队一条（oracle 无去重）"
        );
        let f = rig.deliver(1500);
        assert_eq!(b3_count(&f, 911, SM_1100), 2, "两条 1100");
    }

    /// **32 F32-A/B/C/D/E + InvalidCast**：`Struck` 三支、`ushort` 回绕、非 AnimalObject 的
    /// 异常被吞 ⇒ 639 无尾（B3-32-1/2/3/4）。
    #[test]
    fn spell_p3b3_32_turn_undead_struck_wrap_and_invalid_cast() {
        const SM_17: u16 = mir2_protocol::messages::SM_SPELL;
        const SM_53: u16 = mir2_protocol::messages::SM_HEALTHSPELLCHANGED;
        const SM_638: u16 = mir2_protocol::messages::SM_MAGICFIRE;
        const SM_639: u16 = mir2_protocol::messages::SM_MAGICFIRE_FAIL;
        const SM_640: u16 = mir2_protocol::messages::SM_MAGIC_LVEXP;
        const SM_642: u16 = mir2_protocol::messages::SM_DURACHANGE;

        // F32-A：undead Animal、TargetCret=None。
        let mut rig = B3Rig::new(32, 2, true);
        let target = rig.add_monster("u", 11, 10, 80, true, 30, 1, 100, None, None);
        let before = rig.world.rng.clone();
        rig.cast(32, (11, 10), target);
        let frames = rig.drain();
        assert_eq!(
            b3_ledger(&before, &rig.world.rng, &[300, 2, 100, 3]),
            vec![(300, 269), (2, 0), (100, 32), (3, 1)],
            "F32-A 逐抽（B3-32-2：无 R(6)）"
        );
        assert_eq!(
            b3_seq(&frames, 911),
            vec![SM_53, SM_638],
            "32 无护身符/无 642"
        );
        assert_eq!(b3_seq(&frames, 912), vec![SM_17, SM_638]);
        // `MagicManager.cs:841` 在 Struck 后无条件 `playObject.SetTargetCreat(targetObject)`
        // ⇒ 施法者 `TargetCret`/`TargetFocusTick`（本 must_fix 的断言）。
        assert_eq!(
            rig.world
                .entities
                .get(rig.caster)
                .unwrap()
                .ai
                .target_creature,
            Some(target),
            "F32-A：施法者 TargetCret == 被圣言目标"
        );
        let e = rig.world.entities.get(target).unwrap();
        assert_eq!(e.hp, 0, "圣言即死");
        assert_eq!(e.ai.meat_quality, 65367, "ushort 回绕（B3-32-3）");
        assert_eq!(e.ai.attack_tick, 30, "150 - min(130,30*4)");
        let f = rig.deliver(1000);
        assert_eq!(b3_seq(&f, 911), vec![SM_640]);

        // F32-B：TargetCret=Some(相邻怪) ⇒ GetAttackDir 真 ⇒ 无 R(6)。
        let mut rig = B3Rig::new(32, 2, true);
        let other = rig.add_monster("o", 12, 10, 80, false, 30, 0, 0, None, None);
        let target = rig.add_monster("u", 11, 10, 80, true, 30, 1, 100, Some(other), None);
        let before = rig.world.rng.clone();
        rig.cast(32, (11, 10), target);
        let _ = rig.drain();
        assert_eq!(
            b3_ledger(&before, &rig.world.rng, &[300, 2, 100, 3]),
            vec![(300, 269), (2, 0), (100, 32), (3, 1)],
            "F32-B 无 R(6)"
        );
        assert_eq!(
            rig.world
                .entities
                .get(rig.caster)
                .unwrap()
                .ai
                .target_creature,
            Some(target),
            "F32-B：施法者 TargetCret == 被圣言目标"
        );

        // F32-C：TargetCret=Some(远处怪) ⇒ 抽 R(6)；Level=3 避免 TRAIN。
        let mut rig = B3Rig::new(32, 3, true);
        let far_mob = rig.add_monster("far", 30, 30, 80, false, 30, 0, 0, None, None);
        let target = rig.add_monster("u", 11, 10, 80, true, 30, 1, 100, Some(far_mob), None);
        let before = rig.world.rng.clone();
        rig.cast(32, (11, 10), target);
        let frames = rig.drain();
        assert_eq!(
            b3_ledger(&before, &rig.world.rng, &[6, 300, 2, 100]),
            vec![(6, 5), (300, 124), (2, 0), (100, 40)],
            "F32-C 抽 R(6) 且 R(6)!=0 ⇒ 不改目标"
        );
        assert_eq!(b3_seq(&frames, 911), vec![SM_53, SM_638]);
        assert_eq!(
            rig.world
                .entities
                .get(rig.caster)
                .unwrap()
                .ai
                .target_creature,
            Some(target),
            "F32-C：施法者 TargetCret == 被圣言目标"
        );
        assert_eq!(
            rig.world.entities.get(target).unwrap().ai.meat_quality,
            65512
        );
        let f = rig.deliver(1000);
        assert_eq!(b3_count(&f, 911, SM_640), 0, "Level=3 ⇒ 无 TRAIN");

        // F32-D：非 undead ⇒ 零抽（B3-32-1/4）。
        let mut rig = B3Rig::new(32, 2, true);
        let target = rig.add_monster("m", 11, 10, 80, true, 30, 0, 100, None, None);
        let before = rig.world.rng.clone();
        rig.cast(32, (11, 10), target);
        let frames = rig.drain();
        assert_eq!(
            b3_ledger(&before, &rig.world.rng, &[]),
            Vec::<(i32, i32)>::new()
        );
        assert_eq!(b3_seq(&frames, 911), vec![SM_53, SM_638]);
        assert!(rig.world.entities.get(target).unwrap().ai.meat_quality == 100);

        // F32-E：IsProperTarget 失败（无目标）⇒ 零抽、638 targetId=0。
        let mut rig = B3Rig::new(32, 2, true);
        let before = rig.world.rng.clone();
        rig.cast(32, (11, 10), 0);
        let frames = rig.drain();
        assert_eq!(
            b3_ledger(&before, &rig.world.rng, &[]),
            Vec::<(i32, i32)>::new()
        );
        let body = frames
            .iter()
            .find(|(s, b)| *s == 911 && sf_ident(b) == SM_638)
            .unwrap()
            .1
            .clone();
        let tail = mir2_protocol::edcode::decode(&body[12..]);
        assert_eq!(
            i32::from_le_bytes([tail[0], tail[1], tail[2], tail[3]]),
            0,
            "638 尾 targetId=0"
        );
        let f = rig.deliver(1000);
        assert_eq!(b3_count(&f, 911, SM_640), 0);

        // InvalidCast：玩家目标 + LA_UNDEAD ⇒ `(AnimalObject)` 抛异常被吞 ⇒ 639、无尾。
        let mut rig = B3Rig::new(32, 2, true);
        let ptarget = rig.world.add_entity(new_player_entity("pt".into(), 11, 10));
        rig.world.tick();
        rig.world.entities.get_mut(ptarget).unwrap().life_attrib = 1;
        let before = rig.world.rng.clone();
        rig.cast(32, (11, 10), ptarget);
        let frames = rig.drain();
        assert_eq!(
            b3_ledger(&before, &rig.world.rng, &[]),
            Vec::<(i32, i32)>::new(),
            "抛异常前零抽"
        );
        assert!(b3_count(&frames, 911, SM_639) == 1, "恰一条 639");
        assert!(b3_count(&frames, 912, SM_639) == 1);
        assert_eq!(b3_count(&frames, 911, SM_638), 0, "异常 ⇒ 无共享尾");
        assert_eq!(b3_count(&frames, 911, SM_642), 0);
        let f = rig.deliver(1000);
        assert_eq!(b3_count(&f, 911, SM_640), 0);
    }

    /// **P3 收尾残余 1 生产入口**：32 圣言术的等级门读 `World::mag_turn_undead_level`
    /// （`Config.MagTurnUndeadLevel`），不再是硬编码 50。
    ///
    /// 同一夹具（目标 Lv=40、施法者 Lv=60、固定 `B3_SEED`）：
    /// - 配置 30 ⇒ `target.Level < 30` 假 ⇒ **不抽**尾 R(100)、HP 保持 100；
    /// - 配置 50 ⇒ 门真 ⇒ 抽 R(100)=32 < 49 ⇒ HP 归零。
    ///
    /// 牙：把 `world.mag_turn_undead_level` 换回常量 50 ⇒ 第一段 HP≠0 断言必红。
    #[test]
    fn p3res_spell_32_turn_undead_uses_configured_level_gate() {
        const SM_53: u16 = mir2_protocol::messages::SM_HEALTHSPELLCHANGED;
        const SM_638: u16 = mir2_protocol::messages::SM_MAGICFIRE;

        // 配置 30：目标 Lv=40 被 `target.Level < 30` 挡下（仍走 Struck：R(300)）。
        let mut rig = B3Rig::new(32, 2, true);
        rig.world.set_mag_turn_undead_level(30);
        let target = rig.add_monster("u", 11, 10, 80, true, 40, 1, 100, None, None);
        let before = rig.world.rng.clone();
        rig.cast(32, (11, 10), target);
        let frames = rig.drain();
        assert_eq!(
            b3_ledger(&before, &rig.world.rng, &[300, 2]),
            vec![(300, 269), (2, 0)],
            "cfg=30：等级门失败 ⇒ 无尾 R(100)；boTrain=false ⇒ 训练尾 R(3) 也不抽"
        );
        assert_eq!(b3_seq(&frames, 911), vec![SM_53, SM_638]);
        assert_eq!(
            rig.world.entities.get(target).unwrap().hp,
            100,
            "cfg=30 时 target.Lv=40 不被圣言 ⇒ HP 不变"
        );

        // 配置 50（oracle 缺省）：同夹具 ⇒ 门真，R(100)=32 命中 ⇒ HP=0。
        let mut rig = B3Rig::new(32, 2, true);
        rig.world.set_mag_turn_undead_level(50);
        let target = rig.add_monster("u", 11, 10, 80, true, 40, 1, 100, None, None);
        let before = rig.world.rng.clone();
        rig.cast(32, (11, 10), target);
        let frames = rig.drain();
        assert_eq!(
            b3_ledger(&before, &rig.world.rng, &[300, 2, 100, 3]),
            vec![(300, 269), (2, 0), (100, 32), (3, 1)],
            "cfg=50：尾 R(100) 照抽"
        );
        assert_eq!(b3_seq(&frames, 911), vec![SM_53, SM_638]);
        assert_eq!(
            rig.world.entities.get(target).unwrap().hp,
            0,
            "cfg=50 时 target.Lv=40 < 50 ⇒ 圣言即死"
        );
    }

    /// **P3 收尾残余 2 端到端**：`HitSpeed` 的生产写点 = `recalc_session_ability` →
    /// `apply_ability_to_entity`（oracle `PlayObject.cs:2899` `HitSpeed = AddAbil.HitSpeed`）。
    ///
    /// 两个收件人装备不同武器（StdMode 5，`Hi(MAC)` 13/15 ⇒ `RealAttackSpeed` = 3/5），
    /// 走 `RecalcAbilitys` 的 `ApplyItemParameters`（`PlayObject.cs:4419`）得到各自的
    /// `AddAbil.HitSpeed`，写进 `Entity.hit_speed`；随后施放 18 隐身 ⇒ 657 的
    /// `Series` 末参 = **每个收件人自己的** HitSpeed（`PlayObject.Message.cs:1846`）。
    ///
    /// 牙：删掉 `apply_ability_to_entity` 的 `e.hit_speed = hit_speed` ⇒ 两个实体仍是 0
    /// ⇒ 下面的 3/5 断言必红（既有 B3-18 用例是手工写 `hit_speed`，盖不住这个缺口）。
    #[test]
    fn p3res_hit_speed_written_from_recalc_drives_657_tail() {
        const SM_657: u16 = mir2_protocol::messages::SM_CHARSTATUSCHANGED;

        fn weapon_item(index: u16) -> game_svr::bag::BagItem {
            let mut it = game_svr::bag::BagItem::new(i32::from(index), index);
            it.dura = 100;
            it
        }

        let mut rig = B3Rig::new(18, 2, true);
        let mut catalog = game_svr::ability::StdItemCatalog::new();
        for (index, hi_mac) in [(7101u16, 13u16), (7102u16, 15u16)] {
            catalog.insert(
                index,
                mir2_data::StdItem {
                    name: format!("w{hi_mac}"),
                    std_mode: 5,
                    mac: hi_mac << 8,
                    ..mir2_data::StdItem::default()
                },
            );
        }

        // 收件人 A（施法者自己）：+3。
        let mut cg = rig.ground_sessions.remove("caster").unwrap();
        cg.use_items[game_svr::ability::SLOT_WEAPON] = Some(weapon_item(7101));
        recalc_session_ability(&mut cg, &catalog, None, None);
        assert_eq!(
            cg.hit_speed, 3,
            "StdMode 5 + Hi(MAC)=13 ⇒ RealAttackSpeed=3"
        );
        apply_ability_to_entity(
            rig.world.entities.get_mut(rig.caster).unwrap(),
            &cg.state.wabil,
            &cg.sub,
            cg.hit_speed,
        );
        rig.ground_sessions.insert("caster".into(), cg);
        assert_eq!(rig.world.entities.get(rig.caster).unwrap().hit_speed, 3);

        // 收件人 B（观察者）：+5。
        let mut og = spell_session_ground(rig.observer);
        og.use_items[game_svr::ability::SLOT_WEAPON] = Some(weapon_item(7102));
        recalc_session_ability(&mut og, &catalog, None, None);
        assert_eq!(
            og.hit_speed, 5,
            "StdMode 5 + Hi(MAC)=15 ⇒ RealAttackSpeed=5"
        );
        apply_ability_to_entity(
            rig.world.entities.get_mut(rig.observer).unwrap(),
            &og.state.wabil,
            &og.sub,
            og.hit_speed,
        );
        assert_eq!(rig.world.entities.get(rig.observer).unwrap().hit_speed, 5);

        // 18 隐身的 657 收件人集合 = 自身 + 观察者（F18-A 同夹具）。
        let caster_id = rig.caster;
        let observer_id = rig.observer;
        let _m1 = rig.add_monster("m1", 11, 10, 50, true, 30, 0, 0, Some(caster_id), None);
        let _m2 = rig.add_monster("m2", 15, 10, 50, true, 30, 0, 0, Some(caster_id), None);
        let _m3 = rig.add_monster("m3", 10, 11, 50, true, 30, 0, 0, Some(observer_id), None);
        rig.cast(18, (10, 10), 0);
        let frames = rig.drain();
        for (socket, want) in [(911i32, 3u16), (912i32, 5u16)] {
            let body = frames
                .iter()
                .find(|(s, b)| *s == socket && sf_ident(b) == SM_657)
                .map(|(_, b)| b)
                .unwrap_or_else(|| panic!("socket={socket} 未收到 657"));
            let cm = mir2_protocol::frame::CommandMessage::from_bytes(body).unwrap();
            assert_eq!(
                cm.series, want,
                "socket={socket} 的 657 末参必须是自己的 HitSpeed"
            );
        }
    }

    /// **P3 收尾残余 1 生产入口（bag）**：`handle_bag_cmd` 的两处 `HitSpeed` 生产写点——
    /// `CM_TAKEONITEM` 成功后 `RecalcAbilitys` 的 `HitSpeed = AddAbil.HitSpeed`
    /// （oracle `PlayObject.cs:2899`）必须落到 `Entity.hit_speed`（657 末参来源）；
    /// `CM_TAKEOFFITEM` 卸下后必须回落 `0`。
    ///
    /// 夹具：StdMode 5 武器 `Hi(MAC)=13` ⇒ `RealAttackSpeed(13)=3`。
    ///
    /// 牙：把 `handle_bag_cmd` 里 `e.hit_speed = sg.hit_speed` 改成 `let _ = sg.hit_speed`
    /// ⇒ 穿上后实体仍是 `0`（`left 0 / right 3`）⇒ 本用例必红。
    #[test]
    fn p3res_bag_take_on_off_syncs_hit_speed_to_entity() {
        use std::collections::HashMap;
        const SLOT_WEAPON_U16: u16 = game_svr::ability::SLOT_WEAPON as u16;

        let mut catalog = game_svr::ability::StdItemCatalog::new();
        catalog.insert(
            7101,
            mir2_data::StdItem {
                name: "w13".into(),
                std_mode: 5,
                weight: 0,
                mac: 13 << 8,
                ..mir2_data::StdItem::default()
            },
        );

        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        let mut sg = test_session_ground(42);
        sg.state.item_list = vec![game_svr::bag::BagItem {
            make_index: 60001,
            index: 7101,
            dura: 100,
            dura_max: 100,
            desc: [0u8; 14],
        }];
        sessions.insert("hero".into(), sg);

        let mut online: OnlineRegistry = Vec::new();
        online_set(
            &mut online,
            OnlineEntry {
                account: "ua".into(),
                chr_name: "hero".into(),
                session_id: 1,
                gate_idx: 0,
                socket: 901,
                actor_id: 42,
            },
        );
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        let mut world = mir2_world::World::new(8, 8);
        world.add_entity(mir2_world::Entity::new(42, "hero", 3, 3));
        let mut displays = downlink::DisplayTable::new();

        // 穿上：`RecalcAbilitys` 的 `AddAbil.HitSpeed = RealAttackSpeed(Hi(MAC)=13) = 3`。
        handle_bag_cmd(
            game_svr::bag::CM_TAKEONITEM,
            60001,
            SLOT_WEAPON_U16,
            0,
            Some("w13"),
            "hero",
            901,
            &online,
            &mut sessions,
            &gates,
            &catalog,
            &mut world,
            &mut displays,
            12,
            false,
            false,
        );
        assert!(
            sessions["hero"].use_items[game_svr::ability::SLOT_WEAPON].is_some(),
            "穿装必须成功（否则本用例无判别力）"
        );
        assert_eq!(sessions["hero"].hit_speed, 3, "会话态 HitSpeed = 3");
        assert_eq!(
            world.entities.get(42).unwrap().hit_speed,
            3,
            "穿装重算后必须同步 Entity.hit_speed（657 末参的来源）"
        );
        while rx0.try_recv().is_ok() {}

        // 卸下：HitSpeed 回落 0。
        handle_bag_cmd(
            game_svr::bag::CM_TAKEOFFITEM,
            60001,
            SLOT_WEAPON_U16,
            0,
            Some("w13"),
            "hero",
            901,
            &online,
            &mut sessions,
            &gates,
            &catalog,
            &mut world,
            &mut displays,
            12,
            false,
            false,
        );
        assert!(
            sessions["hero"].use_items[game_svr::ability::SLOT_WEAPON].is_none(),
            "卸装必须成功（否则本用例无判别力）"
        );
        assert_eq!(sessions["hero"].hit_speed, 0, "会话态 HitSpeed 回落 0");
        assert_eq!(
            world.entities.get(42).unwrap().hit_speed,
            0,
            "卸装重算后必须同步回落（657 末参的来源）"
        );
    }

    /// **P3 收尾残余 1 生产入口（36）**：36 无极真气的目标重算后
    /// `RecalcAbilitys` 的 `HitSpeed = AddAbil.HitSpeed`（`PlayObject.cs:2899`）必须落到
    /// **目标**的 `Entity.hit_speed`（657 末参来源）。
    ///
    /// 夹具：目标（obs=912）装 StdMode 5 武器 `Hi(MAC)=15` ⇒ `AddAbil.HitSpeed=5`。
    /// 施法前把目标实体的 `hit_speed` 预置 `99`（哨兵）⇒ 只有生产写点会把它变成 `5`。
    ///
    /// 牙：删掉 36 支里 `e.hit_speed = sg.hit_speed` ⇒ 实体仍是 `99` ⇒ 本用例必红。
    #[test]
    fn p3res_spell_36_target_recalc_syncs_hit_speed_to_entity() {
        const SM_52: u16 = mir2_protocol::messages::SM_ABILITY;

        let mut rig = B5Rig::new(b5_magic_info(36), 2, Some(600));
        rig.seed(0);
        // 把目标的武器换成 Hi(MAC)=15 的 StdMode 5（RealAttackSpeed(15)=5）。
        rig.catalog.insert(
            3,
            mir2_data::StdItem {
                name: "w15".into(),
                std_mode: 5,
                weight: 0,
                dc: 0x0400,
                mac: 15 << 8,
                ..mir2_data::StdItem::default()
            },
        );
        rig.ground_sessions.get_mut("obs").unwrap().use_items[game_svr::ability::SLOT_WEAPON] =
            Some(game_svr::bag::BagItem {
                make_index: 2,
                index: 3,
                dura: 1000,
                dura_max: 1000,
                desc: [0; 14],
            });
        rig.world.entities.get_mut(rig.observer).unwrap().hit_speed = 99;
        rig.cast(36, (11, 9), rig.observer);
        let frames = rig.drain();
        assert_eq!(
            sf_count(&frames, 912, SM_52),
            1,
            "36 目标必须收到 52（证明目标重算真的发生了）"
        );
        assert_eq!(
            rig.world.entities.get(rig.observer).unwrap().hit_speed,
            5,
            "36 目标重算后的 HitSpeed 必须同步到实体（哨兵 99 被替换）"
        );
    }

    /// **P3 收尾残余 3 端到端**：`CheckPkStatus` 的过期口径（`PlayObject.cs:4357-4364`）：
    /// 59s 不清、61s 清 **且每个可见观察者恰一条 656**（含自己）；重复 `SetPkFlag`
    /// 刷新 `PvpNameColorTick`（oracle 赋值在 `if (!PvpFlag)` 之前）。
    ///
    /// 牙：把 `check_pk_status` 的过期支删成「永不清位」⇒ 61s 的 `pvp_flag == false` 与
    /// 656 断言必红。
    #[test]
    fn p3res_pk_flag_expiry_59s_61s_one_656_and_refresh() {
        const SM_656: u16 = mir2_protocol::messages::SM_CHANGENAMECOLOR;

        let mut rig = B3Rig::new(18, 2, true);
        rig.world.clock_ms = 0;
        rig.world.pk_check_tick = 0;
        let caster_id = rig.caster;
        // `SetPkFlag(this=observer, target=caster)`（observer 为攻击者，caster 被置位）。
        assert!(rig.world.set_pk_flag(rig.observer, caster_id).is_some());
        assert!(rig.world.entities.get(caster_id).unwrap().pvp_flag);

        // 59s：未过期 ⇒ 零 656、flag 仍在。
        rig.world.clock_ms = 59_000;
        drain_pk_flag_downlink(&mut rig.world, &rig.online, &rig.gates);
        let frames = rig.drain();
        assert_eq!(b3_count(&frames, 911, SM_656), 0, "59s 不清");
        assert!(
            rig.world.entities.get(caster_id).unwrap().pvp_flag,
            "59s PvpFlag 仍为 true"
        );

        // 61s：过期 ⇒ flag 清 + 656（caster 自己 911、观察者 912 各恰一条；远处 914 零）。
        rig.world.clock_ms = 61_000;
        drain_pk_flag_downlink(&mut rig.world, &rig.online, &rig.gates);
        let frames = rig.drain();
        assert_eq!(b3_count(&frames, 911, SM_656), 1, "自己恰一条 656");
        assert_eq!(b3_count(&frames, 912, SM_656), 1, "观察者恰一条 656");
        assert_eq!(b3_count(&frames, 914, SM_656), 0, "范围外不投递");
        assert!(
            !rig.world.entities.get(caster_id).unwrap().pvp_flag,
            "61s PvpFlag 被清"
        );
        let body = frames
            .iter()
            .find(|(s, b)| *s == 911 && sf_ident(b) == SM_656)
            .map(|(_, b)| b)
            .unwrap();
        let cm = mir2_protocol::frame::CommandMessage::from_bytes(body).unwrap();
        assert_eq!(cm.recog, caster_id, "656 Recog = 被清位者");
        assert_eq!(cm.param, 255u16, "清位后色 = NameColor（ctor 255）");

        // 重复置位刷新计时：61s 重新置位；91s 再置一次（已带 flag ⇒ 零帧但刷新 tick）。
        rig.world.clock_ms = 61_000;
        assert!(rig.world.set_pk_flag(rig.observer, caster_id).is_some());
        rig.world.clock_ms = 91_000;
        assert!(
            rig.world.set_pk_flag(rig.observer, caster_id).is_none(),
            "已带 flag ⇒ 不再产 RefNameColor"
        );
        // 91 + 59 = 150s：未过期。
        rig.world.clock_ms = 150_000;
        drain_pk_flag_downlink(&mut rig.world, &rig.online, &rig.gates);
        let frames = rig.drain();
        assert_eq!(b3_count(&frames, 911, SM_656), 0, "刷新后 59s 不清");
        assert!(rig.world.entities.get(caster_id).unwrap().pvp_flag);
        // 91 + 61 = 152s：过期。
        rig.world.clock_ms = 152_000;
        drain_pk_flag_downlink(&mut rig.world, &rig.online, &rig.gates);
        let frames = rig.drain();
        assert_eq!(b3_count(&frames, 911, SM_656), 1, "刷新后 61s 清");
        assert_eq!(b3_count(&frames, 912, SM_656), 1);
        assert!(!rig.world.entities.get(caster_id).unwrap().pvp_flag);
    }

    /// **T-78 修复的端到端牙**：注入墙钟量级 `clock_ms` 且**不**手工重置 `pk_check_tick`
    /// （模拟 `MIR2_CLOCK_MS` 注入后的真实首调）⇒ 首调建立 500ms 基线，不得立刻检查。
    ///
    /// 夹具把 `PvpNameColorTick` 拨到 61s 前（已过期）：若节流失效，首调就会清位并广播 656。
    #[test]
    fn p3res_pk_throttle_holds_under_injected_wall_clock() {
        const SM_656: u16 = mir2_protocol::messages::SM_CHANGENAMECOLOR;
        const T0: i64 = 1_700_000_000_000;

        let mut rig = B3Rig::new(18, 2, true);
        rig.world.clock_ms = T0;
        let caster_id = rig.caster;
        assert!(rig.world.set_pk_flag(rig.observer, caster_id).is_some());
        // 已进入过期区间（61s），但节流游标尚未初始化。
        rig.world
            .entities
            .get_mut(caster_id)
            .unwrap()
            .pvp_name_color_tick = T0 - 61_000;

        // 首调 + 500ms 内：零 656、flag 仍在。
        drain_pk_flag_downlink(&mut rig.world, &rig.online, &rig.gates);
        let frames = rig.drain();
        assert_eq!(b3_count(&frames, 911, SM_656), 0, "首调不得检查");
        assert!(rig.world.entities.get(caster_id).unwrap().pvp_flag);
        rig.world.clock_ms = T0 + 500;
        drain_pk_flag_downlink(&mut rig.world, &rig.online, &rig.gates);
        let frames = rig.drain();
        assert_eq!(b3_count(&frames, 911, SM_656), 0, "500ms 内不得检查");
        assert!(rig.world.entities.get(caster_id).unwrap().pvp_flag);

        // 600ms：过期 ⇒ 自己与观察者各恰一条 656，范围外零。
        rig.world.clock_ms = T0 + 600;
        drain_pk_flag_downlink(&mut rig.world, &rig.online, &rig.gates);
        let frames = rig.drain();
        assert_eq!(b3_count(&frames, 911, SM_656), 1, "过期后自己恰一条 656");
        assert_eq!(b3_count(&frames, 912, SM_656), 1, "观察者恰一条 656");
        assert_eq!(b3_count(&frames, 914, SM_656), 0, "范围外不投递");
        assert!(!rig.world.entities.get(caster_id).unwrap().pvp_flag);
    }

    /// **40 F40-A/B/C/D**：无目标回落自己、`IsProperFriend` 门、`R(7)` 门、三个计时器
    /// `!=0 ⇒ 置 1`（不是清 0）、boTrain（B3-40-1/2/3/4）。
    #[test]
    fn spell_p3b3_40_unamyounsul_timers_self_fallback_and_gate() {
        const SM_17: u16 = mir2_protocol::messages::SM_SPELL;
        const SM_53: u16 = mir2_protocol::messages::SM_HEALTHSPELLCHANGED;
        const SM_638: u16 = mir2_protocol::messages::SM_MAGICFIRE;
        const SM_640: u16 = mir2_protocol::messages::SM_MAGIC_LVEXP;

        // F40-A：无目标 ⇒ self；R(7)=6，6-3=3 不 <0 ⇒ 门失败。
        let mut rig = B3Rig::new(40, 2, true);
        let before = rig.world.rng.clone();
        rig.cast(40, (12, 12), 0);
        let frames = rig.drain();
        assert_eq!(b3_ledger(&before, &rig.world.rng, &[7]), vec![(7, 6)]);
        assert_eq!(b3_seq(&frames, 911), vec![SM_53, SM_638]);
        let body = frames
            .iter()
            .find(|(s, b)| *s == 911 && sf_ident(b) == SM_638)
            .unwrap()
            .1
            .clone();
        let cm = mir2_protocol::frame::CommandMessage::from_bytes(&body).unwrap();
        assert_eq!(
            (cm.param, cm.tag),
            (10, 10),
            "self 回落 ⇒ 尾坐标 = 施法者坐标"
        );
        let f = rig.deliver(1000);
        assert_eq!(b3_count(&f, 911, SM_640), 0);

        // F40-B：pre_draw=1 + 计时器 [0]=5,[1]=7 ⇒ 门过、置 1、TRAIN。
        let mut rig = B3Rig::new(40, 2, true);
        {
            let e = rig.world.entities.get_mut(rig.caster).unwrap();
            e.status_time[0] = 5;
            e.status_time[1] = 7;
        }
        let _ = rig.world.rng.random_below(0); // pre_draws=1
        let before = rig.world.rng.clone();
        rig.cast(40, (12, 12), 0);
        let frames = rig.drain();
        assert_eq!(
            b3_ledger(&before, &rig.world.rng, &[7, 3]),
            vec![(7, 2), (3, 0)],
            "F40-B"
        );
        assert_eq!(b3_seq(&frames, 911), vec![SM_53, SM_638]);
        let e = rig.world.entities.get(rig.caster).unwrap();
        assert_eq!(
            (e.status_time[0], e.status_time[1], e.status_time[5]),
            (1, 1, 0)
        );
        let f = rig.deliver(1000);
        assert_eq!(b3_seq(&f, 911), vec![SM_640]);
        assert_eq!(rig.tran_point(), 1);

        // F40-C：计时器全 0 ⇒ 门过但 boTrain=false（B3-40-4）。
        let mut rig = B3Rig::new(40, 2, true);
        let _ = rig.world.rng.random_below(0);
        let before = rig.world.rng.clone();
        rig.cast(40, (12, 12), 0);
        let frames = rig.drain();
        assert_eq!(
            b3_ledger(&before, &rig.world.rng, &[7]),
            vec![(7, 2)],
            "F40-C 门过但无 TRAIN"
        );
        assert_eq!(b3_seq(&frames, 911), vec![SM_53, SM_638]);
        let f = rig.deliver(1000);
        assert_eq!(b3_count(&f, 911, SM_640), 0);

        // F40-D：目标为怪 ⇒ IsProperFriend false ⇒ 零抽（B3-40-2）。
        let mut rig = B3Rig::new(40, 2, true);
        let m = rig.add_monster("m", 11, 10, 80, false, 30, 0, 0, None, None);
        let before = rig.world.rng.clone();
        rig.cast(40, (11, 10), m);
        let frames = rig.drain();
        assert_eq!(
            b3_ledger(&before, &rig.world.rng, &[]),
            Vec::<(i32, i32)>::new()
        );
        assert_eq!(b3_seq(&frames, 911), vec![SM_53, SM_638]);
        assert_eq!(b3_seq(&frames, 912), vec![SM_17, SM_638]);

        // F40-B 的 `Level` 方向（B3-40-3）：Level=1、seed 下 R(7)=6 ⇒ 6-2=4 仍不过；
        // 用 Level=6 时 6-7=-1 ⇒ 必过（同一抽），证明门读的是 Level。
        let mut rig = B3Rig::new(40, 6, true);
        rig.world.entities.get_mut(rig.caster).unwrap().status_time[0] = 5;
        let before = rig.world.rng.clone();
        rig.cast(40, (12, 12), 0);
        let frames = rig.drain();
        // `Level=6` ⇒ `6 - 7 = -1 < 0` 门过（同一抽）；但 `Level < 3` 不成立 ⇒ 无 TRAIN 抽。
        // 门过的可观测量 = 计时器被置 1（B3-40-3）。
        assert_eq!(
            b3_ledger(&before, &rig.world.rng, &[7]),
            vec![(7, 6)],
            "Level=6 ⇒ R(7) 过门"
        );
        assert_eq!(
            rig.world.entities.get(rig.caster).unwrap().status_time[0],
            1,
            "门过 ⇒ 计时器置 1（不是清 0）"
        );
        assert_eq!(b3_seq(&frames, 911), vec![SM_53, SM_638]);
        let f = rig.deliver(1000);
        assert_eq!(b3_count(&f, 911, SM_640), 0, "Level=6 ⇒ 不训练");
    }

    /// **640 升级分支**：`PlayObject.CheckMagicLevelUp`（`:5210-5224`）升级 ⇒
    /// `UpdateDelayMsg(..., 800)` 并**先删同 `wIdent+nParam1` 的待投递 640**
    /// （`BaseObject.Message.cs:257-278`）；未升级 ⇒ `SendSelfDelayMsg(..., 1000)`
    /// （`MagicManager.cs:666`）。
    ///
    /// 牙：① 一律 1000ms ⇒ 升级支延迟断言红；② 无去重 ⇒ 投递出两条 640。
    #[test]
    fn spell_p3b3_640_levelup_800ms_and_dedupe() {
        const SM_640: u16 = mir2_protocol::messages::SM_MAGIC_LVEXP;
        let mut rig = B3Rig::new(16, 2, true);
        let _m1 = rig.add_monster("m1", 11, 11, 50, true, 30, 0, 0, None, None);
        let _m2 = rig.add_monster("m2", 12, 11, 50, true, 30, 0, 0, None, None);
        let _m3 = rig.add_monster("m3", 12, 12, 50, true, 30, 0, 0, None, None);

        // 第一次：TranPoint=0 ⇒ 不升级 ⇒ 1000ms 待投递。
        rig.cast(16, (12, 12), 0);
        let _ = rig.drain();
        let pending: Vec<_> = rig
            .world
            .self_delay_msgs
            .iter()
            .filter(|m| m.ident == mir2_world::slave::RM_MAGIC_LVEXP)
            .collect();
        assert_eq!(pending.len(), 1, "未升级 ⇒ 恰一条 1000ms 640");
        assert_eq!(pending[0].deliver_at_ms, rig.world.clock_ms + 1000);
        assert_eq!(pending[0].n_param2, 2, "未升级 Level=2");

        // 第二次：把 TranPoint 推到 499（MaxTrain[2]=500）⇒ 本抽升级到 3。
        rig.saves
            .get_mut("caster")
            .unwrap()
            .record
            .data
            .magic
            .as_mut()
            .unwrap()[0]
            .as_mut()
            .unwrap()
            .tran_point = 499;
        rig.cast(16, (12, 12), 0);
        let _ = rig.drain();
        let pending: Vec<_> = rig
            .world
            .self_delay_msgs
            .iter()
            .filter(|m| m.ident == mir2_world::slave::RM_MAGIC_LVEXP)
            .collect();
        assert_eq!(pending.len(), 1, "升级 ⇒ UpdateDelayMsg 先删旧 640");
        assert_eq!(pending[0].deliver_at_ms, rig.world.clock_ms + 800);
        assert_eq!(pending[0].n_param2, 3, "升级后 Level=3");
        assert_eq!(rig.tran_level(), 3);
        let f = rig.deliver(800);
        assert_eq!(b3_count(&f, 911, SM_640), 1, "800ms 投递恰一条 640");
    }

    /// **28 升级 ⇒ `CheckSeeHealGauge` 接线**：`PlayObject.cs:5231-5240` 在升级后置
    /// `AbilSeeHealGauge = true`（`MagicId == 28 && Level >= 2`）；宿主写
    /// `SessionGround.abil_see_heal_gauge`，否则后续 2/29 的 1103 帧会漏。
    ///
    /// 牙：漏接线 ⇒ 会话态仍 false（本断言红）。
    #[test]
    fn spell_p3b3_28_levelup_sets_see_heal_gauge() {
        const SM_640: u16 = mir2_protocol::messages::SM_MAGIC_LVEXP;
        let mut rig = B3Rig::new(28, 2, true);
        let target = rig.add_monster("t", 12, 10, 80, false, 30, 0, 0, None, None);
        assert!(!rig.ground_sessions["caster"].abil_see_heal_gauge);
        rig.saves
            .get_mut("caster")
            .unwrap()
            .record
            .data
            .magic
            .as_mut()
            .unwrap()[0]
            .as_mut()
            .unwrap()
            .tran_point = 499;
        rig.cast(28, (12, 10), target);
        let _ = rig.drain();
        assert_eq!(rig.tran_level(), 3, "499 + R(3)+1 ⇒ 升级");
        assert!(
            rig.ground_sessions["caster"].abil_see_heal_gauge,
            "Level>=2 ⇒ AbilSeeHealGauge 置真"
        );
        let pending = rig
            .world
            .self_delay_msgs
            .iter()
            .find(|m| m.ident == mir2_world::slave::RM_MAGIC_LVEXP)
            .expect("升级支 800ms 640");
        assert_eq!(pending.deliver_at_ms, rig.world.clock_ms + 800);
        let f = rig.deliver(800);
        assert_eq!(b3_count(&f, 911, SM_640), 1);
    }

    /// **F53-A**：施法者 `ShowHp=true` 时，53 有「自投递 + 广播」两支：
    /// SELF 两条 53、OBS 一条。改坏（漏 `if (ShowHp) SendRefMsg`）⇒ OBS 无 53、SELF 仅一条。
    #[test]
    fn spell_p3b3_53_showhp_broadcast_branch() {
        const SM_53: u16 = mir2_protocol::messages::SM_HEALTHSPELLCHANGED;
        const SM_17: u16 = mir2_protocol::messages::SM_SPELL;
        const SM_638: u16 = mir2_protocol::messages::SM_MAGICFIRE;
        const SM_642: u16 = mir2_protocol::messages::SM_DURACHANGE;

        let mut rig = B3Rig::new(16, 2, true);
        rig.ground_sessions.get_mut("caster").unwrap().show_hp = true;
        let _m = rig.add_monster("m", 11, 11, 50, true, 30, 0, 0, None, None);
        rig.cast(16, (12, 12), 0);
        let frames = rig.drain();
        assert_eq!(
            b3_count(&frames, 911, SM_53),
            2,
            "SELF：自投递 + ShowHp 广播"
        );
        assert_eq!(b3_count(&frames, 912, SM_53), 1, "OBS：仅 ShowHp 广播");
        assert_eq!(b3_count(&frames, 914, SM_53), 0, "FAR 不在 ±12");
        assert_eq!(b3_seq(&frames, 911), vec![SM_53, SM_53, SM_638, SM_642]);
        assert_eq!(b3_seq(&frames, 912), vec![SM_53, SM_17, SM_638]);
    }

    impl B3Rig {
        fn tran_point(&self) -> i32 {
            self.saves["caster"].record.data.magic.as_ref().unwrap()[0]
                .as_ref()
                .unwrap()
                .tran_point
        }

        fn tran_level(&self) -> u8 {
            self.saves["caster"].record.data.magic.as_ref().unwrap()[0]
                .as_ref()
                .unwrap()
                .level
        }
    }
    // ======================================================================
    // 卡 P3-B4（6/48/50/42）：群体列表 / 毒族四魔号
    // ======================================================================
    //
    // 全部走**生产入口** `handle_spell_cmd`（default 支 ∧ 非战士 ∧ 距离门 ⇒ `SM_SPELL(17)`）；
    // 取数断言 = 按合同 §4.1 的 max 序回放并**逐抽比较 `(max,result)`**，回放末态必须与生产
    // `world.rng` 逐字节相同（多抽/少抽/换序都红）。投递 tick 承接同一流（不重新播种）。
    //
    // 牙（每魔号 ≥2，共 ≥8；对应合同 §3 的「改坏必红」）：
    // - 6：B4-6-1（骰门前置）、B4-6-2（`<= 6` 写成 `< 6`）、B4-6-3（`boSpellFail` 只在骰门过时清）、
    //      B4-6-4（删除支也发 642）；
    // - 48：B4-48-1（按首行取模板，不看显式行 ⇒ nPower/MP 红）、B4-48-2（护身符只消耗一次）、
    //      B4-48-3（枚举序）、B4-48-4（非 proper 也 SetTargetCreat）；
    // - 50：B4-50-1（漏 case 级 4 抽）、B4-50-2（成功臂漏 MSD）、B4-50-3（`R(nLevel)` 位置）、
    //      B4-50-4（第一条 RM_DELAYMAGIC 后移）、B4-50-5（`nPower/3`）；
    // - 42：B4-42-1（不置 `boSpellFire=false`）、B4-42-2（null 目标不抛 NPE）、
    //      B4-42-3（helper 638 条件化）、B4-42-4（中心目标也发 716）、B4-42-5（不死 ×1.5）。

    const B4_SEED: i32 = 20261017;

    /// 合同 §1.2 的部署行。`variant`：6、48a（气功波 Idx=48）、48b（群体施毒术 Idx=38）、
    /// 50、42。
    fn b4_magic_info(id: u16, variant: &str) -> mir2_data::MagicInfo {
        let (
            effect,
            effect_type,
            spell,
            power,
            max_power,
            def_spell,
            def_power,
            def_max_power,
            train_level,
        ) = match (id, variant) {
            (6, _) => (
                4u8,
                2u8,
                4u16,
                0u16,
                0u16,
                0u8,
                0u8,
                0u8,
                [14u8, 17, 20, 20],
            ),
            (48, "48a") => (36, 7, 8, 1, 1, 0, 0, 0, [36, 39, 41, 41]),
            (48, _) => (27, 2, 12, 10, 10, 30, 4, 4, [48, 50, 52, 52]),
            (50, _) => (35, 4, 8, 1, 1, 4, 0, 0, [38, 41, 44, 44]),
            (42, _) => (0, 0, 0, 0, 0, 3, 0, 0, [38, 41, 44, 44]),
            _ => unreachable!("B4 四魔号"),
        };
        mir2_data::MagicInfo {
            magic_id: id,
            effect,
            effect_type,
            spell,
            power,
            max_power,
            def_spell,
            def_power,
            def_max_power,
            train_lv: 3,
            train_level,
            max_train: [200, 300, 500, 500],
            ..mir2_data::MagicInfo::default()
        }
    }

    struct B4Rig {
        world: mir2_world::World,
        caster: i32,
        far: i32,
        online: OnlineRegistry,
        saves: std::collections::HashMap<String, SavedHuman>,
        ground_sessions: std::collections::HashMap<String, SessionGround>,
        magic_table: magics::MagicTable,
        displays: downlink::DisplayTable,
        gates: std::collections::HashMap<u8, mpsc::UnboundedSender<SimToGate>>,
        rx: mpsc::UnboundedReceiver<SimToGate>,
        /// 生产接线对象：`drain_b4_with_enter_cfg` 从它取 `[Setup] RedMsg*` 与
        /// `[String] YouPoisoned`（现网 `String.conf:31` = `您中毒了!!!`，GBK
        /// `c4fad6d0b6bec1cb212121`）。B4 单测因此与 `sim_loop` 走**同一条** `EnterConfig` 路径。
        enter_cfg: EnterConfig,
    }

    impl B4Rig {
        fn new(
            magic: mir2_data::MagicInfo,
            magic_level: u8,
            with_amulet_dura: Option<u16>,
        ) -> Self {
            use std::collections::HashMap;
            let magic_id = magic.magic_id;
            let mut world = mir2_world::World::new(64, 64);
            let caster = world.add_entity(new_player_entity("caster".to_string(), 10, 10));
            let observer = world.add_entity(new_player_entity("obs".to_string(), 18, 10));
            let far = world.add_entity(new_player_entity("far".to_string(), 40, 40));
            {
                let e = world.entities.get_mut(caster).unwrap();
                e.level = 60;
                e.attack_mode = 0; // HAM_ALL
                e.luck = 0;
                e.power_rate = 100;
                e.bo_power_item = false;
                e.hp = 100;
                e.max_hp = 100;
            }
            world.tick();
            let mut displays = downlink::DisplayTable::new();
            displays.set(
                caster,
                downlink::ActorDisplay::new(4, 0, 111, 0, 0, 255, b"caster".to_vec()),
            );
            displays.set(
                observer,
                downlink::ActorDisplay::new(4, 0, 112, 0, 0, 255, b"obs".to_vec()),
            );
            displays.set(
                far,
                downlink::ActorDisplay::new(4, 0, 113, 0, 0, 255, b"far".to_vec()),
            );
            let mut online: OnlineRegistry = Vec::new();
            for (i, (name, socket, actor)) in [
                ("caster", 911, caster),
                ("obs", 912, observer),
                ("far", 914, far),
            ]
            .into_iter()
            .enumerate()
            {
                online_set(
                    &mut online,
                    OnlineEntry {
                        account: format!("u{i}"),
                        chr_name: name.into(),
                        session_id: 10 + i32::try_from(i).unwrap_or(0),
                        gate_idx: 0,
                        socket,
                        actor_id: actor,
                    },
                );
            }
            let (tx0, rx) = mpsc::unbounded_channel::<SimToGate>();
            let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
            gates.insert(0, tx0);
            let mut record = stage6_record();
            record.data.magic = Some(vec![Some(record::MagicRcd {
                mag_idx: magic_id,
                level: magic_level,
                magic_key: u16::from(b'm'),
                tran_point: 0,
            })]);
            let mut saves: HashMap<String, SavedHuman> = HashMap::new();
            saves.insert(
                "caster".into(),
                SavedHuman {
                    account: "u0".into(),
                    record,
                    enter_map: "0".into(),
                },
            );
            let mut ground_sessions: HashMap<String, SessionGround> = HashMap::new();
            let mut sg = spell_session_ground(caster);
            sg.state.wabil.level = 60;
            sg.state.wabil.hp = 100;
            sg.state.wabil.max_hp = 100;
            sg.state.wabil.mp = 1000;
            sg.state.wabil.max_mp = 1000;
            sg.state.wabil.sc = 0x0A05;
            sg.state.wabil.mc = 0x0A05;
            if let Some(dura) = with_amulet_dura {
                sg.use_items[game_svr::ability::SLOT_ARMRING_L] = Some(game_svr::bag::BagItem {
                    make_index: 1,
                    index: 1,
                    dura,
                    dura_max: 1000,
                    desc: [0; 14],
                });
            }
            ground_sessions.insert("caster".into(), sg);
            let magic_table = magics::MagicTable::new(vec![magic]);
            // 现网 String.conf 字节（GBK）：`YouPoisoned=您中毒了!!!`。构造生产接线对象
            // `EnterConfig`，`deliver` 再经 `drain_b4_with_enter_cfg` 消费它。
            let enter_cfg = EnterConfig::for_test(strings::parse(
                b"[String]\nYouPoisoned=\xc4\xfa\xd6\xd0\xb6\xbe\xc1\xcb!!!\n",
            ));
            let _ = observer;
            Self {
                world,
                caster,
                far,
                online,
                saves,
                ground_sessions,
                magic_table,
                displays,
                gates,
                rx,
                enter_cfg,
            }
        }

        /// 所有 spawn/tick 完成后再播种（合同 §3.0）。
        fn seed(&mut self, pre_draws: usize) {
            self.world.rng = mir2_shared::rng::RandomNumber::with_seed(B4_SEED);
            for _ in 0..pre_draws {
                let _ = self.world.rng.random_below(0);
            }
        }

        fn cast(&mut self, magic_id: u16, click: (i32, i32), target_actor_id: i32) {
            let mut catalog = game_svr::ability::StdItemCatalog::new();
            catalog.insert(
                1,
                mir2_data::StdItem {
                    name: "护身符".into(),
                    std_mode: 25,
                    shape: 1,
                    ..mir2_data::StdItem::default()
                },
            );
            self.cast_with_catalog(magic_id, click, target_actor_id, &catalog);
        }

        fn cast_with_catalog(
            &mut self,
            magic_id: u16,
            click: (i32, i32),
            target_actor_id: i32,
            catalog: &game_svr::ability::StdItemCatalog,
        ) {
            let pet_cfg = mir2_data::pet_slave::PetSlaveConfig::default();
            let table = game_svr::mongen::MonsterTable::new(Vec::new());
            let registry = mir2_envir::MapRegistry::from_entries(
                mir2_envir::MapLoader::new(".", "map", "envir"),
                Vec::new(),
            );
            handle_spell_cmd(
                game_svr::feature::make_long(
                    u16::try_from(click.0).unwrap_or(0),
                    u16::try_from(click.1).unwrap_or(0),
                ),
                magic_id,
                u16::try_from(target_actor_id).unwrap_or(0),
                0,
                "caster",
                911,
                &self.online,
                &mut self.world,
                &mut self.saves,
                &mut self.ground_sessions,
                catalog,
                &self.magic_table,
                &pet_cfg,
                8,
                Some(&registry),
                &table,
                &mut self.displays,
                &self.gates,
                1,
                1,
                2,
            );
        }

        fn drain(&mut self) -> Vec<SfFrame> {
            let mut frames = Vec::new();
            while let Ok(m) = self.rx.try_recv() {
                if let SimToGate::SendFrame { socket, body } = m {
                    frames.push((socket, body));
                }
            }
            frames
        }

        /// 推进时钟并投递到点的自身延时消息（B4 毒/延迟魔法 + B3 训练帧）；返回本批出帧。
        fn deliver(&mut self, advance_ms: i64) -> Vec<SfFrame> {
            self.world.clock_ms += advance_ms;
            let outs = self.world.deliver_self_delay_msgs();
            let rec = mir2_world::TickRecord {
                slave_self_deliveries: outs,
                ..Default::default()
            };
            drain_b4_with_enter_cfg(
                &rec,
                &mut self.world,
                &self.online,
                &mut self.displays,
                &mut self.ground_sessions,
                &self.gates,
                &self.enter_cfg,
            );
            drain_b3_self_deliveries(
                &rec,
                &self.world,
                &self.online,
                &mut self.ground_sessions,
                &self.gates,
            );
            self.drain()
        }

        #[allow(clippy::too_many_arguments)]
        fn add_monster(
            &mut self,
            name: &str,
            x: i32,
            y: i32,
            race: u8,
            level: u8,
            life_attrib: u8,
            anti_magic: u16,
            mac: u16,
        ) -> i32 {
            let mut e = mir2_world::Entity::new(0, name.to_string(), x, y);
            e.race = race;
            e.level = level;
            e.hp = 100;
            e.max_hp = 100;
            e.life_attrib = life_attrib;
            e.anti_magic = anti_magic;
            e.mac = mac;
            e.ai.animal = false;
            e.ai.target_creature = None;
            e.master = None;
            e.admin_mode = false;
            e.stone_mode = false;
            let id = self.world.add_entity(e);
            self.world.tick();
            self.displays.set(
                id,
                downlink::ActorDisplay::new(4, 0, 220, 0, 0, 255, name.as_bytes().to_vec()),
            );
            id
        }

        fn add_player(&mut self, name: &str, x: i32, y: i32, socket: i32) -> i32 {
            let mut e = new_player_entity(name.to_string(), x, y);
            e.level = 10;
            e.anti_magic = 0;
            e.mac = 0;
            let id = self.world.add_entity(e);
            self.world.tick();
            self.displays.set(
                id,
                downlink::ActorDisplay::new(4, 0, 230, 0, 0, 255, name.as_bytes().to_vec()),
            );
            online_set(
                &mut self.online,
                OnlineEntry {
                    account: name.into(),
                    chr_name: name.into(),
                    session_id: socket,
                    gate_idx: 0,
                    socket,
                    actor_id: id,
                },
            );
            id
        }

        fn mp(&self) -> u16 {
            self.ground_sessions["caster"].state.wabil.mp
        }

        fn tran_point(&self) -> i32 {
            self.saves["caster"].record.data.magic.as_ref().unwrap()[0]
                .as_ref()
                .unwrap()
                .tran_point
        }

        fn tran_level(&self) -> u8 {
            self.saves["caster"].record.data.magic.as_ref().unwrap()[0]
                .as_ref()
                .unwrap()
                .level
        }

        fn target_creature(&self) -> Option<i32> {
            self.world
                .entities
                .get(self.caster)
                .unwrap()
                .ai
                .target_creature
        }

        fn delay_msgs(&self, ident: u16) -> Vec<&mir2_world::slave::SelfDelayMsg> {
            self.world
                .self_delay_msgs
                .iter()
                .filter(|m| m.ident == ident)
                .collect()
        }
    }

    /// 按期望 max 序回放 `before`，逐抽返回 `(max,result)`，并要求末态 == `after`。
    fn b4_ledger(
        before: &mir2_shared::rng::RandomNumber,
        after: &mir2_shared::rng::RandomNumber,
        maxes: &[i32],
    ) -> Vec<(i32, i32)> {
        let mut probe = before.clone();
        let mut out = Vec::with_capacity(maxes.len());
        for &m in maxes {
            out.push((m, probe.random_below(m)));
        }
        assert_eq!(
            format!("{probe:?}"),
            format!("{after:?}"),
            "RNG 末态与期望 max 序不一致（多抽/少抽/换序）"
        );
        out
    }

    fn b4_seq(frames: &[SfFrame], socket: i32) -> Vec<u16> {
        frames
            .iter()
            .filter(|(s, _)| *s == socket)
            .map(|(_, b)| sf_ident(b))
            .collect()
    }

    fn b4_count(frames: &[SfFrame], socket: i32, ident: u16) -> usize {
        frames
            .iter()
            .filter(|(s, b)| *s == socket && sf_ident(b) == ident)
            .count()
    }

    fn b4_all(frames: &[SfFrame], socket: i32, ident: u16) -> Vec<Vec<u8>> {
        frames
            .iter()
            .filter(|(s, b)| *s == socket && sf_ident(b) == ident)
            .map(|(_, b)| b.clone())
            .collect()
    }

    fn b4_cmd(body: &[u8]) -> mir2_protocol::frame::CommandMessage {
        mir2_protocol::frame::CommandMessage::from_bytes(body).unwrap()
    }

    /// **F6-A/B/C/E/G**：施毒术。逐抽、帧序、202 先于 53、失败支恰一条 639、投毒投递。
    #[test]
    fn spell_p3b4_6_poison_draws_frames_and_fail_branches() {
        const SM_17: u16 = mir2_protocol::messages::SM_SPELL;
        const SM_53: u16 = mir2_protocol::messages::SM_HEALTHSPELLCHANGED;
        const SM_202: u16 = mir2_protocol::messages::SM_DELITEM;
        const SM_638: u16 = mir2_protocol::messages::SM_MAGICFIRE;
        const SM_639: u16 = mir2_protocol::messages::SM_MAGICFIRE_FAIL;
        const SM_640: u16 = mir2_protocol::messages::SM_MAGIC_LVEXP;
        const SM_642: u16 = mir2_protocol::messages::SM_DURACHANGE;
        const SM_657: u16 = mir2_protocol::messages::SM_CHARSTATUSCHANGED;

        // ---- F6-A：monster 目标，anti_poison=0，dura=600 ----
        let mut rig = B4Rig::new(b4_magic_info(6, "6"), 2, Some(600));
        let m = rig.add_monster("m", 11, 10, 80, 10, 0, 0, 0);
        rig.seed(0);
        let before = rig.world.rng.clone();
        rig.cast(6, (11, 10), m);
        let frames = rig.drain();
        let got = b4_ledger(&before, &rig.world.rng, &[7, 0, 6, 3]);
        assert_eq!(
            got,
            vec![(7, 6), (0, 0), (6, 1), (3, 1)],
            "F6-A 逐抽（骰门 → GP13 → RP → TRAIN）"
        );
        assert_eq!(
            b4_seq(&frames, 911),
            vec![SM_53, SM_638, SM_642],
            "SELF 立即序"
        );
        assert_eq!(b4_seq(&frames, 912), vec![SM_17, SM_638], "OBS 立即序");
        assert_eq!(b4_count(&frames, rig.far, SM_17), 0, "FAR 在 ±12 外");
        let fire = sf_first(&frames, 912, SM_638);
        assert_eq!(sf_magicfire_target_id(fire), m, "638 ActorId = 目标");
        let dur = b4_cmd(sf_first(&frames, 911, SM_642));
        assert_eq!(
            (dur.param, dur.tag),
            (5, 1000),
            "642 slot=ArmRingl/dura_max"
        );
        assert_eq!(
            rig.delay_msgs(mir2_world::slave::RM_POISON).len(),
            1,
            "恰一条 RM_POISON"
        );
        let p = rig.delay_msgs(mir2_world::slave::RM_POISON)[0];
        assert_eq!(
            (p.actor_id, p.w_param, p.n_param1, p.n_param2, p.n_param3),
            (m, 0, 45, rig.caster, 3),
            "RM_POISON(type=DECHEALTH,time=45,caster,point=3)"
        );
        assert_eq!(rig.target_creature(), Some(m), "SetTargetCreat");
        assert_eq!(rig.tran_point(), 2, "TRAIN=1 ⇒ TranPoint=2");
        assert_eq!(rig.tran_level(), 2, "max_train=500 ⇒ 不升级");
        // 投递：657（毒）+ 640（训练帧）。
        let f = rig.deliver(1000);
        assert_eq!(b4_count(&f, 911, SM_657), 1, "SELF 收 1×657");
        assert_eq!(b4_count(&f, 912, SM_657), 1, "OBS 收 1×657");
        assert_eq!(b4_count(&f, 911, SM_640), 1, "640 仅自己");
        assert_eq!(b4_count(&f, 912, SM_640), 0);
        let lv = b4_cmd(sf_first(&f, 911, SM_640));
        assert_eq!(
            (lv.recog, lv.param, lv.tag),
            (6, 2, 2),
            "640 (MagicId=6, Level=2, TranPoint=2)"
        );
        assert!(
            rig.world.entities.get(m).unwrap().char_status != 0,
            "毒落 CharStatus"
        );

        // ---- F6-B：anti_poison=100 ⇒ 骰门失败（仍有 638、无 642/毒/640）----
        let mut rig = B4Rig::new(b4_magic_info(6, "6"), 2, Some(600));
        let m = rig.add_monster("m", 11, 10, 80, 10, 0, 0, 0);
        rig.world.set_attack_poison(
            m,
            mir2_world::combat::AttackPoisonState {
                anti_poison: 100,
                ..Default::default()
            },
        );
        rig.seed(0);
        let before = rig.world.rng.clone();
        rig.cast(6, (11, 10), m);
        let frames = rig.drain();
        assert_eq!(
            b4_ledger(&before, &rig.world.rng, &[107]),
            vec![(107, 96)],
            "F6-B 只抽骰门"
        );
        assert_eq!(b4_seq(&frames, 911), vec![SM_53, SM_638, SM_642]);
        assert!(rig.delay_msgs(mir2_world::slave::RM_POISON).is_empty());
        let f = rig.deliver(1000);
        assert_eq!(b4_count(&f, 911, SM_657), 0);
        assert_eq!(b4_count(&f, 911, SM_640), 0);
        assert_eq!(rig.tran_point(), 0, "骰门失败 ⇒ 不训练");

        // ---- F6-C：无护身符 ⇒ 零抽 + 恰一条 639 ----
        let mut rig = B4Rig::new(b4_magic_info(6, "6"), 2, None);
        let m = rig.add_monster("m", 11, 10, 80, 10, 0, 0, 0);
        rig.seed(0);
        let before = rig.world.rng.clone();
        rig.cast(6, (11, 10), m);
        let frames = rig.drain();
        assert_eq!(
            b4_ledger(&before, &rig.world.rng, &[]),
            Vec::<(i32, i32)>::new()
        );
        assert_eq!(b4_seq(&frames, 911), vec![SM_53, SM_639]);
        assert_eq!(b4_seq(&frames, 912), vec![SM_17, SM_639]);
        assert_eq!(
            b4_count(&frames, 911, SM_642) + b4_count(&frames, 911, SM_202),
            0
        );

        // ---- F6-E：target_actor_id=0 ⇒ 零抽 + 639 ----
        let mut rig = B4Rig::new(b4_magic_info(6, "6"), 2, Some(600));
        rig.seed(0);
        let before = rig.world.rng.clone();
        rig.cast(6, (11, 10), 0);
        let frames = rig.drain();
        assert_eq!(
            b4_ledger(&before, &rig.world.rng, &[]),
            Vec::<(i32, i32)>::new()
        );
        assert_eq!(b4_seq(&frames, 911), vec![SM_53, SM_639]);
        assert_eq!(b4_count(&frames, 911, SM_638), 0);
        assert_eq!(
            rig.ground_sessions["caster"].use_items[5]
                .as_ref()
                .unwrap()
                .dura,
            600,
            "未消耗护身符"
        );

        // ---- F6-G：dura=100 ⇒ 202 直发、先于 53；无 642；毒/训练照发 ----
        let mut rig = B4Rig::new(b4_magic_info(6, "6"), 2, Some(100));
        let m = rig.add_monster("m", 11, 10, 80, 10, 0, 0, 0);
        rig.seed(0);
        let before = rig.world.rng.clone();
        rig.cast(6, (11, 10), m);
        let frames = rig.drain();
        assert_eq!(
            b4_ledger(&before, &rig.world.rng, &[7, 0, 6, 3]),
            vec![(7, 6), (0, 0), (6, 1), (3, 1)],
            "F6-G 骰门照抽"
        );
        assert_eq!(
            b4_seq(&frames, 911),
            vec![SM_202, SM_53, SM_638],
            "SELF：202 直发先于 53；删除支无 642"
        );
        assert_eq!(b4_count(&frames, 911, SM_642), 0);
        assert_eq!(rig.delay_msgs(mir2_world::slave::RM_POISON).len(), 1);
        let f = rig.deliver(1000);
        assert_eq!(b4_count(&f, 911, SM_657), 1);
        assert_eq!(b4_count(&f, 911, SM_640), 1);

        // ---- F6-H：`attack_mode=HAM_GROUP` + 同组玩家目标 ⇒ `IsProperTarget` 剔除 ----
        // `PlayObject.Attack.cs:686-697`：`HAM_GROUP` 下若 `target.Race == Play` 且
        // `IsGroupMember(target)` ⇒ 返回 false。**真实布局**：`JoinGroup` 只给加入者写
        // `group_owner`（`party.rs:322`），成员表只挂在**团长 Entity** 上
        // （`party.rs:542-544/624`）⇒ 施法者是**非团长**时自身 `group_members` 为空。
        // 若误读施法者自己的表（空表），同组玩家会被误判为合法：多抽（骰门/GP13/RP/TRAIN）、
        // 白扣护身符、多发 638/642 而非恰 1 条 639。
        let mut rig = B4Rig::new(b4_magic_info(6, "6"), 2, Some(600));
        let ally = rig.add_player("ally", 11, 10, 913);
        // 团长：独立实体，成员表含团长自己、施法者与目标玩家。
        let leader = rig.add_player("leader", 12, 10, 915);
        let caster_id = rig.caster;
        {
            let c = rig.world.entities.get_mut(caster_id).unwrap();
            c.attack_mode = mir2_world::combat::ATTACK_MODE_HAM_GROUP;
            c.group_owner = leader;
            c.group_members.clear();
            assert!(c.group_members.is_empty(), "非团长自身表必须为空");
        }
        {
            let l = rig.world.entities.get_mut(leader).unwrap();
            l.group_members = vec![leader, caster_id, ally];
        }
        rig.seed(0);
        let before = rig.world.rng.clone();
        rig.cast(6, (11, 10), ally);
        let frames = rig.drain();
        assert_eq!(
            b4_ledger(&before, &rig.world.rng, &[]),
            Vec::<(i32, i32)>::new(),
            "同组目标 ⇒ 零抽（不是骰门失败，而是 IsProperTarget 直接拒绝）"
        );
        assert_eq!(
            b4_count(&frames, 911, SM_639),
            1,
            "同组目标 ⇒ 恰一条 639（其它失败帧不得出现）"
        );
        assert_eq!(b4_seq(&frames, 911), vec![SM_53, SM_639]);
        assert_eq!(b4_count(&frames, 911, SM_638), 0);
        assert_eq!(
            b4_count(&frames, 911, SM_642) + b4_count(&frames, 911, SM_202),
            0,
            "不消耗护身符 ⇒ 无 642/202"
        );
        assert_eq!(
            rig.ground_sessions["caster"].use_items[5]
                .as_ref()
                .unwrap()
                .dura,
            600,
            "护身符耐久保持 600"
        );
        assert!(rig.delay_msgs(mir2_world::slave::RM_POISON).is_empty());
        let f = rig.deliver(1000);
        assert_eq!(b4_count(&f, 911, SM_657), 0);
        assert_eq!(b4_count(&f, 911, SM_640), 0);
        assert_eq!(rig.tran_point(), 0, "同组目标 ⇒ 不训练");
    }

    /// **F6-W（接线级）**：`SysMsg(YouPoisoned)` 的文本必须来自生产接线
    /// `EnterConfig.string_conf`（`sim_loop` → `drain_b4_with_enter_cfg`），而不是测试自备文本。
    /// 构造含部署值「您中毒了!!!」的 `EnterConfig` ⇒ 施法 → 100 帧体字节 `c4fad6d0b6bec1cb212121`。
    /// 牙：删掉 `drain_b4_with_enter_cfg` 的 `EnterConfig` 参数（或改回 `MessageSettings`
    /// 源码默认「中毒了!!!」）⇒ 本用例不编译/体字节不符 ⇒ 红。
    #[test]
    fn you_poisoned_wire_text_comes_from_enter_config() {
        const SM_100: u16 = mir2_protocol::messages::SM_SYSMESSAGE;

        let mut rig = B4Rig::new(b4_magic_info(6, "6"), 2, Some(600));
        // 玩家目标 ⇒ `RM_POISON` 投递走 `p.is_player` 的 `SysMsg(YouPoisoned)` 支。
        let victim = rig.add_player("victim", 11, 10, 913);
        rig.seed(0);
        rig.cast(6, (11, 10), victim);

        // 生产接线对象：部署 `String.conf:31` 的同值（GBK）经 `strings::parse` 读入。
        let enter_cfg = EnterConfig::for_test(strings::parse(
            b"[String]\nYouPoisoned=\xc4\xfa\xd6\xd0\xb6\xbe\xc1\xcb!!!\n",
        ));

        // 投递 1000ms：`RM_POISON` 到点 ⇒ 657/100/656，走与 `sim_loop` 相同的接线函数。
        rig.world.clock_ms += 1000;
        let outs = rig.world.deliver_self_delay_msgs();
        let rec = mir2_world::TickRecord {
            slave_self_deliveries: outs,
            ..Default::default()
        };
        drain_b4_with_enter_cfg(
            &rec,
            &mut rig.world,
            &rig.online,
            &mut rig.displays,
            &mut rig.ground_sessions,
            &rig.gates,
            &enter_cfg,
        );
        let frames = rig.drain();
        let msgs = b4_all(&frames, 913, SM_100);
        assert_eq!(msgs.len(), 1, "玩家目标收恰 1 条 100");
        assert_eq!(
            mir2_protocol::edcode::decode(&msgs[0][12..]),
            b"\xc4\xfa\xd6\xd0\xb6\xbe\xc1\xcb!!!",
            "YouPoisoned 体字节必须来自 EnterConfig.string_conf（部署值「您中毒了!!!」）"
        );
    }

    /// **F48-A/B/C/D**：群体施毒术。显式行（Idx=48 vs 38）只改基数与 MP；每目标一次护身符；
    /// 枚举序；非 proper 零抽。
    #[test]
    fn spell_p3b4_48_group_poison_rows_per_target_amulet_and_order() {
        const SM_17: u16 = mir2_protocol::messages::SM_SPELL;
        const SM_53: u16 = mir2_protocol::messages::SM_HEALTHSPELLCHANGED;
        const SM_202: u16 = mir2_protocol::messages::SM_DELITEM;
        const SM_638: u16 = mir2_protocol::messages::SM_MAGICFIRE;
        const SM_640: u16 = mir2_protocol::messages::SM_MAGIC_LVEXP;
        const SM_642: u16 = mir2_protocol::messages::SM_DURACHANGE;
        const SM_657: u16 = mir2_protocol::messages::SM_CHARSTATUSCHANGED;

        let maxes = [7, 0, 6, 7, 0, 6, 7, 0, 6, 3];

        // ---- F48-A：行 Idx=48（气功波）----
        let mut rig = B4Rig::new(b4_magic_info(48, "48a"), 2, Some(600));
        let m1 = rig.add_monster("m1", 11, 11, 80, 10, 0, 0, 0);
        let m2 = rig.add_monster("m2", 12, 11, 80, 10, 0, 0, 0);
        let m3 = rig.add_monster("m3", 12, 12, 80, 10, 0, 0, 0);
        rig.seed(0);
        let before = rig.world.rng.clone();
        rig.cast(48, (11, 11), m1);
        let frames = rig.drain();
        assert_eq!(
            b4_ledger(&before, &rig.world.rng, &maxes),
            vec![
                (7, 6),
                (0, 0),
                (6, 1),
                (7, 2),
                (0, 0),
                (6, 5),
                (7, 1),
                (0, 0),
                (6, 0),
                (3, 1)
            ],
            "F48-A 逐目标（骰 → GP13 → RP）×3 + TRAIN"
        );
        assert_eq!(
            b4_seq(&frames, 911),
            vec![SM_53, SM_638, SM_642, SM_642, SM_642],
            "每成功目标一条 642（同优先级保持枚举序）"
        );
        assert_eq!(b4_seq(&frames, 912), vec![SM_17, SM_638]);
        let poisons = rig.delay_msgs(mir2_world::slave::RM_POISON);
        assert_eq!(poisons.len(), 3);
        assert_eq!(
            poisons
                .iter()
                .map(|p| (p.actor_id, p.n_param1, p.n_param3))
                .collect::<Vec<_>>(),
            vec![(m1, 45, 3), (m2, 53, 4), (m3, 43, 3)],
            "毒 time/point 与枚举序"
        );
        assert_eq!(
            rig.target_creature(),
            Some(m3),
            "SetTargetCreat = 最后一个目标"
        );
        assert_eq!(rig.mp(), 1000 - 6, "行 Idx=48 ⇒ nSpellPoint=6");
        assert_eq!(rig.tran_point(), 2);

        // ---- F48-B：行 Idx=38（群体施毒术）——账本相同，nPower 每个 +4、MP 39 ----
        let mut rig = B4Rig::new(b4_magic_info(48, "48b"), 2, Some(600));
        // 行选择牙夹具：记录 MagicList **首行**放 Idx=38、次行放 Idx=48；`find_magic(...,48)`
        // 必须按 MagIdx 命中次行。若改成「取首行」（48-1 变异）⇒ 取到 level=7/tran_point=9 的 38 行
        // ⇒ 帧参/训练值全变 ⇒ 红。
        {
            let magic = rig
                .saves
                .get_mut("caster")
                .unwrap()
                .record
                .data
                .magic
                .as_mut()
                .unwrap();
            magic.insert(
                0,
                Some(record::MagicRcd {
                    mag_idx: 38,
                    level: 7,
                    magic_key: 0,
                    tran_point: 9,
                }),
            );
        }
        let m1 = rig.add_monster("m1", 11, 11, 80, 10, 0, 0, 0);
        let _m2 = rig.add_monster("m2", 12, 11, 80, 10, 0, 0, 0);
        let _m3 = rig.add_monster("m3", 12, 12, 80, 10, 0, 0, 0);
        rig.seed(0);
        let before = rig.world.rng.clone();
        rig.cast(48, (11, 11), m1);
        assert_eq!(
            b4_ledger(&before, &rig.world.rng, &maxes),
            vec![
                (7, 6),
                (0, 0),
                (6, 1),
                (7, 2),
                (0, 0),
                (6, 5),
                (7, 1),
                (0, 0),
                (6, 0),
                (3, 1)
            ],
            "F48-B 与 A 逐项相同的 RNG 账本"
        );
        let poisons = rig.delay_msgs(mir2_world::slave::RM_POISON);
        assert_eq!(
            poisons.iter().map(|p| p.n_param1).collect::<Vec<_>>(),
            vec![49, 57, 47],
            "Idx=38 ⇒ GP13=37 ⇒ nPower 每个 +4"
        );
        assert_eq!(
            poisons.iter().map(|p| p.n_param3).collect::<Vec<_>>(),
            vec![3, 4, 3]
        );
        assert_eq!(rig.mp(), 1000 - 39, "行 Idx=38 ⇒ nSpellPoint=39");

        // ---- F48-C：dura=100 ⇒ 第 1 目标 202、第 2/3 目标 CheckAmulet 失败 ----
        let mut rig = B4Rig::new(b4_magic_info(48, "48a"), 2, Some(100));
        let m1 = rig.add_monster("m1", 11, 11, 80, 10, 0, 0, 0);
        let _m2 = rig.add_monster("m2", 12, 11, 80, 10, 0, 0, 0);
        let _m3 = rig.add_monster("m3", 12, 12, 80, 10, 0, 0, 0);
        rig.seed(0);
        let before = rig.world.rng.clone();
        rig.cast(48, (11, 11), m1);
        let frames = rig.drain();
        assert_eq!(
            b4_ledger(&before, &rig.world.rng, &[7, 0, 6, 3]),
            vec![(7, 6), (0, 0), (6, 1), (3, 1)],
            "只有第 1 目标抽数"
        );
        assert_eq!(
            b4_seq(&frames, 911),
            vec![SM_202, SM_53, SM_638],
            "202 先于 53；无 642"
        );
        assert_eq!(
            rig.delay_msgs(mir2_world::slave::RM_POISON)
                .iter()
                .map(|p| p.actor_id)
                .collect::<Vec<_>>(),
            vec![m1],
            "毒只给第 1 目标"
        );
        assert_eq!(
            rig.target_creature(),
            Some(m1),
            "第 2/3 目标不 SetTargetCreat"
        );
        let f = rig.deliver(1000);
        assert_eq!(b4_count(&f, 911, SM_657), 1);
        assert_eq!(b4_count(&f, 911, SM_640), 1, "boTrain=true ⇒ 640");

        // ---- F48-D：race=10（NPC 段）⇒ 非 proper ⇒ 零抽、无 642/毒/640 ----
        let mut rig = B4Rig::new(b4_magic_info(48, "48a"), 2, Some(600));
        let m1 = rig.add_monster("m1", 11, 11, 10, 10, 0, 0, 0);
        let _m2 = rig.add_monster("m2", 12, 11, 10, 10, 0, 0, 0);
        let _m3 = rig.add_monster("m3", 12, 12, 10, 10, 0, 0, 0);
        rig.seed(0);
        let before = rig.world.rng.clone();
        rig.cast(48, (11, 11), m1);
        let frames = rig.drain();
        assert_eq!(
            b4_ledger(&before, &rig.world.rng, &[]),
            Vec::<(i32, i32)>::new()
        );
        assert_eq!(b4_seq(&frames, 911), vec![SM_53, SM_638]);
        assert_eq!(rig.delay_msgs(mir2_world::slave::RM_POISON).len(), 0);
        assert_eq!(rig.target_creature(), None, "非 proper 不 SetTargetCreat");
        let f = rig.deliver(1000);
        assert_eq!(b4_count(&f, 911, SM_640), 0);
    }

    /// **F50-A2/B/C2/D2**：MabMabe。case 级 4 抽无条件、第一条 RM_DELAYMAGIC 先于等级门、
    /// 投递两相位、玩家目标 `R(nLevel)`/656/100。
    #[test]
    fn spell_p3b4_50_mab_mabe_two_phases_and_gates() {
        const SM_17: u16 = mir2_protocol::messages::SM_SPELL;
        const SM_31: u16 = mir2_protocol::messages::SM_STRUCK;
        const SM_53: u16 = mir2_protocol::messages::SM_HEALTHSPELLCHANGED;
        const SM_100: u16 = mir2_protocol::messages::SM_SYSMESSAGE;
        const SM_638: u16 = mir2_protocol::messages::SM_MAGICFIRE;
        const SM_640: u16 = mir2_protocol::messages::SM_MAGIC_LVEXP;
        const SM_656: u16 = mir2_protocol::messages::SM_CHANGENAMECOLOR;
        const SM_657: u16 = mir2_protocol::messages::SM_CHARSTATUSCHANGED;

        // ---- F50-A2：monster (11,10)，pre_draws=4 ----
        let mut rig = B4Rig::new(b4_magic_info(50, "50"), 2, None);
        let m = rig.add_monster("m", 11, 10, 80, 10, 0, 0, 0);
        rig.seed(4);
        let before = rig.world.rng.clone();
        rig.cast(50, (11, 10), m);
        let frames = rig.drain();
        assert_eq!(
            b4_ledger(
                &before,
                &rig.world.rng,
                &[0, 0, 7, 10, 10, 2, 100, 21, 1, 3]
            ),
            vec![
                (0, 0),
                (0, 0),
                (7, 1),
                (10, 6),
                (10, 1),
                (2, 1),
                (100, 4),
                (21, 2),
                (1, 0),
                (3, 0)
            ],
            "F50-A2 施法 tick 逐抽"
        );
        assert_eq!(b4_seq(&frames, 911), vec![SM_53, SM_638]);
        assert_eq!(b4_seq(&frames, 912), vec![SM_17, SM_638]);
        let delays = rig.delay_msgs(mir2_world::slave::RM_DELAYMAGIC);
        assert_eq!(delays.len(), 2, "两条 RM_DELAYMAGIC");
        assert_eq!(
            (delays[0].w_param, delays[0].n_param2, delays[0].n_param3),
            (2, 2, m),
            "第一条 = nPower/3 = 2"
        );
        assert_eq!(delays[1].w_param, 7, "第二条 = post-MSD nPower = 7");
        // 投递 tick（承接同一流）：本 tick 只投第一条 RM_DELAYMAGIC ⇒ caster MSD ×1 →
        // 目标 R(1000)+MSD ×1；第二条与 lvexp 一起留到 t=1000。
        let before = rig.world.rng.clone();
        let f = rig.deliver(600);
        // **oracle 队列实测**（net8.0）：同 actor 两条 `RM_DELAYMAGIC`(600) 后还有一条
        // `RM_MAGIC_LVEXP`(1000)；出队第一条后 .NET 堆把**末元素**（lvexp）移到根，
        // 它未到点 ⇒ 本次泵停——第二条**虽已到点**也不在本 tick 投递。故本 tick 只有
        // 第一条的 3 抽 [1,1000,1]；第二条留到 t=1000 与 lvexp 一起投。
        assert_eq!(
            b4_ledger(&before, &rig.world.rng, &[1, 1000, 1]),
            vec![(1, 0), (1000, 527), (1, 0)],
            "F50-A2 投递 tick 逐抽（仅第一条 RM_DELAYMAGIC）"
        );
        assert_eq!(b4_seq(&f, 911), vec![SM_656, SM_31]);
        assert_eq!(b4_seq(&f, 912), vec![SM_656, SM_31]);
        let struck = b4_all(&f, 911, SM_31);
        assert_eq!(
            struck.iter().map(|b| b4_cmd(b).series).collect::<Vec<_>>(),
            vec![2],
            "31 的 damage = Round(2/1.2)=2（第二条在 t=1000）"
        );
        let f = rig.deliver(400);
        assert_eq!(b4_count(&f, 911, SM_640), 1);

        // ---- F50-B：anti_magic=11 ⇒ 5 抽、无 RM_DELAYMAGIC/640 ----
        let mut rig = B4Rig::new(b4_magic_info(50, "50"), 2, None);
        let m = rig.add_monster("m", 11, 10, 80, 10, 0, 11, 0);
        rig.seed(4);
        let before = rig.world.rng.clone();
        rig.cast(50, (11, 10), m);
        let frames = rig.drain();
        assert_eq!(
            b4_ledger(&before, &rig.world.rng, &[0, 0, 7, 10, 10]),
            vec![(0, 0), (0, 0), (7, 1), (10, 6), (10, 1)],
            "F50-B 恰 5 抽（4 抽 + R(10)）"
        );
        assert_eq!(b4_seq(&frames, 911), vec![SM_53, SM_638]);
        assert!(rig.delay_msgs(mir2_world::slave::RM_DELAYMAGIC).is_empty());

        // ---- F50-C2：level=200 ⇒ 等级门失败，但第一条 RM_DELAYMAGIC 已入队 ----
        let mut rig = B4Rig::new(b4_magic_info(50, "50"), 2, None);
        let m = rig.add_monster("m", 11, 10, 80, 200, 0, 0, 0);
        rig.seed(4);
        let before = rig.world.rng.clone();
        rig.cast(50, (11, 10), m);
        let frames = rig.drain();
        assert_eq!(
            b4_ledger(&before, &rig.world.rng, &[0, 0, 7, 10, 10, 2]),
            vec![(0, 0), (0, 0), (7, 1), (10, 6), (10, 1), (2, 1)],
            "F50-C2 恰 6 抽"
        );
        assert_eq!(b4_seq(&frames, 911), vec![SM_53, SM_638]);
        assert_eq!(b4_seq(&frames, 912), vec![SM_17, SM_638]);
        let delays = rig.delay_msgs(mir2_world::slave::RM_DELAYMAGIC);
        assert_eq!(delays.len(), 1, "等级门失败仍有一条 RM_DELAYMAGIC");
        assert_eq!(delays[0].w_param, 2, "nPower/3 = 7/3 = 2（整数除法）");
        let before = rig.world.rng.clone();
        let f = rig.deliver(600);
        assert_eq!(
            b4_ledger(&before, &rig.world.rng, &[1, 1]),
            vec![(1, 0), (1, 0)],
            "caster MSD + 目标 MSD（Level=200 不抽 R(1000)）"
        );
        assert_eq!(b4_seq(&f, 911), vec![SM_656, SM_31]);
        assert_eq!(b4_count(&f, 911, SM_640), 0);

        // ---- F50-D2：玩家目标 2500 ⇒ 第 10 抽 R(nLevel)、656、650ms 的 100（time=0 无 657）----
        let mut rig = B4Rig::new(b4_magic_info(50, "50"), 2, None);
        let _m = rig.add_monster("dummy", 11, 12, 80, 10, 0, 0, 0);
        let p = rig.add_player("target", 12, 11, 913);
        rig.world.set_attack_poison(
            p,
            mir2_world::combat::AttackPoisonState {
                un_paralysis: false,
                anti_poison: 0,
                paralysis: false,
            },
        );
        rig.seed(4);
        let before = rig.world.rng.clone();
        rig.cast(50, (12, 11), p);
        let frames = rig.drain();
        assert_eq!(
            b4_ledger(
                &before,
                &rig.world.rng,
                &[0, 0, 7, 10, 10, 2, 100, 21, 1, 2, 3]
            ),
            vec![
                (0, 0),
                (0, 0),
                (7, 1),
                (10, 6),
                (10, 1),
                (2, 1),
                (100, 4),
                (21, 2),
                (1, 0),
                (2, 0),
                (3, 2)
            ],
            "F50-D2 施法 tick 逐抽（含 R(nLevel=2)）"
        );
        assert_eq!(b4_seq(&frames, 911), vec![SM_53, SM_638, SM_656]);
        assert_eq!(b4_seq(&frames, 912), vec![SM_17, SM_638, SM_656]);
        assert_eq!(
            b4_seq(&frames, 913),
            vec![SM_17, SM_638, SM_656],
            "T 收自己的 656"
        );
        assert!(rig.world.entities.get(p).unwrap().pvp_flag, "SetPkFlag");
        // +600ms：两条 RM_DELAYMAGIC 中只有第一条在本 tick 投递（第二条被 lvexp 堆根阻塞到
        // t=1000）；玩家目标：MSD + `StruckDamage` R(10)。
        let before = rig.world.rng.clone();
        let f = rig.deliver(600);
        assert_eq!(
            b4_ledger(&before, &rig.world.rng, &[1, 1, 10]),
            vec![(1, 0), (1, 0), (10, 9)],
            "F50-D2 投递 tick（仅第一条 RM_DELAYMAGIC；玩家目标无 R(1000)，STD R(10)）"
        );
        // **oracle 队列实测**：t=600 只投第一条 `RM_DELAYMAGIC`（第二条被 lvexp 的
        // 堆根阻塞到 t=1000）⇒ 目标侧本 tick 只有 `53 → 31` 这一对。
        assert_eq!(b4_seq(&f, 913), vec![SM_53, SM_31]);
        assert_eq!(
            b4_count(&f, 913, SM_656),
            0,
            "target 已 PvpFlag ⇒ 无第二条 656"
        );
        // +650ms 的 STONE：time = 7/20 + R(2) = 0 ⇒ 只有 100，无 657。
        let f = rig.deliver(50);
        assert_eq!(b4_count(&f, 913, SM_100), 1, "目标自己收 YouPoisoned");
        // 文本必须来自 `[String] YouPoisoned`（现网 `String.conf:31`「您中毒了!!!」）——
        // `MessageSettings.cs:64` 的「中毒了!!!」只是**缺键回落**；用源码默认会少 2 个汉字。
        let msg = b4_all(&f, 913, SM_100);
        assert_eq!(
            mir2_protocol::edcode::decode(&msg[0][12..]),
            b"\xc4\xfa\xd6\xd0\xb6\xbe\xc1\xcb!!!",
            "YouPoisoned 体字节 = `您中毒了!!!` 的 GBK（c4fad6d0b6bec1cb212121）"
        );
        assert_eq!(
            b4_count(&f, 913, SM_657),
            0,
            "time=0 ⇒ StateTick=0 ⇒ 无 657"
        );
        assert_eq!(b4_count(&f, 911, SM_100) + b4_count(&f, 912, SM_100), 0);
    }

    /// **P3 收尾残余 4**：50 的 `Level=0` / `R(nLevel=0)`（`p3-b4-contract` §6-7）。
    ///
    /// .NET `Random(0)` 仍调用一次 `Sample()`（值恒 0）；Rust `random_below(0)` 同口径。
    /// 夹具同 F50-D2（玩家目标），只把 `MagicRcd.level` 由 2 改成 0：施法 tick 的抽数
    /// `[0,0,7,10,10,2,100,21,1,0,3]` —— 第 10 抽 `R(nLevel=0)` **照抽一次且恒 0**，
    /// 其后训练尾 `R(3)` 的位置不变。
    ///
    /// 牙：把 `cast_mab_mabe_spell` 的 `R(nLevel)` 改成「`level==0` 跳过」⇒ RNG 末态少一抽，
    /// `b4_ledger` 必红（多抽/少抽断言）。
    #[test]
    fn spell_p3b4_50_mab_mabe_level_zero_advances_r_zero_once() {
        const SM_17: u16 = mir2_protocol::messages::SM_SPELL;
        const SM_53: u16 = mir2_protocol::messages::SM_HEALTHSPELLCHANGED;
        const SM_638: u16 = mir2_protocol::messages::SM_MAGICFIRE;
        const SM_656: u16 = mir2_protocol::messages::SM_CHANGENAMECOLOR;

        let mut rig = B4Rig::new(b4_magic_info(50, "50"), 0, None);
        let _m = rig.add_monster("dummy", 11, 12, 80, 10, 0, 0, 0);
        let p = rig.add_player("target", 12, 11, 913);
        rig.world.set_attack_poison(
            p,
            mir2_world::combat::AttackPoisonState {
                un_paralysis: false,
                anti_poison: 0,
                paralysis: false,
            },
        );
        // seed=4：与 F50-D2 同流；Level=0 只改 `GetPower` 的等级缩放，不改抽数 max 序。
        rig.seed(4);
        let before = rig.world.rng.clone();
        rig.cast(50, (12, 11), p);
        let frames = rig.drain();
        assert_eq!(
            b4_ledger(
                &before,
                &rig.world.rng,
                &[0, 0, 7, 10, 10, 2, 100, 21, 1, 0, 3]
            ),
            vec![
                (0, 0),
                (0, 0),
                (7, 1),
                (10, 6),
                (10, 1),
                (2, 1),
                (100, 4),
                (21, 2),
                (1, 0),
                (0, 0),
                (3, 2)
            ],
            "Level=0：R(nLevel) 仍恰推进一次且值恒 0（第 10 抽）"
        );
        assert_eq!(b4_seq(&frames, 913), vec![SM_17, SM_638, SM_656]);
        assert_eq!(
            b4_seq(&frames, 911),
            vec![SM_53, SM_638, SM_656],
            "656 由 target 的 SetPkFlag 发出，观察者（含施法者）各收一条"
        );
        assert_eq!(b4_count(&frames, 911, SM_656), 1);
        assert!(rig.world.entities.get(p).unwrap().pvp_flag);
        let poison = rig.delay_msgs(mir2_world::slave::RM_POISON);
        assert_eq!(
            poison.len(),
            1,
            "R(nLevel)=0 ⇒ time 仍按 nPower/20 + 0 投递"
        );
        assert_eq!(poison[0].actor_id, p, "RM_POISON 投递目标是玩家自己");
        assert_eq!(poison[0].n_param3, 0, "nPoint = Level = 0");
    }

    /// **F42-A/B/C/C2**：群体雷电术。null 目标 NPE→639；helper 638 循环前；716 在骰门外；
    /// `boSpellFire=false` 不留第二条 638。
    #[test]
    fn spell_p3b4_42_group_lightening_npe_638_and_716() {
        const SM_17: u16 = mir2_protocol::messages::SM_SPELL;
        const SM_31: u16 = mir2_protocol::messages::SM_STRUCK;
        const SM_53: u16 = mir2_protocol::messages::SM_HEALTHSPELLCHANGED;
        const SM_638: u16 = mir2_protocol::messages::SM_MAGICFIRE;
        const SM_639: u16 = mir2_protocol::messages::SM_MAGICFIRE_FAIL;
        const SM_640: u16 = mir2_protocol::messages::SM_MAGIC_LVEXP;
        const SM_656: u16 = mir2_protocol::messages::SM_CHANGENAMECOLOR;
        const SM_716: u16 = mir2_protocol::messages::SM_716;

        // ---- F42-A：null 目标 ⇒ 零抽、恰 1 条 639、无 638/716/640 ----
        let mut rig = B4Rig::new(b4_magic_info(42, "42"), 2, None);
        let _m = rig.add_monster("m", 11, 10, 80, 10, 0, 0, 0);
        rig.seed(0);
        let before = rig.world.rng.clone();
        rig.cast(42, (11, 10), 0);
        let frames = rig.drain();
        assert_eq!(
            b4_ledger(&before, &rig.world.rng, &[]),
            Vec::<(i32, i32)>::new()
        );
        assert_eq!(b4_seq(&frames, 911), vec![SM_53, SM_639]);
        assert_eq!(b4_seq(&frames, 912), vec![SM_17, SM_639]);
        assert_eq!(b4_count(&frames, 911, SM_638), 0);

        // ---- F42-B：M1(11,11)/M2(12,12) ----
        let mut rig = B4Rig::new(b4_magic_info(42, "42"), 2, None);
        let m1 = rig.add_monster("m1", 11, 11, 80, 10, 0, 0, 0);
        let m2 = rig.add_monster("m2", 12, 12, 80, 10, 0, 0, 0);
        rig.seed(0);
        let before = rig.world.rng.clone();
        rig.cast(42, (11, 11), m1);
        let frames = rig.drain();
        assert_eq!(
            b4_ledger(
                &before,
                &rig.world.rng,
                &[10, 0, 0, 7, 10, 10, 0, 0, 7, 10, 3]
            ),
            vec![
                (10, 8),
                (0, 0),
                (0, 0),
                (7, 2),
                (10, 4),
                (10, 8),
                (0, 0),
                (0, 0),
                (7, 1),
                (10, 5),
                (3, 0)
            ],
            "F42-B 逐目标（骰 + MPow + GP + AP + luck）+ TRAIN"
        );
        assert_eq!(
            b4_seq(&frames, 911),
            vec![SM_53, SM_638, SM_716],
            "638 先于 716"
        );
        assert_eq!(b4_seq(&frames, 912), vec![SM_17, SM_638, SM_716]);
        assert_eq!(
            b4_count(&frames, 911, SM_638),
            1,
            "boSpellFire=false ⇒ 恰一条 638"
        );
        let icon = b4_cmd(sf_first(&frames, 911, SM_716));
        assert_eq!(
            (icon.param, icon.tag, icon.series),
            (12, 12, 4),
            "仅 M2 的 716"
        );
        let fire = sf_first(&frames, 911, SM_638);
        assert_eq!(sf_magicfire_target_id(fire), m1, "638 ActorId = 点击目标");
        assert_eq!(rig.delay_msgs(mir2_world::slave::RM_DELAYMAGIC).len(), 2);
        let before = rig.world.rng.clone();
        let f = rig.deliver(600);
        // **oracle 队列实测**（net8.0）：两条 `RM_DELAYMAGIC`(600) 之后还有一条
        // `RM_MAGIC_LVEXP`(1000)；第一条出队后根变成未到点的 lvexp ⇒ 本次泵停，
        // 第二条留到 t=1000。本 tick 只有第一条的 3 抽 [1,1000,1]。
        assert_eq!(
            b4_ledger(&before, &rig.world.rng, &[1, 1000, 1]),
            vec![(1, 0), (1000, 222), (1, 0)],
            "F42-B 投递 tick（仅第一条 RM_DELAYMAGIC）"
        );
        assert_eq!(b4_seq(&f, 911), vec![SM_656, SM_31]);
        let struck = b4_all(&f, 911, SM_31);
        assert_eq!(
            struck.iter().map(|b| b4_cmd(b).series).collect::<Vec<_>>(),
            vec![6],
            "31 damage = Round(7/1.2)=6（第二条在 t=1000）"
        );
        let f = rig.deliver(400);
        assert_eq!(b4_count(&f, 911, SM_640), 1);
        let _ = m2;

        // ---- F42-C：race=10 ⇒ 非 proper、零抽、仍有 638、无 716/640 ----
        let mut rig = B4Rig::new(b4_magic_info(42, "42"), 2, None);
        let m1 = rig.add_monster("m1", 11, 11, 10, 10, 0, 0, 0);
        let _m2 = rig.add_monster("m2", 12, 12, 10, 10, 0, 0, 0);
        rig.seed(0);
        let before = rig.world.rng.clone();
        rig.cast(42, (11, 11), m1);
        let frames = rig.drain();
        assert_eq!(
            b4_ledger(&before, &rig.world.rng, &[]),
            Vec::<(i32, i32)>::new()
        );
        assert_eq!(b4_seq(&frames, 911), vec![SM_53, SM_638]);
        assert_eq!(b4_count(&frames, 911, SM_716), 0);
        let f = rig.deliver(1000);
        assert_eq!(b4_count(&f, 911, SM_640), 0);

        // ---- F42-C2：anti_magic=11 ⇒ 每目标 1 抽；716 仍在骰门外 ----
        let mut rig = B4Rig::new(b4_magic_info(42, "42"), 2, None);
        let m1 = rig.add_monster("m1", 11, 11, 80, 10, 0, 11, 0);
        let _m2 = rig.add_monster("m2", 12, 12, 80, 10, 0, 11, 0);
        rig.seed(0);
        let before = rig.world.rng.clone();
        rig.cast(42, (11, 11), m1);
        let frames = rig.drain();
        assert_eq!(
            b4_ledger(&before, &rig.world.rng, &[10, 10]),
            vec![(10, 8), (10, 4)],
            "F42-C2 两目标各 1 抽"
        );
        assert_eq!(b4_seq(&frames, 911), vec![SM_53, SM_638, SM_716]);
        assert_eq!(b4_count(&frames, 911, SM_716), 1, "M2 仍收 716（骰门外）");
        assert!(rig.delay_msgs(mir2_world::slave::RM_DELAYMAGIC).is_empty());
        let f = rig.deliver(1000);
        assert_eq!(b4_count(&f, 911, SM_640), 0);
    }

    /// **B4-42-5**：不死系 ×1.5 —— 抽数不变、31 的伤害值变。
    #[test]
    fn spell_p3b4_42_undead_multiplier_changes_damage_only() {
        const SM_31: u16 = mir2_protocol::messages::SM_STRUCK;

        let mut rig = B4Rig::new(b4_magic_info(42, "42"), 2, None);
        let m = rig.add_monster("m", 11, 11, 80, 10, 1, 0, 0); // LA_UNDEAD=1
        rig.seed(0);
        let before = rig.world.rng.clone();
        rig.cast(42, (11, 11), m);
        let got = b4_ledger(&before, &rig.world.rng, &[10, 0, 0, 7, 10, 3]);
        assert_eq!(
            got,
            vec![(10, 8), (0, 0), (0, 0), (7, 2), (10, 4), (3, 2)],
            "×1.5 是纯数值，不增抽"
        );
        let f = rig.deliver(600);
        let struck = b4_all(&f, 911, SM_31);
        assert_eq!(struck.len(), 1);
        // nPower = 7 ⇒ Round(7*1.5)=11；投递 MSD(11)=11（MAC=0），/1.2 = Round(9.17)=9。
        assert_eq!(b4_cmd(&struck[0]).series, 9, "不死 ×1.5 后的 31 伤害");
    }

    // ═════════ HAM_GROUP 团长表统一（跨批收口：B1/B2/firewind/tamming）═════════
    //
    // oracle `IsGroupMember`（`PlayObject.cs:5158-5175`）读的是**团长**（`GroupOwner`）的
    // `GroupMembers`；`GroupOwner == 0` ⇒ false。本仓 `party_create_group` 只把成员表挂在
    // 团长实体（`party.rs:542-544`），`JoinGroup` 只给成员写 `group_owner`（`party.rs:321-323`）
    // ⇒ **非团长施法者自身的 `group_members` 恒空**。若任一调用点仍传 `&caster.group_members`，
    // 同组玩家会被误判为合法目标：多抽骰门/威力、白扣护身符、多发延迟帧/伤害。
    //
    // 以下用例全部走**生产入口** `handle_spell_cmd`，布局 = 真实布局（施法者非团长、团长实体持表）。

    /// 真实布局：施法者挂到团长 `leader` 名下（自身表清空），团长表 = `members` 且
    /// `group_owner` 指向自己（oracle `JoinGroup(this)`，`PlayObject.Operate.cs:837`）。
    fn install_ham_group(rig: &mut SpellFrameRig, leader: i32, members: &[i32]) {
        let caster = rig.caster;
        {
            let c = rig.world.entities.get_mut(caster).unwrap();
            c.attack_mode = mir2_world::combat::ATTACK_MODE_HAM_GROUP;
            c.group_owner = leader;
            c.group_members.clear();
            assert!(
                c.group_members.is_empty(),
                "非团长自身表必须为空（真实布局）"
            );
        }
        let l = rig.world.entities.get_mut(leader).unwrap();
        l.group_owner = leader;
        l.group_members = members.to_vec();
    }

    /// **B1（1/5/11/13/44/45）**：同组玩家目标 ⇒ `IsProperTarget` 直接拒绝 ⇒ **零抽**、
    /// 不投 `RM_DELAYMAGIC`、无训练尾；13 的护身符门在 `IsProperTarget` **之前**（oracle
    /// `:322-325`）照常消耗，共享尾 638 的 ActorId 保留目标（oracle `:332-341` 非对称）。
    ///
    /// 牙：任一支改回 `&caster.group_members`（空表）⇒ 骰门/威力多抽 ⇒ 本用例红；
    /// `attacker_group_members` 改成恒空表 ⇒ 同样红。
    #[test]
    fn ham_group_owner_table_b1_sites_exclude_same_group_player() {
        const SM_SPELL: u16 = mir2_protocol::messages::SM_SPELL;
        const SM_MAGICFIRE: u16 = mir2_protocol::messages::SM_MAGICFIRE;
        const SM_MAGIC_LVEXP: u16 = mir2_protocol::messages::SM_MAGIC_LVEXP;

        for magic_id in [1u16, 5, 11, 13, 44, 45] {
            let mut rig = b1_rig(magic_id, 9);
            let ally = b1_player(&mut rig, 11, 10, 1, 0);
            let leader = b1_player(&mut rig, 20, 20, 60, 0);
            let caster = rig.caster;
            install_ham_group(&mut rig, leader, &[leader, caster, ally]);

            let seed = b1_seed(0, None);
            rig.world.rng = mir2_shared::rng::RandomNumber::with_seed(seed);
            let before = rig.world.rng.clone();
            rig.cast(magic_id, (11, 10), ally);
            let (frames, _raws) = rig.drain();

            assert_eq!(
                draws_between(&before, &rig.world.rng),
                0,
                "[{magic_id}] 同组玩家 ⇒ IsProperTarget 拒绝 ⇒ 零抽（多抽即读错表）"
            );
            assert!(
                rig.world.self_delay_msgs.is_empty(),
                "[{magic_id}] 不得投 RM_DELAYMAGIC/RM_DELAYPUSHED"
            );
            assert_eq!(
                sf_count(&frames, 911, SM_MAGIC_LVEXP),
                0,
                "[{magic_id}] boTrain=false ⇒ 无训练尾"
            );
            assert_eq!(
                sf_seq(&frames, 912),
                vec![SM_SPELL, SM_MAGICFIRE],
                "[{magic_id}] 观察者恰 SM_SPELL → SM_MAGICFIRE"
            );
            let fire = sf_first(&frames, 912, SM_MAGICFIRE);
            // 13 的 IsProperTarget 失败支**保留** targetObject（oracle `:332-341` 无 else）；
            // 1/5/11/44/45 失败支把它置 null（共享尾 ActorId=0）。
            let want_target = if magic_id == 13 { ally } else { 0 };
            assert_eq!(
                sf_magicfire_target_id(fire),
                want_target,
                "[{magic_id}] 共享尾 638 的 ActorId"
            );
        }
    }

    /// **B2（23/24/33/47）**：同组玩家目标不被计入逐目标伤害；范围内怪物照常受击。
    ///
    /// 施法者侧 4 抽无条件（oracle 实参求值序）；每只怪交付段 `R(1000)+MSD(+R(300))`。
    /// 牙：改回 `&caster.group_members` 或把团长表解析成空表 ⇒ 玩家也被交付（多抽 + 53/31）
    /// ⇒ 抽数、HP、帧面三重红。
    #[test]
    fn ham_group_owner_table_b2_sites_exclude_same_group_player() {
        const SM_53: u16 = mir2_protocol::messages::SM_HEALTHSPELLCHANGED;
        const SM_31: u16 = mir2_protocol::messages::SM_STRUCK;
        const SM_656: u16 = mir2_protocol::messages::SM_CHANGENAMECOLOR;

        for magic_id in [23u16, 24, 33, 47] {
            let mut rig = b2_rig(magic_id, 21, &[("obs", 10, 13, false, 912)]);
            let ally = b2_add_player(&mut rig, "ally", 11, 10, 50, 1000, 921);
            let mon = b2_add_monster(&mut rig, "m1", 11, 11, 0);
            let leader = b2_add_player(&mut rig, "leader", 20, 20, 100, 100, 922);
            let caster = rig.caster;
            install_ham_group(&mut rig, leader, &[leader, caster, ally]);

            rig.world.rng = mir2_shared::rng::RandomNumber::with_seed(42);
            let before = rig.world.rng.clone();
            rig.cast(magic_id, (11, 10), ally);
            let (frames, _raws) = rig.drain();

            assert!(
                draws_between(&before, &rig.world.rng) <= 7,
                "[{magic_id}] 只该有 4 施法者抽 + 怪物交付（<=3）；同组玩家不得被交付"
            );
            assert_eq!(
                rig.world.entities.get(ally).unwrap().hp,
                50,
                "[{magic_id}] 同组玩家不得掉血"
            );
            assert!(
                rig.world.entities.get(mon).unwrap().hp < 1000,
                "[{magic_id}] 范围内怪物照常受击（控制组）"
            );
            // 921 仍会收到广播的 SM_SPELL/SM_MAGICFIRE（视野内玩家），但**不得有任何伤害帧**。
            let ally_seq = b2_seq(&frames, 921);
            assert_eq!(
                ally_seq
                    .iter()
                    .filter(|(id, recog)| matches!(*id, SM_53 | SM_31 | SM_656) && *recog == ally)
                    .count(),
                0,
                "[{magic_id}] 同组玩家自身不得成为受击者（53/31/656 recog=ally）；实得 {ally_seq:?}"
            );
        }
    }

    /// **firewind 8/37**：`MagPushArround` 的 `IsProperTarget` 在 `Random(20)` 门之后、
    /// `Random(2)` 步数之前（`MagicManager.cs:37-41`）⇒ 同组玩家恰消耗 1 抽、不被推。
    ///
    /// 牙：改回施法者自己的空表 ⇒ 多 1 抽步数并产生 `SM_BACKSTEP` ⇒ 红。
    #[test]
    fn ham_group_owner_table_firewind_excludes_same_group_player() {
        const SM_BACKSTEP: u16 = mir2_protocol::messages::SM_BACKSTEP;

        let mut rig = SpellFrameRig::new(
            mir2_world::magic::SKILL_FIREWIND,
            &[(mir2_world::magic::SKILL_FIREWIND, 3)],
            &[("obs", 12, 11, false, 912)],
        );
        rig.world.entities.get_mut(rig.caster).unwrap().level = 20;
        let ally = b1_player(&mut rig, 11, 10, 15, 0);
        let leader = b1_player(&mut rig, 20, 20, 60, 0);
        let caster = rig.caster;
        install_ham_group(&mut rig, leader, &[leader, caster, ally]);
        // 显式可见集：只含同组玩家（oracle `VisibleActors` 顺序）。
        rig.world
            .entities
            .get_mut(rig.caster)
            .unwrap()
            .visible_actors = vec![mir2_world::entity::VisibleBaseObject {
            target: ally,
            flag: mir2_world::entity::VisibleFlag::Show,
        }];

        let seed = 1; // 既有正例同 seed：chance 门必过（gap=5, push_level=1 ⇒ 阈值 14）
        rig.world.rng = mir2_shared::rng::RandomNumber::with_seed(seed);
        let before = rig.world.rng.clone();
        rig.cast(mir2_world::magic::SKILL_FIREWIND, (11, 10), 0);
        let (frames, _raws) = rig.drain();

        assert_eq!(
            draws_between(&before, &rig.world.rng),
            1,
            "只消耗 Random(20) 门；IsProperTarget 拒绝后不得再抽 Random(2)"
        );
        assert_eq!(
            sf_count(&frames, 911, SM_BACKSTEP) + sf_count(&frames, 912, SM_BACKSTEP),
            0,
            "同组玩家不得被推（无 SM_BACKSTEP）"
        );
        let (ax, ay) = {
            let a = rig.world.entities.get(ally).unwrap();
            (a.x, a.y)
        };
        assert_eq!((ax, ay), (11, 10), "同组玩家坐标不变");
    }

    /// **tamming 20**：`IsProperTarget(targetObject) && !Animal`（`MagicManager.cs:394-397`）；
    /// 客户端可把同组玩家的 ActorId 当目标发来 ⇒ 必须在 `MagTamming` 前拒绝（零抽）。
    ///
    /// 牙：改回 `&caster.group_members` ⇒ 进入 `MagTamming` 抽数（`R(2)` + 尾）⇒ 红。
    #[test]
    fn ham_group_owner_table_tamming_excludes_same_group_player() {
        let mut rig = SpellFrameRig::new(
            mir2_world::slave::SKILL_TAMMING,
            &[(mir2_world::slave::SKILL_TAMMING, 3)],
            &[("obs", 12, 11, false, 912)],
        );
        let ally = b1_player(&mut rig, 11, 10, 1, 0);
        let leader = b1_player(&mut rig, 20, 20, 60, 0);
        let caster = rig.caster;
        install_ham_group(&mut rig, leader, &[leader, caster, ally]);

        rig.world.rng = mir2_shared::rng::RandomNumber::with_seed(7);
        let before = rig.world.rng.clone();
        rig.cast(mir2_world::slave::SKILL_TAMMING, (11, 10), ally);
        let (frames, _raws) = rig.drain();

        assert_eq!(
            draws_between(&before, &rig.world.rng),
            0,
            "同组玩家 ⇒ 不进 MagTamming（零抽）"
        );
        assert_eq!(
            rig.world.entities.get(ally).unwrap().master,
            None,
            "不得受奴"
        );
        assert_eq!(
            sf_count(&frames, 911, mir2_protocol::messages::SM_MAGIC_LVEXP),
            0,
            "boTrain=false ⇒ 无训练尾"
        );
    }

    /// **团长施法 / 非组队不变**：
    /// - 团长自己施法：`group_owner == 自己`（oracle `JoinGroup(this)`），自身的 `group_members`
    ///   就是成员表 ⇒ 修正前后同组玩家仍被剔除（零抽）；
    /// - 非组队：普通目标照旧走完 6 抽 + `RM_DELAYMAGIC`（与既有 B1 用例一致）。
    #[test]
    fn ham_group_owner_table_leader_and_solo_unchanged() {
        // 团长 = 施法者自己。
        let mut rig = b1_rig(1, 9);
        let ally = b1_player(&mut rig, 11, 10, 1, 0);
        {
            let c = rig.world.entities.get_mut(rig.caster).unwrap();
            c.attack_mode = mir2_world::combat::ATTACK_MODE_HAM_GROUP;
            c.group_owner = rig.caster;
            c.group_members = vec![rig.caster, ally];
        }
        let seed = b1_seed(0, None);
        rig.world.rng = mir2_shared::rng::RandomNumber::with_seed(seed);
        let before = rig.world.rng.clone();
        rig.cast(1, (11, 10), ally);
        let (_frames, _raws) = rig.drain();
        assert_eq!(
            draws_between(&before, &rig.world.rng),
            0,
            "团长自己施法 ⇒ 同组玩家仍被剔除（修正前后一致）"
        );

        // 非组队：普通怪 ⇒ 6 抽 + 恰 1 条 RM_DELAYMAGIC。
        let mut rig = b1_rig(1, 9);
        let mon = b1_monster(&mut rig, 11, 10, 1, 0);
        rig.world.rng = mir2_shared::rng::RandomNumber::with_seed(seed);
        let before = rig.world.rng.clone();
        rig.cast(1, (11, 10), mon);
        let _ = rig.drain();
        assert_eq!(
            draws_between(&before, &rig.world.rng),
            6,
            "非组队 ⇒ 既有 1/5 取数序不变（含训练尾；RM_DELAYMAGIC 在 B1 仅回报载荷，不入队）"
        );
    }

    // ======================================================================
    // 卡 P3-B5（9/10/22/36 + 32 的同族组队门）：穿透 / 火墙 / 友方 buff
    // ======================================================================
    //
    // 全部走**生产入口** `handle_spell_cmd`（default 支 ∧ 非战士 ∧ 距离门 ⇒ `SM_SPELL(17)`）；
    // 取数断言 = 按合同 §4.1 的 max 序回放并**逐抽比较 `(max,result)`**，回放末态必须与生产
    // `world.rng` 逐字节相同（多抽/少抽/换序都红）。投递 tick 承接同一流（不重新播种）。
    //
    // 牙（每魔号 ≥2，共 ≥8；对应合同 §3 的「改坏必红」）：
    // - 9：B5-9-1（终点步长 5→3）、B5-9-2（死对象不跳过）、B5-9-3（骰门方向）、
    //      B5-9-4（638 用点击点而非终点）；
    // - 10：B5-10-1（×1.5 只对不死系）、B5-10-2（不复合）、B5-10-3（步长 8→5）、
    //       B5-10-4（骰门失败仍入延迟）；
    // - 22：B5-22-1（漏安全区门）、B5-22-2（先判安全区再抽数）、B5-22-3（中心占用 ⇒ boTrain=false）、
    //       B5-22-6（安全区漏 100）；
    // - 36：B5-36-1（Level=0 跳过 R(Level)）、B5-36-2（漏 SysMsg 100）、
    //       B5-36-3（只做 DC 增量/饱和加）、B5-36-6（Dura<=100 仍发 642）、
    //       B5-36-ArmRingl（ArmRingl 命中不早返回）。

    const B5_SEED: i32 = 20261017;

    /// 合同 §1.2 的部署行（`sql/mir2_data.sql:78/79/91/104`）。
    fn b5_magic_info(id: u16) -> mir2_data::MagicInfo {
        let (
            effect,
            effect_type,
            spell,
            power,
            max_power,
            def_spell,
            def_power,
            def_max_power,
            train_level,
        ) = match id {
            9 => (
                7u8,
                5u8,
                10u16,
                14u16,
                14u16,
                10u8,
                6u8,
                6u8,
                [16u8, 21, 26, 26],
            ),
            10 => (8, 6, 25, 12, 12, 20, 12, 12, [26, 29, 32, 32]),
            22 => (20, 4, 20, 3, 3, 25, 3, 3, [24, 29, 33, 33]),
            36 => (1, 1, 14, 12, 24, 10, 6, 6, [48, 50, 52, 52]),
            // 32（圣言术）只用于同族组队门用例；其余字段不参与该路径的取数。
            _ => (0, 0, 1, 0, 0, 40, 0, 0, [24, 27, 30, 30]),
        };
        mir2_data::MagicInfo {
            magic_id: id,
            effect,
            effect_type,
            spell,
            power,
            max_power,
            def_spell,
            def_power,
            def_max_power,
            train_lv: 3,
            train_level,
            max_train: [200, 300, 500, 500],
            ..mir2_data::MagicInfo::default()
        }
    }

    struct B5Rig {
        world: mir2_world::World,
        caster: i32,
        observer: i32,
        _far: i32,
        online: OnlineRegistry,
        saves: std::collections::HashMap<String, SavedHuman>,
        ground_sessions: std::collections::HashMap<String, SessionGround>,
        magic_table: magics::MagicTable,
        displays: downlink::DisplayTable,
        catalog: game_svr::ability::StdItemCatalog,
        gates: std::collections::HashMap<u8, mpsc::UnboundedSender<SimToGate>>,
        rx: mpsc::UnboundedReceiver<SimToGate>,
        /// 36 目标（= 观察者 2000）重算前的 `WAbil` 快照（自检 + 逐字段比较用）。
        target_wabil_before: game_svr::ability::Ability,
    }

    impl B5Rig {
        fn new(
            magic: mir2_data::MagicInfo,
            magic_level: u8,
            with_amulet_dura: Option<u16>,
        ) -> Self {
            use std::collections::HashMap;
            let magic_id = magic.magic_id;
            let mut world = mir2_world::World::new(64, 64);
            let caster = world.add_entity(new_player_entity("caster".to_string(), 10, 10));
            // 合同 §3.0：观察者必须**移出 y=10 扫描线**（9/10 的穿透沿 y=10 逐格扫）。
            let observer = world.add_entity(new_player_entity("obs".to_string(), 11, 9));
            let far = world.add_entity(new_player_entity("far".to_string(), 40, 40));
            {
                let e = world.entities.get_mut(caster).unwrap();
                e.level = 60;
                e.attack_mode = 0; // HAM_ALL
                e.luck = 0;
                e.power_rate = 100;
                e.bo_power_item = false;
                e.hp = 100;
                e.max_hp = 100;
                e.ob_mode = false;
                e.fixed_hide_mode = false;
            }
            for id in [observer, far] {
                if let Some(e) = world.entities.get_mut(id) {
                    e.level = 45;
                    e.ob_mode = false;
                    e.fixed_hide_mode = false;
                }
            }
            world.tick();
            let mut displays = downlink::DisplayTable::new();
            displays.set(
                caster,
                downlink::ActorDisplay::new(4, 0, 111, 0, 0, 255, b"caster".to_vec()),
            );
            displays.set(
                observer,
                downlink::ActorDisplay::new(4, 0, 112, 0, 0, 255, b"obs".to_vec()),
            );
            displays.set(
                far,
                downlink::ActorDisplay::new(4, 0, 113, 0, 0, 255, b"far".to_vec()),
            );
            let mut online: OnlineRegistry = Vec::new();
            for (i, (name, socket, actor)) in [
                ("caster", 911, caster),
                ("obs", 912, observer),
                ("far", 914, far),
            ]
            .into_iter()
            .enumerate()
            {
                online_set(
                    &mut online,
                    OnlineEntry {
                        account: format!("u{i}"),
                        chr_name: name.into(),
                        session_id: 10 + i32::try_from(i).unwrap_or(0),
                        gate_idx: 0,
                        socket,
                        actor_id: actor,
                    },
                );
            }
            let (tx0, rx) = mpsc::unbounded_channel::<SimToGate>();
            let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
            gates.insert(0, tx0);
            let mut record = stage6_record();
            record.data.magic = Some(vec![Some(record::MagicRcd {
                mag_idx: magic_id,
                level: magic_level,
                magic_key: u16::from(b'm'),
                tran_point: 0,
            })]);
            let mut saves: HashMap<String, SavedHuman> = HashMap::new();
            saves.insert(
                "caster".into(),
                SavedHuman {
                    account: "u0".into(),
                    record,
                    enter_map: "0".into(),
                },
            );
            let mut catalog = game_svr::ability::StdItemCatalog::new();
            // 护身符（36）：`StdMode=25 / Shape=5`（`MagicBase.cs:55-77`）；索引 1。
            catalog.insert(
                1,
                mir2_data::StdItem {
                    name: "护身符".into(),
                    std_mode: 25,
                    shape: 5,
                    ..mir2_data::StdItem::default()
                },
            );
            // 目标武器（36 的 `recalc_abilitys` 输入）：`DC=0x0400`；索引 2。
            catalog.insert(
                2,
                mir2_data::StdItem {
                    name: "木剑".into(),
                    std_mode: 5,
                    shape: 0,
                    weight: 0,
                    ac: 0,
                    dc: 0x0400,
                    ..mir2_data::StdItem::default()
                },
            );
            let mut ground_sessions: HashMap<String, SessionGround> = HashMap::new();
            let mut sg = spell_session_ground(caster);
            sg.state.wabil.level = 60;
            sg.state.wabil.hp = 100;
            sg.state.wabil.max_hp = 100;
            sg.state.wabil.mp = 1000;
            sg.state.wabil.max_mp = 1000;
            sg.state.wabil.dc = 0x0A05;
            sg.state.wabil.mc = 0x0A06;
            sg.state.wabil.sc = 0x0A06;
            sg.show_hp = false;
            if let Some(dura) = with_amulet_dura {
                sg.use_items[game_svr::ability::SLOT_ARMRING_L] = Some(game_svr::bag::BagItem {
                    make_index: 1,
                    index: 1,
                    dura,
                    dura_max: 1000,
                    desc: [0; 14],
                });
            }
            ground_sessions.insert("caster".into(), sg);
            // 36 的目标（观察者 = 玩家 2000）：按合同 §3.4/§5 钉死全量重算输入，使
            // `recalc_abilitys` 产出 `dc = 0x0A05`。
            let mut tsg = spell_session_ground(observer);
            tsg.equip.job = 1;
            tsg.equip.abil = game_svr::ability::Ability {
                level: 45,
                ..game_svr::ability::Ability::default()
            };
            tsg.equip.bonus_abil = game_svr::ability::NakedAbility {
                dc: 0,
                mc: 0,
                sc: 0,
                ac: 0,
                mac: 0,
                hp: 0,
                mp: 0,
                hit: 0,
                speed: 0,
                reserved: 0,
            };
            tsg.equip.bonus_tick_hit = 20;
            tsg.equip.bonus_tick_speed = 35;
            tsg.use_items = vec![None; game_svr::ability::USE_ITEMS_LEN];
            tsg.use_items[game_svr::ability::SLOT_WEAPON] = Some(game_svr::bag::BagItem {
                make_index: 1,
                index: 2,
                dura: 1000,
                dura_max: 1000,
                desc: [0; 14],
            });
            tsg.state.item_list = Vec::new();
            tsg.sub = game_svr::ability::SubAbility::first_call();
            tsg.state.wabil.hp = 100;
            tsg.state.wabil.mp = 100;
            tsg.show_hp = false;
            tsg.state.gold = 1234;
            tsg.game_gold = 7;
            recalc_session_ability(&mut tsg, &catalog, None, None);
            assert_eq!(
                tsg.state.wabil.dc, 0x0A05,
                "B5Rig 自检：目标全量重算必须产出 dc=0x0A05（合同 §3.4）"
            );
            tsg.state.wabil.hp = 100;
            tsg.state.wabil.mp = 100;
            let target_wabil_before = tsg.state.wabil.clone();
            ground_sessions.insert("obs".into(), tsg);
            let magic_table = magics::MagicTable::new(vec![magic]);
            Self {
                world,
                caster,
                observer,
                _far: far,
                online,
                saves,
                ground_sessions,
                magic_table,
                displays,
                catalog,
                gates,
                rx,
                target_wabil_before,
            }
        }

        /// 所有 spawn/tick 完成后再播种（合同 §3.0）。
        fn seed(&mut self, pre_draws: usize) {
            assert!(!self.world.attack_isolation_enabled());
            self.world.rng = mir2_shared::rng::RandomNumber::with_seed(B5_SEED);
            for _ in 0..pre_draws {
                let _ = self.world.rng.random_below(0);
            }
        }

        fn cast(&mut self, magic_id: u16, click: (i32, i32), target_actor_id: i32) {
            let pet_cfg = mir2_data::pet_slave::PetSlaveConfig::default();
            let table = game_svr::mongen::MonsterTable::new(Vec::new());
            let registry = mir2_envir::MapRegistry::from_entries(
                mir2_envir::MapLoader::new(".", "map", "envir"),
                Vec::new(),
            );
            handle_spell_cmd(
                game_svr::feature::make_long((click.0 as i16) as u16, (click.1 as i16) as u16),
                magic_id,
                u16::try_from(target_actor_id).unwrap_or(0),
                0,
                "caster",
                911,
                &self.online,
                &mut self.world,
                &mut self.saves,
                &mut self.ground_sessions,
                &self.catalog,
                &self.magic_table,
                &pet_cfg,
                8,
                Some(&registry),
                &table,
                &mut self.displays,
                &self.gates,
                1,
                1,
                2,
            );
        }

        fn drain(&mut self) -> Vec<SfFrame> {
            let mut frames = Vec::new();
            while let Ok(m) = self.rx.try_recv() {
                if let SimToGate::SendFrame { socket, body } = m {
                    frames.push((socket, body));
                }
            }
            frames
        }

        /// 推进时钟并投递到点的自身延时消息（36 的 640 / 9/10 的 RM_MAGSTRUCK）。
        fn deliver(&mut self, advance_ms: i64) -> Vec<SfFrame> {
            self.world.clock_ms += advance_ms;
            let outs = self.world.deliver_self_delay_msgs();
            let rec = mir2_world::TickRecord {
                slave_self_deliveries: outs,
                ..Default::default()
            };
            drain_b5_self_deliveries(
                &mut self.world,
                &self.online,
                &self.displays,
                &mut self.ground_sessions,
                &self.gates,
            );
            drain_b3_self_deliveries(
                &rec,
                &self.world,
                &self.online,
                &mut self.ground_sessions,
                &self.gates,
            );
            self.drain()
        }

        /// 推进时钟并跑地图事件处理器；顺带交付 `RM_MAGSTRUCK_MINE`。
        fn run_events(&mut self, advance_ms: i64) -> Vec<SfFrame> {
            self.world.clock_ms += advance_ms;
            self.world.run_map_events();
            let mut buf = SpellFrameBuf::new();
            drain_mag_struck_b2(
                &mut self.world,
                &self.online,
                &self.displays,
                &mut self.ground_sessions,
                &mut buf,
            );
            buf.flush(&self.online, &self.gates);
            self.drain()
        }

        fn add_monster(&mut self, name: &str, x: i32, y: i32, level: u8, anti_magic: u16) -> i32 {
            let mut e = mir2_world::Entity::new(0, name.to_string(), x, y);
            e.race = 80;
            e.level = level;
            e.hp = 100;
            e.max_hp = 100;
            e.life_attrib = 0;
            e.anti_magic = anti_magic;
            e.mac = 0;
            e.rush_mode = false;
            e.ai.animal = false;
            e.ai.target_creature = None;
            e.master = None;
            e.admin_mode = false;
            e.stone_mode = false;
            let id = self.world.add_entity(e);
            self.world.tick();
            self.displays.set(
                id,
                downlink::ActorDisplay::new(4, 0, 220, 0, 0, 255, name.as_bytes().to_vec()),
            );
            id
        }

        fn add_player(&mut self, name: &str, x: i32, y: i32, socket: i32) -> i32 {
            let mut e = new_player_entity(name.to_string(), x, y);
            e.level = 10;
            e.anti_magic = 0;
            e.mac = 0;
            let id = self.world.add_entity(e);
            self.world.tick();
            self.displays.set(
                id,
                downlink::ActorDisplay::new(4, 0, 230, 0, 0, 255, name.as_bytes().to_vec()),
            );
            online_set(
                &mut self.online,
                OnlineEntry {
                    account: name.into(),
                    chr_name: name.into(),
                    session_id: socket,
                    gate_idx: 0,
                    socket,
                    actor_id: id,
                },
            );
            id
        }

        fn mp(&self) -> u16 {
            self.ground_sessions["caster"].state.wabil.mp
        }

        fn tran_point(&self) -> i32 {
            self.saves["caster"].record.data.magic.as_ref().unwrap()[0]
                .as_ref()
                .unwrap()
                .tran_point
        }

        fn tran_level(&self) -> u8 {
            self.saves["caster"].record.data.magic.as_ref().unwrap()[0]
                .as_ref()
                .unwrap()
                .level
        }

        fn delay_msgs(&self, ident: u16) -> Vec<&mir2_world::slave::SelfDelayMsg> {
            self.world
                .self_delay_msgs
                .iter()
                .filter(|m| m.ident == ident)
                .collect()
        }

        fn amulet_dura(&self) -> Option<u16> {
            self.ground_sessions["caster"].use_items[game_svr::ability::SLOT_ARMRING_L]
                .as_ref()
                .map(|i| i.dura)
        }
    }

    /// 按期望 max 序回放 `before`，逐抽返回 `(max,result)`，并要求末态 == `after`。
    fn b5_ledger(
        before: &mir2_shared::rng::RandomNumber,
        after: &mir2_shared::rng::RandomNumber,
        maxes: &[i32],
    ) -> Vec<(i32, i32)> {
        let mut probe = before.clone();
        let mut out = Vec::with_capacity(maxes.len());
        for &m in maxes {
            out.push((m, probe.random_below(m)));
        }
        assert_eq!(
            format!("{probe:?}"),
            format!("{after:?}"),
            "RNG 末态与期望 max 序不一致（多抽/少抽/换序）"
        );
        out
    }

    fn b5_cmd(body: &[u8]) -> mir2_protocol::frame::CommandMessage {
        mir2_protocol::frame::CommandMessage::from_bytes(body).unwrap()
    }

    /// **F9-A/B/C + F10-A/B/C**：穿透的逐抽、终点帧、死格跳过、×1.5 复合、投递 tick。
    #[test]
    fn spell_p3b5_9_10_pass_through_draws_compounding_and_frames() {
        const SM_17: u16 = mir2_protocol::messages::SM_SPELL;
        const SM_31: u16 = mir2_protocol::messages::SM_STRUCK;
        const SM_53: u16 = mir2_protocol::messages::SM_HEALTHSPELLCHANGED;
        const SM_638: u16 = mir2_protocol::messages::SM_MAGICFIRE;
        const SM_640: u16 = mir2_protocol::messages::SM_MAGIC_LVEXP;
        const RM_MAGSTRUCK: u16 = mir2_world::slave::RM_MAGSTRUCK;

        // ---- F9-A：M1 命中、M2 骰门失败、M3 死格 ----
        {
            let mut rig = B5Rig::new(b5_magic_info(9), 2, None);
            let m1 = rig.add_monster("m1", 12, 10, 30, 0);
            let _m2 = rig.add_monster("m2", 14, 10, 30, 10);
            let _m3 = rig.add_monster("m3", 13, 10, 30, 0);
            rig.world.entities.get_mut(_m3).unwrap().death = true;
            rig.seed(0);
            let before = rig.world.rng.clone();
            rig.cast(9, (14, 10), 0);
            let frames = rig.drain();
            let got = b5_ledger(&before, &rig.world.rng, &[0, 0, 6, 10, 10, 10, 3]);
            assert_eq!(
                got,
                vec![(0, 0), (0, 0), (6, 1), (10, 4), (10, 4), (10, 8), (3, 0)],
                "F9-A 取数账本"
            );
            assert_eq!(rig.tran_point(), 1, "尾 R(3)=0 ⇒ TranPoint=1");
            assert_eq!(rig.tran_level(), 2);
            assert_eq!(
                sf_seq(&frames, 911),
                vec![SM_53, SM_638],
                "施法者出队序 17 → 53 → 638（640 在 +1s）"
            );
            assert_eq!(sf_seq(&frames, 912), vec![SM_17, SM_638], "观察者 17 → 638");
            assert_eq!(sf_count(&frames, 914, SM_17), 0, "±12 外无帧");
            let fire = b5_cmd(sf_first(&frames, 911, SM_638));
            assert_eq!(
                (fire.param, fire.tag),
                (15, 10),
                "638 尾坐标 = 穿透终点 (15,10)"
            );
            // 恰一条 600ms `RM_MAGSTRUCK`（目标 M1、power=24、actor_ref=施法者）。
            let delays = rig.delay_msgs(RM_MAGSTRUCK);
            assert_eq!(delays.len(), 1, "M2 骰门失败 ⇒ 只有 M1 一条延迟帧");
            assert_eq!(delays[0].actor_id, m1);
            assert_eq!(delays[0].n_param1, 24, "nPower=24");
            assert_eq!(delays[0].actor_ref, rig.caster);
            // 投递 tick：R(1000)=656（怪物 walk）、R(1)=0（MAC=0）⇒ dmg 24。
            let after_cast = rig.world.rng.clone();
            let frames = rig.deliver(600);
            let got = b5_ledger(&after_cast, &rig.world.rng, &[1000, 1]);
            assert_eq!(got, vec![(1000, 656), (1, 0)], "F9-A 投递 tick 承接同一流");
            let struck = sf_first(&frames, 911, SM_31);
            let cmd = b5_cmd(struck);
            assert_eq!(cmd.recog, m1, "31 的 recog = 受击怪");
            assert_eq!(cmd.series, 24, "31 的伤害 = 24");
            assert!(sf_count(&frames, 912, SM_31) == 1, "观察者也收 31");
            // +1000ms 的 640（优先级 255）。
            let frames = rig.deliver(400);
            let seq = sf_seq(&frames, 911);
            assert_eq!(seq, vec![SM_640], "640 在 +1s");
            let c = b5_cmd(sf_first(&frames, 911, SM_640));
            assert_eq!((c.recog, c.param, c.tag), (9, 2, 1));
        }

        // ---- F9-B：GetNextPosition(...,1) 失败 ⇒ 零抽、无 640、638 用点击点 ----
        {
            let mut rig = B5Rig::new(b5_magic_info(9), 2, None);
            rig.world.entities.get_mut(rig.caster).unwrap().x = 0;
            rig.seed(0);
            let before = rig.world.rng.clone();
            rig.cast(9, (-2, 10), 0);
            let frames = rig.drain();
            assert_eq!(b5_ledger(&before, &rig.world.rng, &[]), vec![], "零抽");
            assert_eq!(rig.tran_point(), 0);
            assert_eq!(sf_seq(&frames, 911), vec![SM_53, SM_638]);
            let c = b5_cmd(sf_first(&frames, 911, SM_638));
            assert_eq!(
                (c.param, c.tag),
                (0xFFFE, 10),
                "失败支 638 保留点击坐标（i16 -2 = 0xFFFE）"
            );
            let frames = rig.deliver(1000);
            assert_eq!(sf_count(&frames, 911, SM_640), 0, "boTrain=false ⇒ 无 640");
        }

        // ---- F9-C：死格跳过 + 尾 R(3)=2 ----
        {
            let mut rig = B5Rig::new(b5_magic_info(9), 2, None);
            let _m1 = rig.add_monster("m1", 12, 10, 30, 0);
            let m3 = rig.add_monster("m3", 13, 10, 30, 0);
            rig.world.entities.get_mut(m3).unwrap().death = true;
            rig.seed(0);
            let before = rig.world.rng.clone();
            rig.cast(9, (14, 10), 0);
            let _ = rig.drain();
            let got = b5_ledger(&before, &rig.world.rng, &[0, 0, 6, 10, 10, 3]);
            assert_eq!(
                got,
                vec![(0, 0), (0, 0), (6, 1), (10, 4), (10, 4), (3, 2)],
                "死格不抽 R(10)"
            );
            assert_eq!(rig.tran_point(), 3, "R(3)=2 ⇒ TranPoint=3");
        }

        // ---- F10-A：三击 ×1.5 逐击复合 ----
        {
            let mut rig = B5Rig::new(b5_magic_info(10), 2, None);
            let m1 = rig.add_monster("m1", 12, 10, 30, 0);
            let m2 = rig.add_monster("m2", 15, 10, 30, 0);
            let m3 = rig.add_monster("m3", 17, 10, 30, 0);
            let dead = rig.add_monster("m4", 13, 10, 30, 0);
            rig.world.entities.get_mut(dead).unwrap().death = true;
            rig.seed(0);
            let before = rig.world.rng.clone();
            rig.cast(10, (16, 10), 0);
            let frames = rig.drain();
            let got = b5_ledger(&before, &rig.world.rng, &[0, 0, 6, 10, 10, 10, 10, 3]);
            assert_eq!(
                got,
                vec![
                    (0, 0),
                    (0, 0),
                    (6, 1),
                    (10, 4),
                    (10, 4),
                    (10, 8),
                    (10, 2),
                    (3, 1)
                ],
                "F10-A 取数账本"
            );
            assert_eq!(rig.tran_point(), 2);
            assert_eq!(sf_seq(&frames, 911), vec![SM_53, SM_638]);
            let c = b5_cmd(sf_first(&frames, 911, SM_638));
            assert_eq!((c.param, c.tag), (18, 10), "10 的终点步长 = 8 ⇒ (18,10)");
            let delays = rig.delay_msgs(RM_MAGSTRUCK);
            assert_eq!(delays.len(), 3);
            let powers: Vec<i32> = delays.iter().map(|d| d.n_param1).collect();
            assert_eq!(powers, vec![42, 63, 95], "Round 逐击复合 28→42→63→95");
            assert_eq!(
                delays.iter().map(|d| d.actor_id).collect::<Vec<_>>(),
                vec![m1, m2, m3]
            );
            let after_cast = rig.world.rng.clone();
            let frames = rig.deliver(600);
            let got = b5_ledger(&after_cast, &rig.world.rng, &[1000, 1, 1000, 1, 1000, 1]);
            assert_eq!(
                got,
                vec![(1000, 147), (1, 0), (1000, 42), (1, 0), (1000, 222), (1, 0)],
                "F10-A 投递 tick"
            );
            let mut damages: Vec<u16> = frames
                .iter()
                .filter(|(s, _)| *s == 911)
                .filter(|(_, b)| sf_ident(b) == SM_31)
                .map(|(_, b)| b5_cmd(b).series)
                .collect();
            damages.sort_unstable();
            assert_eq!(damages, vec![42, 63, 95], "31 的三条伤害");
        }

        // ---- F10-B：仅 M1、骰门失败 ⇒ 无尾抽、无延迟帧 ----
        {
            let mut rig = B5Rig::new(b5_magic_info(10), 2, None);
            let _m1 = rig.add_monster("m1", 12, 10, 30, 10);
            rig.seed(0);
            let before = rig.world.rng.clone();
            rig.cast(10, (16, 10), 0);
            let frames = rig.drain();
            let got = b5_ledger(&before, &rig.world.rng, &[0, 0, 6, 10, 10]);
            assert_eq!(
                got,
                vec![(0, 0), (0, 0), (6, 1), (10, 4), (10, 4)],
                "骰门失败 ⇒ tcount=0 ⇒ 无尾抽"
            );
            assert!(rig.delay_msgs(RM_MAGSTRUCK).is_empty());
            let frames2 = rig.deliver(1000);
            assert_eq!(
                sf_count(&frames, 911, SM_640) + sf_count(&frames2, 911, SM_640),
                0
            );
        }

        // ---- F10-C：边界失败 ----
        {
            let mut rig = B5Rig::new(b5_magic_info(10), 2, None);
            rig.world.entities.get_mut(rig.caster).unwrap().x = 0;
            rig.seed(0);
            let before = rig.world.rng.clone();
            rig.cast(10, (-2, 10), 0);
            let _frames = rig.drain();
            assert_eq!(b5_ledger(&before, &rig.world.rng, &[]), vec![]);
        }
    }

    /// **F22-A/B/C/D**：火墙的顺序、安全区 100、中心占用、配置门、事件伤害。
    #[test]
    fn spell_p3b5_22_fire_wall_events_safe_zone_and_occupied_center() {
        const SM_31: u16 = mir2_protocol::messages::SM_STRUCK;
        const SM_53: u16 = mir2_protocol::messages::SM_HEALTHSPELLCHANGED;
        const SM_100: u16 = mir2_protocol::messages::SM_SYSMESSAGE;
        const SM_638: u16 = mir2_protocol::messages::SM_MAGICFIRE;
        const SM_640: u16 = mir2_protocol::messages::SM_MAGIC_LVEXP;

        // ---- F22-A：5 格全空、固定顺序、事件参数 ----
        {
            let mut rig = B5Rig::new(b5_magic_info(22), 2, None);
            rig.world.clock_ms = 10_000; // 事件 3000ms 门（uptime > 3000）
            rig.seed(0);
            let before = rig.world.rng.clone();
            rig.cast(22, (10, 13), 0);
            let frames = rig.drain();
            let got = b5_ledger(&before, &rig.world.rng, &[0, 0, 6, 10, 0, 5, 3]);
            assert_eq!(
                got,
                vec![(0, 0), (0, 0), (6, 1), (10, 4), (0, 0), (5, 4), (3, 0)],
                "F22-A 取数账本"
            );
            assert_eq!(rig.tran_point(), 1);
            assert_eq!(sf_seq(&frames, 911), vec![SM_53, SM_638]);
            let evs: Vec<(i32, i32, i32, i32)> = rig
                .world
                .fire_burn_events
                .iter()
                .map(|e| (e.x, e.y, e.damage, e.continue_ms))
                .collect();
            assert_eq!(
                evs,
                vec![
                    (10, 12, 12, 16_000),
                    (9, 13, 12, 16_000),
                    (10, 13, 12, 16_000),
                    (11, 13, 12, 16_000),
                    (10, 14, 12, 16_000)
                ],
                "固定顺序 上/左/中/右/下（nDamage=12、time=16 ⇒ 16000ms）"
            );
            let frames = rig.deliver(1000);
            assert_eq!(sf_count(&frames, 911, SM_640), 1, "boTrain=true ⇒ 640");
        }

        // ---- F22-B：安全区门（配置开）⇒ 抽数已发生、0 事件、100 帧 ----
        {
            let mut rig = B5Rig::new(b5_magic_info(22), 2, None);
            rig.world.clock_ms = 10_000;
            rig.world.entities.get_mut(rig.caster).unwrap().in_safe_zone = true;
            rig.world.set_b5_config(mir2_world::magic_effect::B5Config {
                disable_in_safe_zone_fire_cross: true,
                ..mir2_world::magic_effect::B5Config::default()
            });
            rig.seed(0);
            let before = rig.world.rng.clone();
            rig.cast(22, (10, 13), 0);
            let frames = rig.drain();
            let got = b5_ledger(&before, &rig.world.rng, &[0, 0, 6, 10, 0, 5]);
            assert_eq!(
                got,
                vec![(0, 0), (0, 0), (6, 1), (10, 4), (0, 0), (5, 4)],
                "安全区门在实参求值之后 ⇒ 6 抽、无尾抽"
            );
            assert_eq!(rig.world.fire_burn_events.len(), 0, "安全区 ⇒ 0 事件");
            assert_eq!(
                sf_seq(&frames, 911),
                vec![SM_53, SM_638, SM_100],
                "施法者出队序 17 → 53 → 638 → 100（无 640）"
            );
            let msg = b5_cmd(sf_first(&frames, 911, SM_100));
            assert_eq!(msg.recog, rig.caster);
            assert_eq!(msg.param, 0x38FF, "Red 前景/背景 0xFF/0x38");
            assert_eq!(msg.series, 1);
            let text = mir2_protocol::edcode::decode(&sf_first(&frames, 911, SM_100)[12..]);
            assert_eq!(
                text, b"\xb0\xb2\xc8\xab\xc7\xf8\xb2\xbb\xd4\xca\xd0\xed\xca\xb9\xd3\xc3...",
                "文本 = 安全区不允许使用..."
            );
            let frames = rig.deliver(1000);
            assert_eq!(sf_count(&frames, 911, SM_640), 0, "boTrain=false ⇒ 无 640");
        }

        // ---- F22-C：中心已注册事件 ⇒ 只新增 4 个、boTrain 仍 true ----
        {
            let mut rig = B5Rig::new(b5_magic_info(22), 2, None);
            rig.world.clock_ms = 10_000;
            // 预置必须走 ctor + AddMapEvent（同时写 Event 格对象与管理器 id=0）。
            rig.world
                .add_fire_burn_event(rig.caster, 0, 10, 13, 12, 16_000);
            assert!(rig.world.event_registered);
            rig.seed(0);
            let before = rig.world.rng.clone();
            rig.cast(22, (10, 13), 0);
            let _ = rig.drain();
            assert_eq!(
                b5_ledger(&before, &rig.world.rng, &[0, 0, 6, 10, 0, 5, 3]),
                vec![(0, 0), (0, 0), (6, 1), (10, 4), (0, 0), (5, 4), (3, 0)]
            );
            assert_eq!(rig.world.fire_burn_events.len(), 5, "预置 1 + 新增 4");
            let coords: Vec<(i32, i32)> = rig
                .world
                .fire_burn_events
                .iter()
                .skip(1)
                .map(|e| (e.x, e.y))
                .collect();
            assert_eq!(coords, vec![(10, 12), (9, 13), (11, 13), (10, 14)]);
            let frames = rig.deliver(1000);
            assert_eq!(
                sf_count(&frames, 911, SM_640),
                1,
                "boTrain 与「是否新建」无关 ⇒ 640 照发"
            );
        }

        // ---- F22-D：安全区 + 配置 false ⇒ 5 个事件照建 ----
        {
            let mut rig = B5Rig::new(b5_magic_info(22), 2, None);
            rig.world.clock_ms = 10_000;
            rig.world.entities.get_mut(rig.caster).unwrap().in_safe_zone = true;
            rig.world.set_b5_config(mir2_world::magic_effect::B5Config {
                disable_in_safe_zone_fire_cross: false,
                ..mir2_world::magic_effect::B5Config::default()
            });
            rig.seed(0);
            rig.cast(22, (10, 13), 0);
            let _ = rig.drain();
            assert_eq!(rig.world.fire_burn_events.len(), 5, "配置 false ⇒ 门不生效");
        }

        // ---- 事件 tick：首次 Run ≈ +500ms、MINE 无 R(1000)、伤害 12 ----
        {
            let mut rig = B5Rig::new(b5_magic_info(22), 2, None);
            rig.world.clock_ms = 10_000;
            let victim = rig.add_monster("v", 10, 13, 30, 0);
            rig.seed(0);
            rig.cast(22, (10, 13), 0);
            let _ = rig.drain();
            // RunTick=500 严格大于 ⇒ +501 起跳；500ms 内不跑。
            let _ = rig.run_events(500);
            assert!(rig.world.pending_mag_struck.is_empty(), "500ms 门未过");
            let after_cast = rig.world.rng.clone();
            let frames = rig.run_events(100);
            // MINE：无 R(1000)，只有 MSD 的 R(1)（MAC=0）。
            let got = b5_ledger(&after_cast, &rig.world.rng, &[1]);
            assert_eq!(got, vec![(1, 0)], "MINE 投递只抽 MSD");
            let cmd = b5_cmd(sf_first(&frames, 911, SM_31));
            assert_eq!(cmd.recog, victim);
            assert_eq!(cmd.series, 12, "事件伤害 = 12");
        }
    }

    /// **F36-A/B/C/D/E**：无极真气的护身符、友方门、52/100/642 帧与优先级。
    #[test]
    fn spell_p3b5_36_uenhancer_frames_amulet_and_gates() {
        const SM_17: u16 = mir2_protocol::messages::SM_SPELL;
        const SM_52: u16 = mir2_protocol::messages::SM_ABILITY;
        const SM_53: u16 = mir2_protocol::messages::SM_HEALTHSPELLCHANGED;
        const SM_100: u16 = mir2_protocol::messages::SM_SYSMESSAGE;
        const SM_638: u16 = mir2_protocol::messages::SM_MAGICFIRE;
        const SM_639: u16 = mir2_protocol::messages::SM_MAGICFIRE_FAIL;
        const SM_640: u16 = mir2_protocol::messages::SM_MAGIC_LVEXP;
        const SM_642: u16 = mir2_protocol::messages::SM_DURACHANGE;

        // ---- F36-A：独立玩家目标 ----
        {
            let mut rig = B5Rig::new(b5_magic_info(36), 2, Some(600));
            rig.seed(0);
            let before = rig.world.rng.clone();
            rig.cast(36, (11, 9), rig.observer);
            let frames = rig.drain();
            let got = b5_ledger(&before, &rig.world.rng, &[2, 0, 6, 10, 3]);
            assert_eq!(
                got,
                vec![(2, 1), (0, 0), (6, 1), (10, 4), (3, 1)],
                "F36-A 取数账本"
            );
            assert_eq!(rig.tran_point(), 2);
            assert_eq!(rig.tran_level(), 2);
            assert_eq!(rig.mp(), 979, "GetSpellPoint(36)=21 ⇒ MP 1000→979");
            assert_eq!(
                sf_seq(&frames, 911),
                vec![SM_53, SM_638, SM_642],
                "caster 出队序 17 → 53 → 638 → 642"
            );
            assert_eq!(
                sf_seq(&frames, 912),
                vec![SM_17, SM_52, SM_638, SM_100],
                "target 出队序 17 → 52 → 638 → 100"
            );
            let dura = b5_cmd(sf_first(&frames, 911, SM_642));
            assert_eq!((dura.recog, dura.param, dura.tag), (500, 5, 1000));
            assert_eq!(rig.amulet_dura(), Some(500));
            let msg = b5_cmd(sf_first(&frames, 912, SM_100));
            assert_eq!(
                (msg.recog, msg.param, msg.series),
                (rig.observer, 0xFFDB, 1)
            );
            let text = mir2_protocol::edcode::decode(&sf_first(&frames, 912, SM_100)[12..]);
            assert_eq!(
                text,
                b"\xce\xef\xc0\xed\xb9\xa5\xbb\xf7\xc1\xa6\xd4\xf6\xbc\xd31\xb7\xd6\xd6\xd35\x37\xc3\xeb ",
                "文本 = 物理攻击力增加1分钟57秒 "
            );
            let ability = b5_cmd(sf_first(&frames, 912, SM_52));
            assert_eq!(ability.recog, 1234, "52 的 Gold");
            assert_eq!(ability.param, 0x6301, "52 的 MakeWord(Job,99)");
            assert_eq!((ability.tag, ability.series), (7, 0), "52 的 GameGold");
            let tail = &sf_first(&frames, 912, SM_52)[12..];
            assert_eq!(
                tail,
                &mir2_protocol::edcode::encode(&record::encode_ability_client(
                    &rig.ground_sessions["obs"].state.wabil
                )),
                "52 尾 = 重算后的整个 WAbil（58B 客户端布局）"
            );
            let after = &rig.ground_sessions["obs"].state.wabil;
            assert_eq!(after.dc, 0x0E05, "DC 高字节 10 + nPower 4 = 14");
            assert_eq!(after.mc, rig.target_wabil_before.mc);
            assert_eq!(after.sc, rig.target_wabil_before.sc);
            assert_eq!(after.max_hp, rig.target_wabil_before.max_hp);
            assert_eq!(after.max_mp, rig.target_wabil_before.max_mp);
            assert_eq!(after.hp, 100);
            let frames = rig.deliver(1000);
            let c = b5_cmd(sf_first(&frames, 911, SM_640));
            assert_eq!((c.recog, c.param, c.tag), (36, 2, 2));
        }

        // ---- F36-F：Dura==100 ⇒ 删除支（无 642、发 202、清槽） ----
        {
            let mut rig = B5Rig::new(b5_magic_info(36), 2, Some(100));
            rig.seed(0);
            let before = rig.world.rng.clone();
            rig.cast(36, (11, 9), rig.observer);
            let frames = rig.drain();
            assert_eq!(
                b5_ledger(&before, &rig.world.rng, &[2, 0, 6, 10, 3]),
                vec![(2, 1), (0, 0), (6, 1), (10, 4), (3, 1)],
                "删除支仍完成全部抽数"
            );
            assert_eq!(rig.amulet_dura(), None, "Dura==100 ⇒ 扣光并清槽");
            assert_eq!(sf_count(&frames, 911, SM_642), 0, "删除支不得发 642");
            assert_eq!(
                sf_count(&frames, 911, mir2_protocol::messages::SM_DELITEM),
                1,
                "删除支发 SM_DELITEM(202)"
            );
        }

        // ---- F36-B：Level=0 仍推进 R(0) ----
        {
            let mut rig = B5Rig::new(b5_magic_info(36), 0, Some(600));
            rig.seed(0);
            let before = rig.world.rng.clone();
            rig.cast(36, (11, 9), rig.observer);
            let frames = rig.drain();
            let got = b5_ledger(&before, &rig.world.rng, &[0, 0, 6, 10, 3]);
            assert_eq!(
                got,
                vec![(0, 0), (0, 0), (6, 1), (10, 4), (3, 1)],
                "Level=0 也抽 R(0)"
            );
            assert_eq!(rig.tran_point(), 2);
            // nPower=1、nTime=97 ⇒ "1分钟37秒"
            let text = mir2_protocol::edcode::decode(&sf_first(&frames, 912, SM_100)[12..]);
            assert_eq!(
                text,
                b"\xce\xef\xc0\xed\xb9\xa5\xbb\xf7\xc1\xa6\xd4\xf6\xbc\xd31\xb7\xd6\xd6\xd33\x37\xc3\xeb ",
                "97 ⇒ 1分钟37秒"
            );
        }

        // ---- F36-C：无护身符 ⇒ 零抽、恰一条 639、17 仍发 ----
        {
            let mut rig = B5Rig::new(b5_magic_info(36), 2, None);
            rig.seed(0);
            let before = rig.world.rng.clone();
            rig.cast(36, (11, 9), rig.observer);
            let frames = rig.drain();
            assert_eq!(b5_ledger(&before, &rig.world.rng, &[]), vec![], "零抽");
            assert_eq!(sf_seq(&frames, 911), vec![SM_53, SM_639]);
            assert_eq!(sf_count(&frames, 911, SM_639), 1);
            for ident in [SM_52, SM_100, SM_638, SM_640, SM_642] {
                assert_eq!(sf_count(&frames, 911, ident), 0, "无 {ident}");
            }
        }

        // ---- F36-D：非玩家目标 ⇒ 友方门拒绝、不耗护身符 ----
        {
            let mut rig = B5Rig::new(b5_magic_info(36), 2, Some(600));
            let mon = rig.add_monster("m", 12, 10, 30, 0);
            rig.seed(0);
            let before = rig.world.rng.clone();
            rig.cast(36, (12, 10), mon);
            let frames = rig.drain();
            assert_eq!(b5_ledger(&before, &rig.world.rng, &[]), vec![], "零抽");
            assert_eq!(sf_seq(&frames, 911), vec![SM_53, SM_639]);
            assert_eq!(rig.amulet_dura(), Some(600), "友方门先于 CheckAmulet");
        }

        // ---- F36-E：自施法（target==null）⇒ 单队列 17 → 52 → 53 → 638 → 642 → 100 ----
        {
            let mut rig = B5Rig::new(b5_magic_info(36), 2, Some(600));
            rig.seed(0);
            let before = rig.world.rng.clone();
            rig.cast(36, (10, 10), 0);
            let frames = rig.drain();
            assert_eq!(
                b5_ledger(&before, &rig.world.rng, &[2, 0, 6, 10, 3]),
                vec![(2, 1), (0, 0), (6, 1), (10, 4), (3, 1)]
            );
            assert_eq!(
                sf_seq(&frames, 911),
                vec![SM_52, SM_53, SM_638, SM_642, SM_100],
                "自施法单队列出队序（52=67 先于 53=68）"
            );
            let frames = rig.deliver(1000);
            assert_eq!(sf_count(&frames, 911, SM_640), 1);
        }

        // ---- F36-E2（must_fix）：自施法 click≠caster ⇒ 尾 638 用 caster 坐标 ----
        // oracle `MagicManager.cs:612-617`：`targetObject == null` 时 `nTargetX/nTargetY`
        // 被改写成 caster 的 `CurrX/CurrY`，与 click 无关；`SM_SPELL(17)`（`:159`，更早）
        // 仍用 click。click=(12,10)、caster=(10,10) ⇒ 17=(12,10)、638=(10,10)。
        {
            let mut rig = B5Rig::new(b5_magic_info(36), 2, Some(600));
            rig.seed(0);
            rig.cast(36, (12, 10), 0);
            let frames = rig.drain();
            let spell = b5_cmd(sf_first(&frames, 912, SM_17));
            assert_eq!((spell.param, spell.tag), (12, 10), "17 仍用 click 坐标");
            let fire = b5_cmd(sf_first(&frames, 911, SM_638));
            assert_eq!(
                (fire.param, fire.tag),
                (10, 10),
                "自施法 638 用归一后的 caster 坐标（不是 click (12,10)）"
            );
            assert_eq!(
                sf_magicfire_target_id(sf_first(&frames, 911, SM_638)),
                rig.caster,
                "638 的目标 id 也归一成 caster 自己"
            );
        }
    }

    /// **32 的同族组队门**：`IsProperTarget` 必须读**团长**的成员表（`attacker_group_members`）。
    ///
    /// 真实 party 布局：团长实体持成员表，成员只有 `group_owner` 指针。施法者是成员（非团长）。
    /// 目标 = 同组玩家且 `LifeAttrib=LA_UNDEAD`：
    /// - 正确（读团长表）⇒ 非 proper ⇒ 共享尾照发（638、无 640、无 639）；
    /// - 改回施法者自己的空表 ⇒ proper ⇒ `(AnimalObject)` 强转失败 ⇒ 639、无 638。
    #[test]
    fn spell_p3b5_32_group_gate_reads_leader_table() {
        const SM_53: u16 = mir2_protocol::messages::SM_HEALTHSPELLCHANGED;
        const SM_638: u16 = mir2_protocol::messages::SM_MAGICFIRE;
        const SM_639: u16 = mir2_protocol::messages::SM_MAGICFIRE_FAIL;

        let mut rig = B5Rig::new(b5_magic_info(32), 2, None);
        let ally = rig.add_player("ally", 11, 10, 913);
        let leader = rig.add_player("leader", 20, 20, 915);
        {
            let c = rig.world.entities.get_mut(rig.caster).unwrap();
            c.attack_mode = mir2_world::combat::ATTACK_MODE_HAM_GROUP;
            c.group_owner = leader;
            c.group_members = Vec::new(); // 真实成员布局：成员不自持表
            let a = rig.world.entities.get_mut(ally).unwrap();
            a.life_attrib = mir2_world::magic_effect::LA_UNDEAD;
            let l = rig.world.entities.get_mut(leader).unwrap();
            l.group_members = vec![leader, rig.caster, ally];
        }
        rig.seed(0);
        let before = rig.world.rng.clone();
        rig.cast(32, (11, 10), ally);
        let frames = rig.drain();
        assert_eq!(
            b5_ledger(&before, &rig.world.rng, &[]),
            vec![],
            "非 proper ⇒ 零抽"
        );
        assert_eq!(
            sf_seq(&frames, 911),
            vec![SM_53, SM_638],
            "非 proper ⇒ boSpellFail 保持 false ⇒ 共享尾 638（无 639/640）"
        );
        assert_eq!(sf_count(&frames, 911, SM_639), 0);

        // 非组队：同一目标 ⇒ proper ⇒ `(AnimalObject)` 防御臂 ⇒ 639、无 638。
        let mut rig = B5Rig::new(b5_magic_info(32), 2, None);
        let solo = rig.add_player("solo", 11, 10, 913);
        {
            let a = rig.world.entities.get_mut(solo).unwrap();
            a.life_attrib = mir2_world::magic_effect::LA_UNDEAD;
        }
        rig.seed(0);
        rig.cast(32, (11, 10), solo);
        let frames = rig.drain();
        assert_eq!(
            sf_seq(&frames, 911),
            vec![SM_53, SM_639],
            "proper + 玩家 ⇒ InvalidCast 防御臂 ⇒ 639、无尾"
        );
        assert_eq!(sf_count(&frames, 911, SM_638), 0);
    }
    // ==== 本批（AOI 卫士可见性 / VerifyMapTime）判据 ====

    /// 生成一只**静止**卫士（race 11；`is_guard_race` ⇒ `monster_ai_tick` 只跑
    /// `base_object_run_monster`，不游走/不索敌）。`spawn_monster_precomputed` 在**首个 tick 前**
    /// 直接落格（`CellObject.add_time = clock_ms`），复刻 Guardian 装载时机。
    fn spawn_static_guard(world: &mut mir2_world::World, x: i32, y: i32, dir: u8) -> i32 {
        world
            .spawn_monster_precomputed(
                "guard",
                x,
                y,
                0,
                11,
                10,
                0,
                100,
                0,
                0,
                0,
                0,
                0,
                0,
                Vec::new(),
                mir2_world::MonsterCtorDraws::default(),
                dir,
                false,
            )
            .expect("卫士生成/落格成功")
    }

    fn collect_frames(
        rx: &mut mpsc::UnboundedReceiver<SimToGate>,
        out: &mut Vec<(i32, u16, u16, u16, u16)>,
    ) {
        while let Ok(SimToGate::SendFrame { body, .. }) = rx.try_recv() {
            let cm = mir2_protocol::frame::CommandMessage::from_bytes(&body)
                .expect("SM_* body 至少 12B");
            out.push((cm.recog, cm.ident, cm.param, cm.tag, cm.series));
        }
    }

    fn test_online_gates(
        chr_name: &str,
        actor_id: i32,
    ) -> (
        OnlineRegistry,
        HashMap<u8, mpsc::UnboundedSender<SimToGate>>,
        mpsc::UnboundedReceiver<SimToGate>,
    ) {
        let mut online: OnlineRegistry = Vec::new();
        online_set(
            &mut online,
            OnlineEntry {
                account: "up".into(),
                chr_name: chr_name.into(),
                session_id: 1,
                gate_idx: 0,
                socket: 901,
                actor_id,
            },
        );
        let (tx0, rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        (online, gates, rx0)
    }

    /// **判据① + ②**：静态卫士 `(281,661)` + 玩家 `(291,666)`（Chebyshev 10 ≤ vr 12），
    /// 推进 400 tick × 200ms（80s，跨过两个 30s VerifyMapTime 刷新点）：
    /// - 卫士的 `CellObject` 仍在 `(281,661)` 格内；
    /// - 玩家可见集仍含卫士（`Show | Invisible`）；
    /// - 恰好**一对** `SM_TURN(recog=guard, param=281, tag=661)` + `SM_FEATURECHANGED(recog=guard)`，
    ///   且**没有** `SM_WALK`（卫士未移动）。
    ///
    /// 红检（本批牙①②）：删掉 `base_object_run_monster` 末尾的 `verify_map_time` ⇒ 60s 时卫士自己的
    /// AOI 扫描（非玩家 viewer）把过期格子项删掉 ⇒ 格子项断言/可见集断言必红；把
    /// `aoi.rs` 的 `!viewer_is_play &&` 改回去不会直接触发本条（verify 刷新使 add_time 不过期），
    /// 由 `aoi::tests::player_viewer_skips_cell_expiry` 单独钉住。
    #[test]
    fn vmt_static_guard_stays_visible_beyond_60s_one_appearance_pair() {
        let mut world = mir2_world::World::new(700, 700);
        world.enable_monster_ai();
        let guard = spawn_static_guard(&mut world, 281, 661, 5);
        world.open_session("p");
        let p = world
            .enter_map("p", new_player_entity("p".to_string(), 291, 666), 0)
            .expect("玩家进图");
        assert_eq!(
            world.entities.get(guard).map(|e| (e.x, e.y)),
            Some((281, 661))
        );

        let mut displays = downlink::DisplayTable::new();
        displays.set(
            guard,
            downlink::monster_display(5, &mir2_data::models::MonsterInfo::default()),
        );
        let (online, gates, mut rx) = test_online_gates("p", p);

        let mut frames: Vec<(i32, u16, u16, u16, u16)> = Vec::new();
        for _ in 0..400 {
            world.tick();
            let _ = drain_aoi_downlink(&world, &displays, &online, &gates);
            collect_frames(&mut rx, &mut frames);
        }
        assert_eq!(world.clock_ms, 80_000, "400 × 200ms");

        // ①-1 卫士格子项仍在（未被 60s 过期逐出）。
        let cell = world.map(0).cell(281, 661);
        assert!(
            cell.obj_list
                .iter()
                .any(|o| o.actor_object && o.cell_obj_id == guard),
            "80s 后卫士 CellObject 必须仍在 (281,661)：{cell:?}"
        );
        // ①-2 玩家可见集仍含卫士。
        let vis = world
            .entities
            .get(p)
            .expect("玩家存在")
            .visible_actors
            .iter()
            .any(|v| v.target == guard && v.flag != mir2_world::VisibleFlag::Hidden);
        assert!(vis, "玩家 visible_actors 必须仍含卫士");

        // ①-3 恰好一对出现帧；且没有 SM_WALK。
        let turn: Vec<_> = frames
            .iter()
            .filter(|f| f.0 == guard && f.1 == mir2_protocol::messages::SM_TURN)
            .collect();
        let feat: Vec<_> = frames
            .iter()
            .filter(|f| f.0 == guard && f.1 == mir2_protocol::messages::SM_FEATURECHANGED)
            .collect();
        assert_eq!(turn.len(), 1, "恰好一条 SM_TURN：{frames:?}");
        assert_eq!(feat.len(), 1, "恰好一条 SM_FEATURECHANGED：{frames:?}");
        assert_eq!(turn[0].2, 281, "SM_TURN.param = x");
        assert_eq!(turn[0].3, 661, "SM_TURN.tag = y");
        assert_eq!(turn[0].4 & 0xFF, 5, "SM_TURN.series 低字节 = dir");
        assert_eq!(
            frames
                .iter()
                .filter(|f| f.0 == guard && f.1 == mir2_protocol::messages::SM_WALK)
                .count(),
            0,
            "卫士静止，不得有 SM_WALK"
        );
    }

    /// **判据② 阴性对照**：到第 149 tick（29.8s）时还没过 30s 门 ⇒ `verify_tick`/`add_time`
    /// 均保持落格初值 0，且**不重复发**出现对（整段只有 1 对）。
    ///
    /// 红检：把 `verify_map_time` 的 `> VERIFY_MAP_TIME_MS` 改成 `>= 0`（每 tick 刷新）⇒ 本用例
    /// `verify_tick == 0` / `add_time == 0` 断言红（刷新本身不重复出帧，但时序口径错）。
    #[test]
    fn vmt_no_duplicate_appearance_before_30s_refresh() {
        let mut world = mir2_world::World::new(700, 700);
        world.enable_monster_ai();
        let guard = spawn_static_guard(&mut world, 281, 661, 5);
        world.open_session("p");
        let p = world
            .enter_map("p", new_player_entity("p".to_string(), 291, 666), 0)
            .expect("玩家进图");
        let mut displays = downlink::DisplayTable::new();
        displays.set(
            guard,
            downlink::monster_display(5, &mir2_data::models::MonsterInfo::default()),
        );
        let (online, gates, mut rx) = test_online_gates("p", p);

        let mut frames: Vec<(i32, u16, u16, u16, u16)> = Vec::new();
        for _ in 0..149 {
            world.tick();
            let _ = drain_aoi_downlink(&world, &displays, &online, &gates);
            collect_frames(&mut rx, &mut frames);
        }
        assert_eq!(world.clock_ms, 29_800, "149 × 200ms");
        assert_eq!(
            world.entities.get(guard).unwrap().verify_tick,
            0,
            "未到 30s 门不得刷新 VerifyTick"
        );
        let add_time = world
            .map(0)
            .cell(281, 661)
            .obj_list
            .iter()
            .find(|o| o.actor_object && o.cell_obj_id == guard)
            .expect("格子项")
            .add_time;
        assert_eq!(add_time, 0, "未到 30s 门不得刷新 AddTime");
        assert_eq!(
            frames
                .iter()
                .filter(|f| f.0 == guard && f.1 == mir2_protocol::messages::SM_TURN)
                .count(),
            1,
            "29.8s 内只发一次出现帧：{frames:?}"
        );
        assert_eq!(
            frames
                .iter()
                .filter(|f| f.0 == guard && f.1 == mir2_protocol::messages::SM_FEATURECHANGED)
                .count(),
            1
        );
    }

    /// **判据③**：固定 NPC（`NormNpc.Run` → `base.Run()`）与商人（`Merchant.Run` → `base.Run()`）
