    /// **PL-1 / P32 判据 1**：`HP==0 && !Death && LastHiter==null && Revival &&
    /// now-RevivalTick>RevivalTime` ⇒ `HP=MaxHP`、`RevivalTick=now`、戒指耐久 -1000、
    /// `RM_DURACHANGE`（千位变化）+ 53 + 绿色 SysMsg。
    ///
    /// 红检：把 `>` 改成 `>=` ⇒ 「恰好 60s 不复活」用例必红；删 `e.hp = e.max_hp` ⇒ HP 断言必红。
    #[test]
    fn p32_revives_hp_zero_player_and_damages_ring() {
        let catalog = p32_catalog();
        let now = 1_000_000i64;
        let (mut world, mut sessions, online, gates, mut rx, actor) = p32_fixture(5000, 0);
        drain_player_revival(
            &mut world,
            &mut sessions,
            &online,
            &gates,
            &catalog,
            now,
            60_000,
            0xDB,
            0xFF,
            b"revived",
            12,
        );
        let e = world.entities.get(actor).unwrap();
        assert_eq!(e.hp, 100, "HP=MaxHP");
        assert_eq!(e.max_hp, 100);
        assert_eq!(e.revival_tick, now, "RevivalTick=now");
        let sg = sessions.get("p32a").unwrap();
        assert_eq!(
            sg.use_items[game_svr::ability::SLOT_RING_L]
                .as_ref()
                .unwrap()
                .dura,
            4000,
            "耐久 -1000"
        );
        assert_eq!(
            take_frame_idents(&mut rx),
            vec![
                mir2_protocol::messages::SM_HEALTHSPELLCHANGED,
                mir2_protocol::messages::SM_DURACHANGE,
                mir2_protocol::messages::SM_SYSMESSAGE,
            ],
            "帧序：53(68) → SM_DURACHANGE(141) → SM_SYSMESSAGE(252)"
        );
    }

    /// **PL-1 复验 F2（复现）**：P32 的 53 帧必须走生产选路
    /// [`game_svr::smframe::sm_healthspellchanged_frame`]——默认（冻结客户端布局）
    /// 追加 12B `TCharDesc` 尾；`sm_healthspellchanged` 是 oracle header-only，仅供
    /// `MIR2_CLIENT_ABILITY_LAYOUT=0` 对拍路径使用。
    /// 牙：默认布局下断言 53 tail 长度 = 12 且可按客户端口径回读 HP/MP/MaxHP。
    #[test]
    fn p32_healthspellchanged_uses_production_layout_with_tchardesc() {
        let catalog = p32_catalog();
        let (mut world, mut sessions, online, gates, mut rx, _actor) = p32_fixture(5000, 0);
        drain_player_revival(
            &mut world,
            &mut sessions,
            &online,
            &gates,
            &catalog,
            1_000_000,
            60_000,
            0xDB,
            0xFF,
            b"revived",
            12,
        );
        let mut body = None;
        while let Ok(SimToGate::SendFrame { body: b, .. }) = rx.try_recv() {
            if u16::from_le_bytes([b[4], b[5]]) == mir2_protocol::messages::SM_HEALTHSPELLCHANGED {
                body = Some(b);
            }
        }
        let body = body.expect("复活必须发 53");
        if game_svr::smframe::client_layout_enabled() {
            let desc = mir2_protocol::edcode::decode(&body[12..]);
            assert_eq!(desc.len(), 12, "冻结客户端布局：TCharDesc = 3 × i32 = 12B");
            let at = |o: usize| i32::from_le_bytes(desc[o..o + 4].try_into().unwrap());
            assert_eq!(at(0), 100, "Feature = HP（复活后 = MaxHP）");
            assert_eq!(at(4), 0, "Status = MP");
            assert_eq!(at(8), 100, "StatusEx = MaxHP");
        } else {
            assert_eq!(
                body.len(),
                12,
                "oracle 对拍路径（MIR2_CLIENT_ABILITY_LAYOUT=0）header-only"
            );
        }
    }

    /// **PL-1 复验 F3（复现）**：破零戒指的 `SM_DELITEM` 载荷 `Dura` 必须是 **0**。
    /// oracle `PlayObject.cs:5371-5377` 先写 `UseItems[i].Dura = 0` 再 `SendDelItems`
    /// （`PlayObject.Base.cs:1654-1658` 取 `userItem.Dura`），Index 保留到发帧后。
    /// 牙：解码载荷断言 `Dura == 0`（用例 Dura=1000），`MakeIndex` 仍按实例回读。
    #[test]
    fn p32_sm_delitem_payload_carries_zero_dura() {
        let catalog = p32_catalog();
        let (mut world, mut sessions, online, gates, mut rx, _actor) = p32_fixture(1000, 0);
        drain_player_revival(
            &mut world,
            &mut sessions,
            &online,
            &gates,
            &catalog,
            2_000_000,
            60_000,
            0xDB,
            0xFF,
            b"revived",
            12,
        );
        let mut payload = None;
        while let Ok(SimToGate::SendFrame { body, .. }) = rx.try_recv() {
            if u16::from_le_bytes([body[4], body[5]]) == mir2_protocol::messages::SM_DELITEM {
                payload = Some(body[12..].to_vec());
            }
        }
        let raw = mir2_protocol::edcode::decode(&payload.expect("Dura==1000 ⇒ 必发 SM_DELITEM"));
        assert_eq!(raw.len(), 124, "ClientItem 定长 124B");
        assert_eq!(
            u16::from_le_bytes([raw[104], raw[105]]),
            0,
            "SendDelItems 的 Dura 取破零后的 0（oracle 先赋值再发帧）"
        );
        assert_eq!(
            &raw[100..104],
            &77i32.to_le_bytes(),
            "MakeIndex 仍按实例编码（Index 保留到发帧后）"
        );
    }

    /// **PL-1 / P32 判据 2（三档耐久边界，ushort 回绕）**：
    /// `1000 ⇒ 0` 才移除 + `SM_DELITEM`；`999 ⇒ 65535` 留位；`0 ⇒ 64536` 留位。
    ///
    /// 红检：把 `wrapping_sub` 改成 `saturating_sub` ⇒ 999/0 两档的耐久断言必红；
    /// 把 `n_dura == 0` 改成 `n_dura <= 1000` ⇒ 999 档的 `index==0` 必红。
    #[test]
    fn p32_ring_dura_ushort_wrap_boundaries() {
        let catalog = p32_catalog();
        let cases: [(u16, u16, bool); 3] =
            [(1000, 0, true), (999, 65535, false), (0, 64536, false)];
        for (dura_in, dura_out, broken) in cases {
            let now = 2_000_000i64;
            let (mut world, mut sessions, online, gates, mut rx, _actor) = p32_fixture(dura_in, 0);
            drain_player_revival(
                &mut world,
                &mut sessions,
                &online,
                &gates,
                &catalog,
                now,
                60_000,
                0xDB,
                0xFF,
                b"revived",
                12,
            );
            let sg = sessions.get("p32a").unwrap();
            let slot = sg.use_items[game_svr::ability::SLOT_RING_L]
                .as_ref()
                .unwrap();
            assert_eq!(slot.dura, dura_out, "Dura {dura_in} ⇒ {dura_out}");
            assert_eq!(
                slot.index == 0,
                broken,
                "Dura {dura_in} ⇒ broken={broken}（ushort 回绕后 == 0 才移除）"
            );
            // **复验 F7**：精确帧序列（不是 `contains`）——Dura==1000 破零多一条即时
            // `SM_DELITEM`；642 每次都**恰一条**（`tDura != Round(nDura/1000)` 对本用例恒真），
            // 重复入队必须在这里判红（旧 `contains` 口径对「多发 642」是假绿）。
            let mut expected = Vec::new();
            if broken {
                expected.push(mir2_protocol::messages::SM_DELITEM);
            }
            expected.push(mir2_protocol::messages::SM_HEALTHSPELLCHANGED);
            expected.push(mir2_protocol::messages::SM_DURACHANGE);
            expected.push(mir2_protocol::messages::SM_SYSMESSAGE);
            assert_eq!(
                take_frame_idents(&mut rx),
                expected,
                "Dura {dura_in}: 精确帧序（SM_DELITEM 仅破零；642 恰一条；53 → 642 → 252 按 ident 优先级）"
            );
        }
    }

    /// **PL-1 / P32 判据 3（门）**：严格 `>`、`Death`、`LastHiter` 三态。
    ///
    /// 红检：`>`→`>=` ⇒ 「恰好 60s」必红；去掉 `un_revival` 门 ⇒ 玩家命中者用例必红。
    #[test]
    fn p32_revival_gates_strict_gt_death_and_last_hiter() {
        let catalog = p32_catalog();
        let now = 3_000_000i64;
        // 恰好 60s（不复活）。
        let (mut world, mut sessions, online, gates, mut rx, actor) =
            p32_fixture(5000, now - 60_000);
        drain_player_revival(
            &mut world,
            &mut sessions,
            &online,
            &gates,
            &catalog,
            now,
            60_000,
            0xDB,
            0xFF,
            b"revived",
            12,
        );
        assert_eq!(
            world.entities.get(actor).unwrap().hp,
            0,
            "严格 >：恰好 60s 不复活"
        );
        assert!(take_frame_idents(&mut rx).is_empty());

        // Death ⇒ 不复活。
        let (mut world, mut sessions, online, gates, mut rx, actor) = p32_fixture(5000, 0);
        world.entities.get_mut(actor).unwrap().death = true;
        drain_player_revival(
            &mut world,
            &mut sessions,
            &online,
            &gates,
            &catalog,
            now,
            60_000,
            0xDB,
            0xFF,
            b"revived",
            12,
        );
        assert_eq!(world.entities.get(actor).unwrap().hp, 0, "Death ⇒ 不复活");
        assert!(take_frame_idents(&mut rx).is_empty());

        // LastHiter = 怪物 ⇒ 不复活；= 玩家且 UnRevival ⇒ 不复活；= 玩家且 !UnRevival ⇒ 复活。
        for (race, un_revival, expect_revive) in
            [(1u8, false, false), (0u8, true, false), (0, false, true)]
        {
            let (mut world, mut sessions, online, gates, mut rx, actor) = p32_fixture(5000, 0);
            let mut hiter = mir2_world::Entity::new(0, "hiter".to_string(), 3, 3);
            hiter.race = race;
            hiter.un_revival = un_revival;
            let hid = world.entities.alloc_id();
            hiter.id = hid;
            world.entities.insert(hiter);
            world.entities.get_mut(actor).unwrap().last_hiter = Some(hid);
            drain_player_revival(
                &mut world,
                &mut sessions,
                &online,
                &gates,
                &catalog,
                now,
                60_000,
                0xDB,
                0xFF,
                b"revived",
                12,
            );
            let revived = world.entities.get(actor).unwrap().hp > 0;
            assert_eq!(
                revived, expect_revive,
                "race={race} un_revival={un_revival} ⇒ revived={expect_revive}"
            );
            if expect_revive {
                assert!(!take_frame_idents(&mut rx).is_empty());
            } else {
                assert!(take_frame_idents(&mut rx).is_empty());
            }
        }
    }

    /// **Lane B / B6**：会话内 `RecalcAbilitys()` 的 `FlameRing` **粘滞**、`RecoveryRing` **每轮重置**。
    ///
    /// 牙 4：把 `flame_ring_in` 当「每轮本次命中」传（第 2 轮传 false）⇒ 火球被删、本用例红；
    /// 把 `recovery_ring` 做成粘滞（第 2 轮仍传 true）⇒ 治愈不被删、本用例红。
    #[test]
    fn lane_b_session_recalc_flame_sticky_and_recovery_resets() {
        let mut catalog = game_svr::ability::StdItemCatalog::new();
        catalog.insert(
            1151,
            mir2_data::StdItem {
                name: "FireRing".into(),
                std_mode: 22,
                shape: 115,
                dura_max: 5000,
                ..mir2_data::StdItem::default()
            },
        );
        catalog.insert(
            1152,
            mir2_data::StdItem {
                name: "HealRing".into(),
                std_mode: 22,
                shape: 116,
                dura_max: 5000,
                ..mir2_data::StdItem::default()
            },
        );
        let table = magics::MagicTable::new(vec![
            mir2_data::MagicInfo {
                magic_id: 1,
                magic_name: "火球术".into(),
                ..mir2_data::MagicInfo::default()
            },
            mir2_data::MagicInfo {
                magic_id: 2,
                magic_name: "治愈术".into(),
                ..mir2_data::MagicInfo::default()
            },
        ]);
        let cfg = MagicCfg {
            table: &table,
            fire_ball_skill: "火球术",
            heal_skill: "治愈术",
        };
        let ring = |index: u16| {
            Some(game_svr::bag::BagItem {
                make_index: 1,
                index,
                dura: 100,
                dura_max: 100,
                desc: [0u8; 14],
            })
        };
        let magic = |id: u16| {
            Some(record::MagicRcd {
                mag_idx: id,
                level: 0,
                magic_key: 0,
                tran_point: 0,
            })
        };
        let mut saved = SavedHuman {
            account: "a".into(),
            record: record::PlayerRecord::default(),
            enter_map: "0".into(),
        };
        saved.record.data.magic = Some(vec![magic(1), magic(2)]);
        let mut sg = test_session_ground(9);
        sg.equip.job = 0; // 战士：无火球戒指时 `DelItemSkill(1)` 会删火球

        // 第 1 轮：两枚戒指都戴（Dura>0）⇒ 两块都命中；技能已在列表 ⇒ 无 210。
        sg.use_items[game_svr::ability::SLOT_RING_L] = ring(1151);
        sg.use_items[game_svr::ability::SLOT_RING_R] = ring(1152);
        let eff = recalc_session_ability(
            &mut sg,
            &catalog,
            None,
            Some(MagicRecalc {
                saved: &mut saved,
                cfg,
                flame_ring_in: false,
            }),
        );
        assert!(eff.magic_events.is_empty());
        assert!(eff.flame_ring && eff.recovery_ring);
        let mut flame = eff.flame_ring; // `entity.flame_ring |= effect.flame_ring`
        assert_eq!(saved.record.data.magic, Some(vec![magic(1), magic(2)]));

        // 第 2 轮：两枚都脱下。FlameRing 粘滞（历史 true）⇒ 火球不删；
        // RecoveryRing 本轮 false ⇒ 立即删治愈并发 212。
        sg.use_items[game_svr::ability::SLOT_RING_L] = None;
        sg.use_items[game_svr::ability::SLOT_RING_R] = None;
        let eff = recalc_session_ability(
            &mut sg,
            &catalog,
            None,
            Some(MagicRecalc {
                saved: &mut saved,
                cfg,
                flame_ring_in: flame,
            }),
        );
        assert_eq!(
            eff.magic_events,
            vec![smframe::MagicEvent::Del { mag_idx: 2 }]
        );
        flame |= eff.flame_ring;
        assert_eq!(
            saved.record.data.magic,
            Some(vec![magic(1)]),
            "火球保留（粘滞）、治愈删除（每轮重置）"
        );

        // 第 3 轮：仍无戒指且粘滞仍真 ⇒ 火球依旧保留、无事件。
        let eff = recalc_session_ability(
            &mut sg,
            &catalog,
            None,
            Some(MagicRecalc {
                saved: &mut saved,
                cfg,
                flame_ring_in: flame,
            }),
        );
        assert!(eff.magic_events.is_empty());
        assert_eq!(saved.record.data.magic, Some(vec![magic(1)]));

        // 下次登录 = 新 PlayObject（flame_ring_in=false）⇒ 才删火球并发 212。
        let eff = recalc_session_ability(
            &mut sg,
            &catalog,
            None,
            Some(MagicRecalc {
                saved: &mut saved,
                cfg,
                flame_ring_in: false,
            }),
        );
        assert_eq!(
            eff.magic_events,
            vec![smframe::MagicEvent::Del { mag_idx: 1 }]
        );
        assert_eq!(saved.record.data.magic, Some(vec![]));

        // 牙 3：Dura==0 的戒指不置标志 ⇒ 等同没戴。
        sg.use_items[game_svr::ability::SLOT_RING_L] = Some(game_svr::bag::BagItem {
            make_index: 1,
            index: 1151,
            dura: 0,
            dura_max: 100,
            desc: [0u8; 14],
        });
        let eff = recalc_session_ability(
            &mut sg,
            &catalog,
            None,
            Some(MagicRecalc {
                saved: &mut saved,
                cfg,
                flame_ring_in: false,
            }),
        );
        assert!(!eff.flame_ring, "Dura==0 不置 FlameRing");
    }

    /// **Lane B / B1**：会话内第一次戴上 115 火球戒指 ⇒ 追加 `Level=1/Key=0/TranPoint=0`
    /// 并发 210（事件携带模板 `Def`）；211/存档同源记录立即可见。
